#!/usr/bin/env python3
"""
install_condensate_lab.py  -  loguebio: put the real Condensate Lab into
apps/condensate-lab (it holds only the create-next-app starter), plus the new
shared settings package packages/access (@repo/access).

Rebuilt from the July chat and your backup (simulation, renderer, page), with the
physics retuned and tested, and the accessibility work the design rules call for.

Edits (ids for --skip):
  access-package  packages/access/*  (new: one settings source, palette, announcer
                  and settings form for every tool; settings carry across tools)
  app-files       apps/condensate-lab/components/*, lib/*  (new: the app)
  page            apps/condensate-lab/app/page.tsx  (replaces the starter page)
  styles          apps/condensate-lab/app/globals.css  (replaces the starter styles)
  layout-import   app/layout.tsx: import the settings boot script
  layout-title    app/layout.tsx: tab title "Condensate Lab" instead of "Create Next App"
  layout-head     app/layout.tsx: apply saved settings before first paint
  deps            apps/condensate-lab/package.json: add "@repo/access": "*"
  check-types     (optional) apps/condensate-lab/package.json: "check-types" script
  readme          apps/condensate-lab/README.md  (replaces the create-next-app README)
  root-readme     README.md: list packages/access under "Repository layout"

Usage (run from anywhere inside the repo, or pass --path <repo root>):
  python3 install_condensate_lab.py --dry-run
  python3 install_condensate_lab.py --diff
  python3 install_condensate_lab.py
  npm install
  python3 install_condensate_lab.py --revert

Needs packages/suite (from suite_nav.py) already in place. Every edit is checked
in memory first; a missing or repeated anchor, or a page/styles/README that is no
longer the starter, aborts with exit 1 and writes nothing. Re-running skips what
is already done. Changed files are backed up as <file>.bak-<timestamp>.
"""
import argparse
import difflib
import json
import os
import sys
import time

APP = "apps/condensate-lab"
STATE = ".install-condensate-lab-script.json"
FILES = {
    "apps/condensate-lab/README.md": "# Condensate Lab\n\nWatch proteins and RNA gather into droplets (liquid-liquid phase separation), the\nway cells build compartments without walls. Change stickiness, temperature,\nconcentration, pH and crowding; bleach a droplet to test whether it is liquid\n(FRAP); turn on disease mode to watch droplets harden; find the threshold where\ndroplets start; compare with textbook Flory-Huggins theory or your own FRAP data.\n\nA simplified 2D teaching model with arbitrary units. The app lists what it leaves\nout under \"About this model\".\n\n```bash\nnpm run dev -w apps/condensate-lab      # from the repo root\n```\n\n## Layout\n\n```\napp/            page, layout (applies saved settings before first paint), styles\ncomponents/     CondensateLab (composition), SimCanvas, Controls, Playback, Status,\n                Panels (Droplets, Over time, FRAP, Threshold, Theory, Log), Guide,\n                Dialogs, LineChart, SortableTable, Tabs\nlib/sim/        engine (Brownian dynamics, clusters, hardening, bleaching), params,\n                frap (fit, CSV import), floryHuggins, rng\nlib/store.ts    the one state model every view reads and every control writes\nlib/describe.ts the text versions of the picture (summary, announcements, alt text)\nlib/export.ts   CSV, JSON and SVG exports, each labelled as simulated data\nlib/content.ts  presets, guide, glossary, model limits\n```\n\nSettings (theme, contrast, palette, text size, motion, autoplay, simpler interface,\nreading time, sound, vibration) come from the shared `@repo/access` package, so they\ncarry across every LogueBio tool.\n\n## Every route reaches the same result\n\n- **Picture:** shapes as well as colours (protein circles, RNA triangles, solid\n  squares, bleached hollow), numbered droplet outlines.\n- **Text:** a live summary under the picture, a sortable droplets table, a log of\n  every change, and a table under each chart.\n- **Keyboard:** in the picture, arrows move between droplets, B bleaches, Space\n  plays or pauses; in charts, arrows read each point.\n- **Screen readers:** throttled spoken updates (they can be turned off), droplets\n  announced with size, contents, state and position.\n- **Sound and touch (optional):** tones for changes, a tone whose pitch follows\n  the share of protein in droplets, vibration where the device supports it.\n- **Motion:** nothing starts by itself unless the settings allow it; pause, step,\n  jump ahead, speed, and \"picture updates once a second / only when paused\".\n",
    "apps/condensate-lab/app/globals.css": "@import \"tailwindcss\";\n\n/*\n * Condensate Lab. Colours come from tokens that change with the person's\n * settings (data attributes set by @repo/access on <html>):\n *   data-theme light|dark, data-contrast normal|high, data-motion reduce|allow,\n *   data-spacing normal|wide, data-simpler, --access-text-scale.\n * Every text/background pair below meets WCAG AA (4.5:1); high contrast meets AAA.\n */\n\n:root {\n  --bg: #f4f2ec;\n  --surface: #fffdf8;\n  --canvas: #fbfaf7;\n  --ink: #1a1d21;\n  --muted: #4b5563;\n  --line: #c9c5b9;\n  --grid: #e5e3dc;\n  --accent: #0b5fa5;\n  --accent-ink: #ffffff;\n  --focus: #b45309;\n  --note-bg: #eef4fb;\n  --note-line: #9bbbe0;\n  --phase-mixed: #4b5563;\n  --phase-borderline: #8a5a00;\n  --phase-separated: #0b5fa5;\n  --radius: 10px;\n  --border-w: 1px;\n  --background: var(--bg);\n  --foreground: var(--ink);\n  color-scheme: light;\n}\n\n:root[data-theme=\"dark\"] {\n  --bg: #111418;\n  --surface: #1a1f25;\n  --canvas: #0d1013;\n  --ink: #eceff3;\n  --muted: #b3bcc8;\n  --line: #3b4450;\n  --grid: #222831;\n  --accent: #7cc0ff;\n  --accent-ink: #0b1622;\n  --focus: #ffb454;\n  --note-bg: #16263a;\n  --note-line: #33557c;\n  --phase-mixed: #b3bcc8;\n  --phase-borderline: #f2c14e;\n  --phase-separated: #7cc0ff;\n  color-scheme: dark;\n}\n\n:root[data-contrast=\"high\"] {\n  --bg: #ffffff;\n  --surface: #ffffff;\n  --canvas: #ffffff;\n  --ink: #000000;\n  --muted: #1f1f1f;\n  --line: #000000;\n  --grid: #b0b0b0;\n  --accent: #0033cc;\n  --accent-ink: #ffffff;\n  --focus: #b30000;\n  --note-bg: #ffffff;\n  --note-line: #000000;\n  --phase-mixed: #000000;\n  --phase-borderline: #6b3b00;\n  --phase-separated: #0033cc;\n  --border-w: 2px;\n}\n\n:root[data-contrast=\"high\"][data-theme=\"dark\"] {\n  --bg: #000000;\n  --surface: #000000;\n  --canvas: #000000;\n  --ink: #ffffff;\n  --muted: #f0f0f0;\n  --line: #ffffff;\n  --grid: #555555;\n  --accent: #66ccff;\n  --accent-ink: #000000;\n  --focus: #ffd400;\n  --note-bg: #000000;\n  --note-line: #ffffff;\n  --phase-mixed: #ffffff;\n  --phase-borderline: #ffd400;\n  --phase-separated: #66ccff;\n}\n\n@theme inline {\n  --color-background: var(--background);\n  --color-foreground: var(--foreground);\n  --font-sans: var(--font-geist-sans);\n  --font-mono: var(--font-geist-mono);\n}\n\nhtml {\n  font-size: calc(100% * var(--access-text-scale, 1));\n}\n\nbody {\n  background: var(--bg);\n  color: var(--ink);\n  font-family: var(--font-geist-sans), system-ui, sans-serif;\n  line-height: 1.55;\n}\n\n:root[data-spacing=\"wide\"] body {\n  letter-spacing: 0.06em;\n  word-spacing: 0.16em;\n  line-height: 1.9;\n}\n:root[data-spacing=\"wide\"] p {\n  margin-bottom: 1.2em;\n}\n\n:root[data-motion=\"reduce\"] *,\n:root[data-motion=\"reduce\"] *::before,\n:root[data-motion=\"reduce\"] *::after {\n  animation-duration: 0.001ms !important;\n  animation-iteration-count: 1 !important;\n  transition-duration: 0.001ms !important;\n  scroll-behavior: auto !important;\n}\n\n*:focus-visible {\n  outline: 3px solid var(--focus);\n  outline-offset: 2px;\n}\n\n.visually-hidden {\n  position: absolute !important;\n  width: 1px;\n  height: 1px;\n  padding: 0;\n  margin: -1px;\n  overflow: hidden;\n  clip: rect(0 0 0 0);\n  white-space: nowrap;\n  border: 0;\n}\n\n.skip-link {\n  position: absolute;\n  left: 12px;\n  top: -100px;\n  z-index: 100;\n  padding: 10px 16px;\n  background: var(--accent);\n  color: var(--accent-ink);\n  border-radius: 8px;\n  font-weight: 650;\n}\n.skip-link:focus {\n  top: 12px;\n}\n\n.muted {\n  color: var(--muted);\n}\n.mono {\n  font-family: var(--font-geist-mono), ui-monospace, monospace;\n  font-variant-numeric: tabular-nums;\n}\n.label {\n  font-weight: 650;\n  margin-right: 0.35em;\n}\n\n/* ─── Layout ─────────────────────────────────────────────────────────────── */\n\n.app {\n  width: 100%;\n  max-width: 1480px;\n  margin: 0 auto;\n  padding: 16px 16px 96px;\n}\n\n.app-header {\n  display: flex;\n  flex-wrap: wrap;\n  gap: 12px 24px;\n  align-items: flex-end;\n  justify-content: space-between;\n  padding: 8px 0 16px;\n  border-bottom: var(--border-w) solid var(--line);\n  margin-bottom: 16px;\n}\n.brand h1 {\n  font-size: 1.9rem;\n  font-weight: 750;\n  letter-spacing: -0.01em;\n  line-height: 1.15;\n}\n.tagline {\n  color: var(--muted);\n  max-width: 60ch;\n}\n.header-actions {\n  display: flex;\n  flex-wrap: wrap;\n  gap: 8px;\n}\n\n.layout {\n  display: grid;\n  gap: 16px;\n  grid-template-columns: minmax(0, 1fr);\n  grid-template-areas: \"stage\" \"controls\" \"results\";\n}\n.stage {\n  grid-area: stage;\n}\n.controls {\n  grid-area: controls;\n}\n.results {\n  grid-area: results;\n}\n\n@media (min-width: 960px) {\n  .layout {\n    grid-template-columns: minmax(0, 1.7fr) minmax(300px, 1fr);\n    grid-template-areas: \"stage controls\" \"results results\";\n    align-items: start;\n  }\n}\n@media (min-width: 1680px) {\n  .layout {\n    grid-template-columns: minmax(0, 1.5fr) minmax(320px, 0.75fr) minmax(480px, 1fr);\n    grid-template-areas: \"stage controls results\";\n  }\n}\n\n/* Large text: fewer, wider columns (width breakpoints don't see the text size) */\n:root[data-text-size=\"125\"] .layout {\n  grid-template-columns: minmax(0, 1fr);\n  grid-template-areas: \"stage\" \"controls\" \"results\";\n}\n@media (min-width: 1280px) {\n  :root[data-text-size=\"125\"] .layout {\n    grid-template-columns: minmax(0, 1.6fr) minmax(320px, 1fr);\n    grid-template-areas: \"stage controls\" \"results results\";\n  }\n}\n:root[data-text-size=\"150\"] .layout,\n:root[data-text-size=\"200\"] .layout {\n  grid-template-columns: minmax(0, 1fr);\n  grid-template-areas: \"stage\" \"controls\" \"results\";\n}\n\n.panel {\n  background: var(--surface);\n  border: var(--border-w) solid var(--line);\n  border-radius: var(--radius);\n  padding: 16px;\n  min-width: 0;\n}\n.panel h2 {\n  font-size: 1.2rem;\n  font-weight: 700;\n  margin-bottom: 10px;\n}\n.panel h3 {\n  font-size: 1.05rem;\n  font-weight: 700;\n  margin: 16px 0 6px;\n}\n.panel p {\n  margin-bottom: 0.6em;\n}\n.about {\n  margin-top: 16px;\n}\n.about ul {\n  list-style: disc;\n  padding-left: 1.4em;\n  margin-bottom: 10px;\n}\n.about li {\n  margin-bottom: 4px;\n}\n\n/* ─── Simulation picture ─────────────────────────────────────────────────── */\n\n.figure-wrap {\n  border: var(--border-w) solid var(--line);\n  border-radius: 8px;\n  overflow: hidden;\n  background: var(--canvas);\n}\n.sim-canvas {\n  display: block;\n  width: 100%;\n  aspect-ratio: 3 / 2;\n  touch-action: manipulation;\n  cursor: pointer;\n}\n.sim-canvas:focus-visible {\n  outline-offset: -3px;\n}\n.hint {\n  font-size: 0.9rem;\n  color: var(--muted);\n  margin: 8px 0;\n}\n\n.legend {\n  display: flex;\n  flex-wrap: wrap;\n  gap: 6px 16px;\n  margin: 8px 0;\n  font-size: 0.92rem;\n}\n.legend li {\n  display: inline-flex;\n  align-items: center;\n  gap: 6px;\n}\n\n/* ─── Buttons and controls ───────────────────────────────────────────────── */\n\n.button {\n  display: inline-flex;\n  align-items: center;\n  justify-content: center;\n  gap: 8px;\n  min-height: 44px;\n  min-width: 44px;\n  padding: 8px 14px;\n  border-radius: 8px;\n  border: var(--border-w) solid var(--line);\n  background: var(--surface);\n  color: var(--ink);\n  font: inherit;\n  font-weight: 600;\n  cursor: pointer;\n  text-align: center;\n}\n.button:hover {\n  border-color: var(--ink);\n}\n.button.primary {\n  background: var(--accent);\n  border-color: var(--accent);\n  color: var(--accent-ink);\n}\n.button.secondary {\n  background: transparent;\n}\n.button.small {\n  min-height: 44px;\n  padding: 6px 10px;\n  font-size: 0.92rem;\n}\n.button[aria-disabled=\"true\"],\n.button:disabled {\n  opacity: 0.55;\n  cursor: not-allowed;\n}\n.button[aria-pressed=\"true\"] {\n  border-width: 2px;\n  border-color: var(--accent);\n}\n.glyph {\n  font-size: 0.85em;\n}\n.button-row {\n  display: flex;\n  flex-wrap: wrap;\n  gap: 8px;\n  margin: 10px 0;\n}\n\n.icon-button {\n  flex: none;\n  width: 44px;\n  height: 44px;\n  border-radius: 8px;\n  border: var(--border-w) solid var(--line);\n  background: var(--surface);\n  color: var(--ink);\n  font-size: 1.3rem;\n  font-weight: 700;\n  line-height: 1;\n  cursor: pointer;\n}\n.icon-button:disabled {\n  opacity: 0.45;\n  cursor: not-allowed;\n}\n\n.control {\n  margin-bottom: 14px;\n}\n.control-head {\n  display: flex;\n  justify-content: space-between;\n  align-items: baseline;\n  gap: 8px;\n}\n.control-label {\n  font-weight: 650;\n}\n.control-value {\n  font-family: var(--font-geist-mono), ui-monospace, monospace;\n  font-variant-numeric: tabular-nums;\n}\n.control-row {\n  display: flex;\n  align-items: center;\n  gap: 8px;\n}\n.control-row input[type=\"range\"] {\n  flex: 1;\n  min-width: 0;\n  height: 44px;\n  accent-color: var(--accent);\n  cursor: pointer;\n}\n.control-help {\n  font-size: 0.9rem;\n  color: var(--muted);\n  margin-top: 2px;\n}\n\n.select {\n  min-height: 44px;\n  padding: 6px 10px;\n  border-radius: 8px;\n  border: var(--border-w) solid var(--line);\n  background: var(--surface);\n  color: var(--ink);\n  font: inherit;\n  max-width: 100%;\n}\n.control .select {\n  width: 100%;\n  margin-top: 4px;\n}\n\n.switch {\n  display: flex;\n  align-items: center;\n  gap: 10px;\n  min-height: 44px;\n  cursor: pointer;\n  position: relative;\n}\n.switch input {\n  position: absolute;\n  opacity: 0;\n  width: 52px;\n  height: 30px;\n  margin: 0;\n  cursor: pointer;\n}\n.switch-track {\n  flex: none;\n  width: 52px;\n  height: 30px;\n  border-radius: 999px;\n  border: 2px solid var(--muted);\n  background: var(--surface);\n  position: relative;\n}\n.switch-thumb {\n  position: absolute;\n  top: 3px;\n  left: 3px;\n  width: 20px;\n  height: 20px;\n  border-radius: 50%;\n  background: var(--muted);\n  transition: transform 0.15s;\n}\n.switch input:checked + .switch-track {\n  background: var(--accent);\n  border-color: var(--accent);\n}\n.switch input:checked + .switch-track .switch-thumb {\n  transform: translateX(22px);\n  background: var(--accent-ink);\n}\n.switch input:focus-visible + .switch-track {\n  outline: 3px solid var(--focus);\n  outline-offset: 2px;\n}\n.switch-state {\n  margin-left: auto;\n  font-weight: 650;\n  color: var(--muted);\n}\n\n.check {\n  display: inline-flex;\n  align-items: center;\n  gap: 10px;\n  min-height: 44px;\n  cursor: pointer;\n}\n.check input {\n  width: 22px;\n  height: 22px;\n  accent-color: var(--accent);\n}\n\n.radio-group {\n  display: flex;\n  flex-wrap: wrap;\n  gap: 8px;\n  border: var(--border-w) solid var(--line);\n  border-radius: 8px;\n  padding: 8px 12px 12px;\n  margin: 10px 0;\n}\n.radio-group legend {\n  font-weight: 650;\n  padding: 0 4px;\n}\n.radio {\n  display: inline-flex;\n  align-items: center;\n  gap: 8px;\n  min-height: 44px;\n  padding: 4px 12px 4px 8px;\n  border: var(--border-w) solid var(--line);\n  border-radius: 8px;\n  cursor: pointer;\n}\n.radio input {\n  width: 20px;\n  height: 20px;\n  accent-color: var(--accent);\n}\n\n.inline-field {\n  display: inline-flex;\n  align-items: center;\n  gap: 8px;\n}\n.inline-field label {\n  font-weight: 600;\n}\n\n.file-field {\n  position: relative;\n  display: inline-block;\n  margin: 6px 0;\n}\n.file-input {\n  position: absolute;\n  inset: 0;\n  opacity: 0;\n  width: 100%;\n  cursor: pointer;\n}\n.file-field:focus-within .button {\n  outline: 3px solid var(--focus);\n  outline-offset: 2px;\n}\n\n.more {\n  border-top: var(--border-w) solid var(--line);\n  padding-top: 10px;\n}\n\n/* ─── Playback and status ────────────────────────────────────────────────── */\n\n.playback {\n  margin: 10px 0;\n}\n.playback-row {\n  display: flex;\n  flex-wrap: wrap;\n  align-items: center;\n  gap: 8px 16px;\n  margin-bottom: 8px;\n}\n.playback-row:first-child {\n  gap: 8px;\n}\n.play {\n  min-width: 104px;\n}\n.time {\n  font-weight: 600;\n  margin: 0 !important;\n}\n.time-unit {\n  font-weight: 400;\n  color: var(--muted);\n  font-size: 0.9rem;\n}\n\n.status {\n  border-top: var(--border-w) solid var(--line);\n  padding-top: 10px;\n  margin-top: 6px;\n}\n.status-phase {\n  display: flex;\n  flex-wrap: wrap;\n  align-items: center;\n  gap: 8px 16px;\n}\n.status-stats {\n  display: inline-flex;\n  flex-wrap: wrap;\n  gap: 4px 16px;\n}\n.badge {\n  display: inline-flex;\n  align-items: center;\n  gap: 6px;\n  padding: 3px 10px;\n  border-radius: 999px;\n  border: 2px solid currentColor;\n  font-weight: 700;\n}\n.badge-glyph {\n  letter-spacing: -0.1em;\n}\n.phase-mixed {\n  color: var(--phase-mixed);\n}\n.phase-borderline {\n  color: var(--phase-borderline);\n}\n.phase-separated {\n  color: var(--phase-separated);\n}\n.status-text {\n  font-size: 1.02rem;\n}\n.status-latest {\n  font-size: 0.95rem;\n}\n\n.selection {\n  border-top: var(--border-w) solid var(--line);\n  margin-top: 10px;\n  padding-top: 4px;\n}\n\n.note {\n  background: var(--note-bg);\n  border: var(--border-w) solid var(--note-line);\n  border-radius: 8px;\n  padding: 8px 12px;\n}\n\n/* ─── Guide ──────────────────────────────────────────────────────────────── */\n\n.guide {\n  background: var(--note-bg);\n  border: var(--border-w) solid var(--note-line);\n  border-radius: var(--radius);\n  padding: 14px 16px;\n  margin-bottom: 16px;\n  max-width: 78ch;\n}\n.guide-top {\n  display: flex;\n  justify-content: space-between;\n  align-items: center;\n  gap: 12px;\n}\n.guide-kicker {\n  font-size: 0.95rem;\n  font-weight: 700;\n  text-transform: uppercase;\n  letter-spacing: 0.06em;\n}\n.guide-title {\n  font-size: 1.3rem;\n  font-weight: 750;\n  margin: 6px 0 8px;\n}\n.guide p {\n  margin-bottom: 0.6em;\n}\n.guide-look {\n  border-left: 4px solid var(--accent);\n  padding-left: 10px;\n}\n\n/* ─── Tabs ───────────────────────────────────────────────────────────────── */\n\n.tablist {\n  display: flex;\n  flex-wrap: wrap;\n  gap: 4px;\n  border-bottom: var(--border-w) solid var(--line);\n  margin-bottom: 12px;\n}\n.tab {\n  min-height: 44px;\n  padding: 8px 12px;\n  border: none;\n  border-bottom: 3px solid transparent;\n  background: none;\n  color: var(--muted);\n  font: inherit;\n  font-weight: 650;\n  cursor: pointer;\n}\n.tab[aria-selected=\"true\"] {\n  color: var(--ink);\n  border-bottom-color: var(--accent);\n}\n.tabpanel:focus-visible {\n  outline-offset: 4px;\n}\n\n/* ─── Tables ─────────────────────────────────────────────────────────────── */\n\n.table-wrap {\n  overflow-x: auto;\n  max-height: 420px;\n  overflow-y: auto;\n  border: var(--border-w) solid var(--line);\n  border-radius: 8px;\n  margin: 8px 0;\n}\n.data-table {\n  width: 100%;\n  border-collapse: collapse;\n  font-size: 0.93rem;\n}\n.data-table caption {\n  text-align: left;\n  font-weight: 650;\n  padding: 8px 10px;\n}\n.data-table th,\n.data-table td {\n  padding: 4px 10px;\n  border-top: 1px solid var(--grid);\n  text-align: left;\n  white-space: nowrap;\n}\n.data-table thead th {\n  position: sticky;\n  top: 0;\n  background: var(--surface);\n  border-bottom: var(--border-w) solid var(--line);\n  padding: 0;\n}\n.data-table tbody th {\n  font-weight: 600;\n}\n.data-table .num {\n  text-align: right;\n  font-variant-numeric: tabular-nums;\n}\n.sort-button {\n  width: 100%;\n  min-height: 44px;\n  padding: 6px 10px;\n  border: none;\n  background: none;\n  color: inherit;\n  font: inherit;\n  font-weight: 650;\n  text-align: inherit;\n  cursor: pointer;\n}\n.sort-mark {\n  color: var(--muted);\n}\n\n/* ─── Charts ─────────────────────────────────────────────────────────────── */\n\n.chart {\n  margin: 12px 0 18px;\n}\n.chart-title {\n  font-weight: 700;\n  margin-bottom: 4px;\n}\n.chart-summary {\n  font-size: 0.95rem;\n}\n.chart-surface {\n  border: var(--border-w) solid var(--line);\n  border-radius: 8px;\n  background: var(--canvas);\n  padding: 4px;\n}\n.chart-svg {\n  display: block;\n  width: 100%;\n  height: auto;\n}\n.chart-readout {\n  font-size: 0.9rem;\n  color: var(--muted);\n  padding: 2px 6px 4px;\n  margin: 0 !important;\n  min-height: 1.6em;\n}\n.numbers summary,\n.about summary {\n  cursor: pointer;\n  min-height: 44px;\n  display: flex;\n  align-items: center;\n  font-weight: 650;\n}\n.empty {\n  color: var(--muted);\n  font-style: italic;\n}\n\n.log {\n  list-style: none;\n  padding: 0;\n  max-height: 420px;\n  overflow-y: auto;\n}\n.log li {\n  padding: 4px 0;\n  border-top: 1px solid var(--grid);\n}\n\n.glossary div {\n  margin-bottom: 8px;\n}\n.glossary dt {\n  font-weight: 700;\n}\n.glossary dd {\n  margin-left: 0;\n}\n\n.action-list li {\n  margin-bottom: 8px;\n}\n\n/* ─── Dialogs ────────────────────────────────────────────────────────────── */\n\n.dialog {\n  width: min(720px, calc(100vw - 24px));\n  max-height: calc(100dvh - 24px);\n  margin: auto;\n  padding: 0;\n  border: var(--border-w) solid var(--line);\n  border-radius: var(--radius);\n  background: var(--surface);\n  color: var(--ink);\n}\n.dialog::backdrop {\n  background: rgb(0 0 0 / 0.55);\n}\n.dialog-head {\n  position: sticky;\n  top: 0;\n  display: flex;\n  justify-content: space-between;\n  align-items: center;\n  gap: 12px;\n  padding: 12px 16px;\n  background: var(--surface);\n  border-bottom: var(--border-w) solid var(--line);\n  z-index: 1;\n}\n.dialog-head h2 {\n  font-size: 1.25rem;\n  font-weight: 750;\n}\n.dialog-body {\n  padding: 16px;\n}\n.dialog-body h3 {\n  font-size: 1.05rem;\n  font-weight: 700;\n  margin: 14px 0 6px;\n}\n.dialog-body p {\n  margin-bottom: 0.6em;\n}\n\n@media print {\n  .header-actions,\n  .playback,\n  .button-row,\n  .skip-link {\n    display: none !important;\n  }\n  .panel {\n    break-inside: avoid;\n  }\n}\n",
    "apps/condensate-lab/app/page.tsx": "import CondensateLab from \"@/components/CondensateLab\";\n\nexport default function Home() {\n  return <CondensateLab />;\n}\n",
    "apps/condensate-lab/components/CondensateLab.tsx": "\"use client\";\n\nimport { announce, applySettingsToDocument, setAnnounceGap, useAccess } from \"@repo/access\";\nimport { useEffect, useRef, useState } from \"react\";\nimport { GLOSSARY, LIMITS } from \"@/lib/content\";\nimport { LabStore } from \"@/lib/store\";\nimport { DataDialog, SettingsDialog } from \"./Dialogs\";\nimport { Controls } from \"./Controls\";\nimport { Guide } from \"./Guide\";\nimport { LabContext } from \"./LabContext\";\nimport { DropletsPanel, FrapPanel, HistoryPanel, LogPanel, ScanPanel, TheoryPanel } from \"./Panels\";\nimport { Playback } from \"./Playback\";\nimport { SimCanvas, type PictureMode } from \"./SimCanvas\";\nimport { SelectionCard, StatusSummary, useChangeChannels } from \"./Status\";\nimport { Tabs } from \"./Tabs\";\nimport { useThemeColors, type ThemeColors } from \"./useTheme\";\n\nfunction Legend({ c }: { c: ThemeColors }) {\n  return (\n    <ul className=\"legend picture-legend\" aria-label=\"Key to the picture\">\n      <li>\n        <svg width=\"18\" height=\"18\" aria-hidden=\"true\">\n          <circle cx=\"9\" cy=\"9\" r=\"6\" fill={c.protein} />\n        </svg>\n        Protein (circle): builds droplets\n      </li>\n      <li>\n        <svg width=\"18\" height=\"18\" aria-hidden=\"true\">\n          <polygon points=\"9,2 16,15 2,15\" fill={c.rna} />\n        </svg>\n        RNA (triangle): joins droplets\n      </li>\n      <li>\n        <svg width=\"18\" height=\"18\" aria-hidden=\"true\">\n          <rect x=\"3\" y=\"3\" width=\"12\" height=\"12\" fill={c.solid} />\n        </svg>\n        Solid protein (square)\n      </li>\n      <li>\n        <svg width=\"18\" height=\"18\" aria-hidden=\"true\">\n          <circle cx=\"9\" cy=\"9\" r=\"6\" fill=\"none\" stroke={c.protein} strokeWidth=\"1.5\" />\n        </svg>\n        Bleached (hollow)\n      </li>\n      <li>\n        <svg width=\"26\" height=\"18\" aria-hidden=\"true\">\n          <circle cx=\"13\" cy=\"9\" r=\"7\" fill=\"none\" stroke={c.muted} strokeWidth=\"1.5\" strokeDasharray=\"3 2\" />\n        </svg>\n        Droplet, numbered\n      </li>\n      <li>\n        <svg width=\"26\" height=\"18\" aria-hidden=\"true\">\n          <circle cx=\"13\" cy=\"9\" r=\"7\" fill=\"none\" stroke={c.accent} strokeWidth=\"3\" />\n        </svg>\n        Selected droplet\n      </li>\n    </ul>\n  );\n}\n\nfunction Lab({ store }: { store: LabStore }) {\n  const access = useAccess();\n  const colors = useThemeColors();\n  const [guideChoice, setGuideChoice] = useState<boolean | null>(null);\n  const [guideStep, setGuideStep] = useState(0);\n  const [tab, setTab] = useState(\"droplets\");\n  const [modeChoice, setModeChoice] = useState<PictureMode | null>(null);\n  const [spoken, setSpoken] = useState(true);\n  const [listen, setListen] = useState(false);\n  const [settingsOpen, setSettingsOpen] = useState(false);\n  const [dataOpen, setDataOpen] = useState(false);\n  const autoplayed = useRef(false);\n\n  const guideOpen = guideChoice ?? access.beginner;\n  const mode: PictureMode = modeChoice ?? (access.reducedMotion ? \"second\" : \"live\");\n\n  useEffect(() => {\n    applySettingsToDocument(access);\n    setAnnounceGap(1800 * access.readingFactor);\n  }, [access]);\n\n  // Start by itself only when the person's settings allow it, and only once.\n  useEffect(() => {\n    if (access.server || autoplayed.current) return;\n    autoplayed.current = true;\n    if (access.autoplay) store.play();\n  }, [access, store]);\n  // Stop work when the page goes away (also lets development's double mount start cleanly).\n  useEffect(\n    () => () => {\n      autoplayed.current = false;\n      store.pause();\n      store.cancelScan(false);\n    },\n    [store],\n  );\n\n  useChangeChannels(spoken, listen);\n\n  const onBleach = () => {\n    const s = store.getSnapshot();\n    if (s.selectedId === null) {\n      announce(\"Select a droplet first: click or tap one, use Next droplet, or focus the picture and use the arrow keys.\", { topic: \"selection\" });\n      return;\n    }\n    const msg = store.bleachDroplet(s.selectedId);\n    announce(msg, { topic: \"frap\" });\n    if (store.getSnapshot().frap?.status === \"recording\") {\n      setTab(\"frap\");\n      if (!store.getSnapshot().running && access.autoplay) store.play();\n      else if (!store.getSnapshot().running) announce(\"Press Play or Jump ahead to watch the recovery.\", { topic: \"frap-hint\" });\n    }\n  };\n\n  const tabs = [\n    { id: \"droplets\", label: \"Droplets\", content: <DropletsPanel /> },\n    { id: \"time\", label: \"Over time\", content: <HistoryPanel colors={colors} /> },\n    { id: \"frap\", label: \"FRAP\", content: <FrapPanel colors={colors} /> },\n    { id: \"scan\", label: \"Threshold\", content: <ScanPanel colors={colors} /> },\n    { id: \"theory\", label: \"Theory\", content: <TheoryPanel colors={colors} /> },\n    { id: \"log\", label: \"Log\", content: <LogPanel /> },\n  ];\n\n  return (\n    <div className=\"app\">\n      <header className=\"app-header\">\n        <a href=\"#stage\" className=\"skip-link\">\n          Skip to the simulation\n        </a>\n        <div className=\"brand\">\n          <h1>Condensate Lab</h1>\n          <p className=\"tagline\">See how proteins and RNA gather into droplets: the way cells make compartments without walls.</p>\n        </div>\n        <div className=\"header-actions\" role=\"group\" aria-label=\"Lab tools\">\n          <button type=\"button\" className=\"button\" aria-expanded={guideOpen} aria-controls=\"guide-region\" onClick={() => setGuideChoice(!guideOpen)}>\n            {guideOpen ? \"Hide guide\" : \"Guide\"}\n          </button>\n          <button type=\"button\" className=\"button\" onClick={() => setSettingsOpen(true)}>\n            Settings\n          </button>\n          <button type=\"button\" className=\"button\" onClick={() => setDataOpen(true)}>\n            Save and load\n          </button>\n        </div>\n      </header>\n\n      <main id=\"main\">\n        <div id=\"guide-region\">\n          {guideOpen ? (\n            <Guide\n              step={guideStep}\n              setStep={setGuideStep}\n              onClose={() => setGuideChoice(false)}\n              canAutoplay={access.autoplay}\n              onOpenTab={(t) => setTab(t)}\n            />\n          ) : null}\n        </div>\n\n        <div className=\"layout\">\n          <section id=\"stage\" className=\"stage panel\" aria-labelledby=\"stage-h\" tabIndex={-1}>\n            <h2 id=\"stage-h\">The simulation</h2>\n            <div className=\"figure-wrap\">\n              <SimCanvas colors={colors} mode={mode} labelId=\"stage-h\" describedBy=\"summary-text canvas-keys\" onBleach={onBleach} />\n            </div>\n            <p id=\"canvas-keys\" className=\"hint\">\n              In the picture: arrow keys move between droplets, B bleaches a spot in the selected droplet, Space plays or pauses, Escape clears the\n              selection. Click or tap a droplet to select it.\n            </p>\n            <Legend c={colors} />\n            <Playback mode={mode} setMode={setModeChoice} />\n            <StatusSummary id=\"summary-text\" />\n            <div className=\"button-row\">\n              <button\n                type=\"button\"\n                className=\"button secondary\"\n                aria-pressed={listen}\n                onClick={() => {\n                  setListen(!listen);\n                  announce(listen ? \"Tone off.\" : \"Tone on: its pitch rises as more protein joins droplets.\", { topic: \"listen\" });\n                }}\n              >\n                {listen ? \"Stop the tone\" : \"Hear the result as a tone\"}\n              </button>\n            </div>\n            <SelectionCard onBleach={onBleach} />\n          </section>\n\n          <Controls />\n\n          <section className=\"results panel\" aria-labelledby=\"results-h\">\n            <h2 id=\"results-h\">Results</h2>\n            <Tabs label=\"Results\" tabs={tabs} current={tab} onChange={setTab} />\n          </section>\n        </div>\n\n        <section className=\"about panel\" aria-labelledby=\"about-h\">\n          <h2 id=\"about-h\">About this model</h2>\n          <p>\n            A simplified simulation for building intuition: molecules are beads that jiggle (Brownian motion) and stick to each other. It shows the\n            right trends, not real numbers. What it leaves out:\n          </p>\n          <ul>\n            {LIMITS.map((l) => (\n              <li key={l}>{l}</li>\n            ))}\n          </ul>\n          <details>\n            <summary>Words used here</summary>\n            <dl className=\"glossary\">\n              {GLOSSARY.map((g) => (\n                <div key={g.term}>\n                  <dt>{g.term}</dt>\n                  <dd>{g.definition}</dd>\n                </div>\n              ))}\n            </dl>\n          </details>\n        </section>\n      </main>\n\n      <SettingsDialog open={settingsOpen} onClose={() => setSettingsOpen(false)} spoken={spoken} setSpoken={setSpoken} />\n      <DataDialog open={dataOpen} onClose={() => setDataOpen(false)} colors={colors} />\n    </div>\n  );\n}\n\nexport default function CondensateLab() {\n  const [store] = useState(() => new LabStore());\n  return (\n    <LabContext.Provider value={store}>\n      <Lab store={store} />\n    </LabContext.Provider>\n  );\n}\n",
    "apps/condensate-lab/components/Controls.tsx": "\"use client\";\n\nimport { announce, useAccess } from \"@repo/access\";\nimport { useId, useRef, useState } from \"react\";\nimport { PRESETS } from \"@/lib/content\";\nimport { clampParam, formatParam, PARAM_SPECS, type ParamSpec } from \"@/lib/sim/params\";\nimport { useSnapshot, useStore } from \"./LabContext\";\n\nfunction Slider({ spec, value, showHelp }: { spec: ParamSpec; value: number; showHelp: boolean }) {\n  const store = useStore();\n  const id = useId();\n  const [draft, setDraft] = useState<number | null>(null);\n  const timer = useRef<ReturnType<typeof setTimeout> | null>(null);\n  const shown = draft ?? value;\n\n  // Settings that restart the run (molecule counts) wait until you stop moving the slider.\n  const commit = (v: number) => {\n    const c = clampParam(spec.key, v);\n    if (!spec.restarts) {\n      store.setParam(spec.key, c);\n      return;\n    }\n    setDraft(c);\n    if (timer.current) clearTimeout(timer.current);\n    timer.current = setTimeout(() => {\n      store.setParam(spec.key, c);\n      setDraft(null);\n    }, 400);\n  };\n\n  const nudge = (dir: 1 | -1) => {\n    const c = clampParam(spec.key, shown + dir * spec.step);\n    commit(c);\n    announce(`${spec.label} ${formatParam(spec.key, c)}`, { topic: `param-${spec.key}` });\n  };\n\n  return (\n    <div className=\"control\">\n      <div className=\"control-head\">\n        <label htmlFor={id} className=\"control-label\">\n          {spec.label}\n        </label>\n        <output htmlFor={id} className=\"control-value\" aria-hidden=\"true\">\n          {formatParam(spec.key, shown)}\n        </output>\n      </div>\n      <div className=\"control-row\">\n        <button\n          type=\"button\"\n          className=\"icon-button\"\n          onClick={() => nudge(-1)}\n          disabled={shown <= spec.min}\n          aria-label={`Decrease ${spec.short}`}\n        >\n          −\n        </button>\n        <input\n          id={id}\n          type=\"range\"\n          min={spec.min}\n          max={spec.max}\n          step={spec.step}\n          value={shown}\n          aria-valuetext={formatParam(spec.key, shown)}\n          aria-describedby={`${id}-help`}\n          onChange={(e) => commit(Number(e.target.value))}\n        />\n        <button\n          type=\"button\"\n          className=\"icon-button\"\n          onClick={() => nudge(1)}\n          disabled={shown >= spec.max}\n          aria-label={`Increase ${spec.short}`}\n        >\n          +\n        </button>\n      </div>\n      <p id={`${id}-help`} className={showHelp ? \"control-help\" : \"visually-hidden\"}>\n        {spec.help}\n        {spec.restarts ? \" Changing it starts a new run.\" : \"\"}\n      </p>\n    </div>\n  );\n}\n\nfunction Toggle({\n  label,\n  help,\n  checked,\n  onChange,\n  showHelp,\n}: {\n  label: string;\n  help: string;\n  checked: boolean;\n  onChange: (v: boolean) => void;\n  showHelp: boolean;\n}) {\n  const id = useId();\n  return (\n    <div className=\"control\">\n      <label className=\"switch\" htmlFor={id}>\n        <input id={id} type=\"checkbox\" role=\"switch\" checked={checked} onChange={(e) => onChange(e.target.checked)} aria-describedby={`${id}-help`} />\n        <span className=\"switch-track\" aria-hidden=\"true\">\n          <span className=\"switch-thumb\" />\n        </span>\n        <span className=\"control-label\">{label}</span>\n        <span className=\"switch-state\" aria-hidden=\"true\">\n          {checked ? \"On\" : \"Off\"}\n        </span>\n      </label>\n      <p id={`${id}-help`} className={showHelp ? \"control-help\" : \"visually-hidden\"}>\n        {help}\n      </p>\n    </div>\n  );\n}\n\nexport function Controls() {\n  const store = useStore();\n  const snap = useSnapshot();\n  const access = useAccess();\n  const p = snap.params;\n  const showHelp = access.beginner;\n  const [moreOpen, setMoreOpen] = useState(false);\n  const simpler = access.settings.simpler;\n  const main = PARAM_SPECS.filter((s) => !s.advanced && (s.key !== \"rnaCount\" || p.multiComponent));\n  const advanced = PARAM_SPECS.filter((s) => s.advanced);\n  const presetId = useId();\n\n  const advancedBlock = (\n    <>\n      {advanced.map((s) => (\n        <Slider key={s.key} spec={s} value={p[s.key]} showHelp={showHelp} />\n      ))}\n    </>\n  );\n\n  return (\n    <section className=\"panel controls\" aria-labelledby=\"controls-h\">\n      <h2 id=\"controls-h\">Settings for the mix</h2>\n      <div className=\"control\">\n        <label htmlFor={presetId} className=\"control-label\">\n          Start from an example\n        </label>\n        <select\n          id={presetId}\n          className=\"select\"\n          value=\"\"\n          onChange={(e) => {\n            const pr = PRESETS.find((x) => x.id === e.target.value);\n            if (!pr) return;\n            store.applyParams(pr.params, pr.name);\n            announce(`${pr.name}: ${pr.summary}`, { topic: \"preset\" });\n          }}\n        >\n          <option value=\"\">Choose an example…</option>\n          {PRESETS.map((pr) => (\n            <option key={pr.id} value={pr.id}>\n              {pr.name}\n            </option>\n          ))}\n        </select>\n        <p className={showHelp ? \"control-help\" : \"visually-hidden\"}>\n          Illustrative settings inspired by real structures, not measurements of them.\n        </p>\n      </div>\n      {main.map((s) => (\n        <Slider key={s.key} spec={s} value={p[s.key]} showHelp={showHelp} />\n      ))}\n      <Toggle\n        label=\"Include RNA\"\n        help=\"RNA molecules (triangles) join the mix. Changing this starts a new run.\"\n        checked={p.multiComponent}\n        onChange={(v) => store.setFlag(\"multiComponent\", v)}\n        showHelp={showHelp}\n      />\n      <Toggle\n        label=\"Disease mode\"\n        help=\"Large droplets can slowly harden into solid clumps (squares), as with some ALS mutations. Turning it off stops new hardening but does not undo it.\"\n        checked={p.diseaseMode}\n        onChange={(v) => store.setFlag(\"diseaseMode\", v)}\n        showHelp={showHelp}\n      />\n      {simpler ? (\n        <div className=\"more\">\n          <button\n            type=\"button\"\n            className=\"button secondary\"\n            aria-expanded={moreOpen}\n            aria-controls=\"more-settings\"\n            onClick={() => setMoreOpen((o) => !o)}\n          >\n            {moreOpen ? \"Hide pH, crowding and hardening speed\" : \"Show pH, crowding and hardening speed\"}\n          </button>\n          <div id=\"more-settings\" hidden={!moreOpen}>\n            {advancedBlock}\n          </div>\n        </div>\n      ) : (\n        advancedBlock\n      )}\n    </section>\n  );\n}\n",
    "apps/condensate-lab/components/Dialogs.tsx": "\"use client\";\n\nimport { AccessSettingsPanel } from \"@repo/access\";\nimport { useEffect, useId, useRef, useState, useSyncExternalStore, type ReactNode } from \"react\";\nimport { download, dropletsCsv, historyCsv, pictureSvg, settingsJson } from \"@/lib/export\";\nimport { sanitizeParams } from \"@/lib/sim/params\";\nimport { soundSupported } from \"@/lib/sonify\";\nimport { useSnapshot, useStore } from \"./LabContext\";\nimport type { ThemeColors } from \"./useTheme\";\n\n/**\n * A modal dialog using the native <dialog>: the browser traps focus and Escape\n * closes it. Focus goes back to the button that opened it.\n */\nexport function Dialog({ open, onClose, title, children }: { open: boolean; onClose: () => void; title: string; children: ReactNode }) {\n  const ref = useRef<HTMLDialogElement>(null);\n  const opener = useRef<Element | null>(null);\n  const id = useId();\n  useEffect(() => {\n    const d = ref.current;\n    if (!d) return;\n    if (open && !d.open) {\n      opener.current = document.activeElement;\n      d.showModal();\n    } else if (!open && d.open) {\n      d.close();\n    }\n  }, [open]);\n  return (\n    <dialog\n      ref={ref}\n      className=\"dialog\"\n      aria-labelledby={`${id}-h`}\n      onClose={() => {\n        onClose();\n        const o = opener.current as HTMLElement | null;\n        if (o && typeof o.focus === \"function\") o.focus();\n      }}\n      onCancel={(e) => {\n        // Escape never closes while typing in a text field\n        const a = document.activeElement as HTMLElement | null;\n        if (a && (a.tagName === \"TEXTAREA\" || (a.tagName === \"INPUT\" && (a as HTMLInputElement).type === \"text\"))) e.preventDefault();\n      }}\n    >\n      <div className=\"dialog-head\">\n        <h2 id={`${id}-h`}>{title}</h2>\n        <button type=\"button\" className=\"button secondary\" onClick={() => ref.current?.close()}>\n          Close\n        </button>\n      </div>\n      <div className=\"dialog-body\">{children}</div>\n    </dialog>\n  );\n}\n\nconst noSubscribe = () => () => {};\n\nexport function SettingsDialog({\n  open,\n  onClose,\n  spoken,\n  setSpoken,\n}: {\n  open: boolean;\n  onClose: () => void;\n  spoken: boolean;\n  setSpoken: (v: boolean) => void;\n}) {\n  const id = useId();\n  const canSound = useSyncExternalStore(noSubscribe, soundSupported, () => true);\n  return (\n    <Dialog open={open} onClose={onClose} title=\"Settings\">\n      <p>These choices apply to every LogueBio tool on this device.</p>\n      <AccessSettingsPanel headingLevel={3} />\n      <h3>In Condensate Lab</h3>\n      <div className=\"control\">\n        <label className=\"check\" htmlFor={id}>\n          <input id={id} type=\"checkbox\" checked={spoken} onChange={(e) => setSpoken(e.target.checked)} />\n          Spoken updates while the simulation runs\n        </label>\n        <p className=\"control-help\">\n          For screen readers: a short update every few seconds about droplets forming, merging and dissolving. Turn off for quiet; the summary under the\n          picture and the Log tab always have the latest.\n        </p>\n      </div>\n      {!canSound ? <p className=\"note\">This browser cannot play sounds from a web page.</p> : null}\n    </Dialog>\n  );\n}\n\nexport function DataDialog({ open, onClose, colors }: { open: boolean; onClose: () => void; colors: ThemeColors }) {\n  const store = useStore();\n  const snap = useSnapshot();\n  const fileId = useId();\n  const [msg, setMsg] = useState<string | null>(null);\n  const stamp = `t${Math.round(snap.time)}`;\n  return (\n    <Dialog open={open} onClose={onClose} title=\"Save and load\">\n      <p>Files are made and read on this device. Nothing is uploaded.</p>\n      <h3>Save</h3>\n      <ul className=\"action-list\">\n        <li>\n          <button\n            type=\"button\"\n            className=\"button\"\n            onClick={() =>\n              download(`condensate-lab-picture-${stamp}.svg`, pictureSvg(store.world, snap, { protein: colors.protein, rna: colors.rna, solid: colors.solid, ink: colors.ink, paper: colors.paper }), \"image/svg+xml\")\n            }\n          >\n            Picture (SVG)\n          </button>\n          <span className=\"muted\"> with a title and a full text description inside, for alt text.</span>\n        </li>\n        <li>\n          <button type=\"button\" className=\"button\" onClick={() => download(`condensate-lab-droplets-${stamp}.csv`, dropletsCsv(snap), \"text/csv\")}>\n            Droplets table (CSV)\n          </button>\n        </li>\n        <li>\n          <button type=\"button\" className=\"button\" onClick={() => download(\"condensate-lab-over-time.csv\", historyCsv(snap), \"text/csv\")}>\n            Readings over time (CSV)\n          </button>\n        </li>\n        <li>\n          <button type=\"button\" className=\"button\" onClick={() => download(\"condensate-lab-settings.json\", settingsJson(snap), \"application/json\")}>\n            Settings (JSON)\n          </button>\n          <span className=\"muted\"> to repeat this run later: same seed, same start.</span>\n        </li>\n      </ul>\n      <p className=\"muted\">FRAP curves and threshold scans have their own download buttons in their tabs.</p>\n      <h3>Load settings</h3>\n      <div className=\"file-field\">\n        <label htmlFor={fileId} className=\"button\">\n          Choose a settings file\n        </label>\n        <input\n          id={fileId}\n          type=\"file\"\n          accept=\".json,application/json\"\n          className=\"file-input\"\n          onChange={async (e) => {\n            const file = e.target.files?.[0];\n            if (!file) return;\n            try {\n              const data = JSON.parse(await file.text());\n              const params = sanitizeParams(data && typeof data === \"object\" && \"params\" in data ? (data as { params: unknown }).params : data);\n              store.applyParams(params, `Settings from ${file.name}`);\n              setMsg(`Loaded settings from ${file.name}. Anything missing or out of range was set to its default.`);\n            } catch {\n              setMsg(\"That file is not a settings file (it is not valid JSON).\");\n            }\n            e.target.value = \"\";\n          }}\n        />\n      </div>\n      {msg ? (\n        <p className=\"note\" role=\"status\">\n          {msg}\n        </p>\n      ) : null}\n    </Dialog>\n  );\n}\n",
    "apps/condensate-lab/components/Guide.tsx": "\"use client\";\n\nimport { announce } from \"@repo/access\";\nimport { useRef } from \"react\";\nimport { GUIDE } from \"@/lib/content\";\nimport { useStore } from \"./LabContext\";\n\nexport function Guide({\n  step,\n  setStep,\n  onClose,\n  canAutoplay,\n  onOpenTab,\n}: {\n  step: number;\n  setStep: (n: number) => void;\n  onClose: () => void;\n  canAutoplay: boolean;\n  onOpenTab: (tab: string) => void;\n}) {\n  const store = useStore();\n  const g = GUIDE[step];\n  const headingRef = useRef<HTMLHeadingElement>(null);\n  const go = (n: number) => {\n    setStep(n);\n    // keep focus with the reader: move it to the new step's heading\n    requestAnimationFrame(() => headingRef.current?.focus());\n  };\n  const tabFor: Record<string, string> = { theory: \"theory\", frap: \"frap\", rna: \"droplets\", concentration: \"scan\" };\n  return (\n    <section className=\"guide\" aria-labelledby=\"guide-h\">\n      <div className=\"guide-top\">\n        <h2 id=\"guide-h\" className=\"guide-kicker\">\n          Guide <span className=\"muted\">· step {step + 1} of {GUIDE.length}</span>\n        </h2>\n        <button type=\"button\" className=\"button secondary small\" onClick={onClose}>\n          Hide guide\n        </button>\n      </div>\n      <h3 ref={headingRef} tabIndex={-1} className=\"guide-title\">\n        {g.title}\n      </h3>\n      {g.body.map((para, i) => (\n        <p key={i}>{para}</p>\n      ))}\n      {g.lookFor ? (\n        <p className=\"guide-look\">\n          <span className=\"label\">Look for</span> {g.lookFor}\n        </p>\n      ) : null}\n      <div className=\"button-row\">\n        <button\n          type=\"button\"\n          className=\"button\"\n          aria-disabled={step === 0}\n          onClick={() => (step > 0 ? go(step - 1) : announce(\"This is the first step.\", { topic: \"guide\" }))}\n        >\n          Previous step\n        </button>\n        {g.tryParams ? (\n          <button\n            type=\"button\"\n            className=\"button primary\"\n            onClick={() => {\n              store.applyParams(g.tryParams!, g.tryLabel);\n              if (canAutoplay) {\n                store.play();\n                announce(`${g.tryLabel}: done, and playing. ${g.lookFor ?? \"\"}`, { topic: \"guide\" });\n              } else {\n                announce(`${g.tryLabel}: done. Press Play or Jump ahead to see what happens.`, { topic: \"guide\" });\n              }\n            }}\n          >\n            Try it: {g.tryLabel}\n          </button>\n        ) : null}\n        {tabFor[g.id] ? (\n          <button type=\"button\" className=\"button\" onClick={() => onOpenTab(tabFor[g.id])}>\n            Open the {tabFor[g.id] === \"scan\" ? \"Threshold\" : tabFor[g.id] === \"frap\" ? \"FRAP\" : tabFor[g.id] === \"theory\" ? \"Theory\" : \"Droplets\"} tab\n          </button>\n        ) : null}\n        <button\n          type=\"button\"\n          className=\"button\"\n          onClick={() => (step < GUIDE.length - 1 ? go(step + 1) : announce(\"This is the last step. You can hide the guide or go back.\", { topic: \"guide\" }))}\n          aria-disabled={step === GUIDE.length - 1}\n        >\n          Next step\n        </button>\n      </div>\n    </section>\n  );\n}\n",
    "apps/condensate-lab/components/LabContext.tsx": "\"use client\";\n\nimport { createContext, useContext, useSyncExternalStore } from \"react\";\nimport type { LabStore, Snapshot } from \"@/lib/store\";\n\nexport const LabContext = createContext<LabStore | null>(null);\n\nexport function useStore(): LabStore {\n  const s = useContext(LabContext);\n  if (!s) throw new Error(\"useStore must be used inside <LabContext.Provider>\");\n  return s;\n}\n\n/** The current state of the lab; re-renders when it changes. */\nexport function useSnapshot(): Snapshot {\n  const store = useStore();\n  return useSyncExternalStore(store.subscribe, store.getSnapshot, store.getSnapshot);\n}\n",
    "apps/condensate-lab/components/LineChart.tsx": "\"use client\";\n\nimport { announce } from \"@repo/access\";\nimport { useId, useState, type ReactNode } from \"react\";\nimport { SortableTable, type Column } from \"./SortableTable\";\n\nexport type Marker = \"circle\" | \"triangle\" | \"square\" | \"diamond\" | \"none\";\n\nexport interface Series {\n  name: string;\n  points: { x: number; y: number }[];\n  color: string;\n  marker: Marker;\n  dash?: string;\n  /** Draw a line through the points (default true). */\n  line?: boolean;\n}\n\nexport interface RefLine {\n  axis: \"x\" | \"y\";\n  value: number;\n  label: string;\n}\n\nconst W = 520;\nconst H = 260;\nconst M = { l: 56, r: 16, t: 16, b: 46 };\n\nfunction niceTicks(lo: number, hi: number, n = 5): number[] {\n  if (!(hi > lo)) return [lo];\n  const raw = (hi - lo) / n;\n  const mag = Math.pow(10, Math.floor(Math.log10(raw)));\n  const step = [1, 2, 2.5, 5, 10].map((m) => m * mag).find((s) => s >= raw) ?? raw;\n  const out: number[] = [];\n  for (let v = Math.ceil(lo / step) * step; v <= hi + step * 1e-9; v += step) out.push(Number(v.toPrecision(10)));\n  return out;\n}\n\nexport function MarkerShape({ m, x, y, size, color }: { m: Marker; x: number; y: number; size: number; color: string }) {\n  const s = size;\n  switch (m) {\n    case \"circle\":\n      return <circle cx={x} cy={y} r={s / 2} fill={color} />;\n    case \"square\":\n      return <rect x={x - s / 2} y={y - s / 2} width={s} height={s} fill={color} />;\n    case \"triangle\":\n      return <polygon points={`${x},${y - s * 0.6} ${x + s * 0.55},${y + s * 0.45} ${x - s * 0.55},${y + s * 0.45}`} fill={color} />;\n    case \"diamond\":\n      return <polygon points={`${x},${y - s * 0.6} ${x + s * 0.6},${y} ${x},${y + s * 0.6} ${x - s * 0.6},${y}`} fill={color} />;\n    default:\n      return null;\n  }\n}\n\n/**\n * A line chart with its non-visual equivalents built in: a text summary, a\n * keyboard cursor that reads out each point, and a sortable table of the\n * same numbers.\n */\nexport function LineChart({\n  title,\n  summary,\n  xLabel,\n  yLabel,\n  xFormat,\n  yFormat,\n  series,\n  xDomain,\n  yDomain,\n  refLines = [],\n  ink,\n  muted,\n  grid,\n  accent,\n  tableLimit = 150,\n  emptyText,\n  children,\n}: {\n  title: string;\n  summary: ReactNode;\n  xLabel: string;\n  yLabel: string;\n  xFormat: (v: number) => string;\n  yFormat: (v: number) => string;\n  series: Series[];\n  xDomain?: [number, number];\n  yDomain?: [number, number];\n  refLines?: RefLine[];\n  ink: string;\n  muted: string;\n  grid: string;\n  accent: string;\n  tableLimit?: number;\n  emptyText: string;\n  children?: ReactNode;\n}) {\n  const uid = useId();\n  const [cursor, setCursor] = useState<{ s: number; i: number } | null>(null);\n  const all = series.flatMap((s) => s.points);\n  const has = all.length > 0;\n  const [x0, x1] = xDomain ?? (has ? [Math.min(...all.map((p) => p.x)), Math.max(...all.map((p) => p.x))] : [0, 1]);\n  const [y0, y1] = yDomain ?? (has ? [Math.min(0, ...all.map((p) => p.y)), Math.max(...all.map((p) => p.y))] : [0, 1]);\n  const xs = (v: number) => M.l + ((v - x0) / (x1 - x0 || 1)) * (W - M.l - M.r);\n  const ys = (v: number) => H - M.b - ((v - y0) / (y1 - y0 || 1)) * (H - M.t - M.b);\n  const xt = niceTicks(x0, x1, 5);\n  const yt = niceTicks(y0, y1, 4);\n\n  const active = cursor && series[cursor.s] && series[cursor.s].points[cursor.i] ? cursor : null;\n  const readout = active\n    ? `${series[active.s].name}: ${xLabel} ${xFormat(series[active.s].points[active.i].x)}, ${yLabel} ${yFormat(series[active.s].points[active.i].y)}`\n    : null;\n\n  const move = (s: number, i: number) => {\n    const pts = series[s]?.points;\n    if (!pts || pts.length === 0) return;\n    const ci = Math.max(0, Math.min(pts.length - 1, i));\n    setCursor({ s, i: ci });\n    const p = pts[ci];\n    announce(`${series[s].name}: ${xLabel} ${xFormat(p.x)}, ${yLabel} ${yFormat(p.y)}. Point ${ci + 1} of ${pts.length}.`, { topic: uid });\n  };\n\n  const onKeyDown = (e: React.KeyboardEvent) => {\n    if (!has) return;\n    const s = active?.s ?? series.findIndex((x) => x.points.length > 0);\n    const i = active?.i ?? -1;\n    const len = series[s]?.points.length ?? 0;\n    const big = Math.max(1, Math.round(len / 10));\n    switch (e.key) {\n      case \"ArrowRight\":\n        move(s, i + 1);\n        break;\n      case \"ArrowLeft\":\n        move(s, i < 0 ? len - 1 : i - 1);\n        break;\n      case \"PageUp\":\n        move(s, i + big);\n        break;\n      case \"PageDown\":\n        move(s, i - big);\n        break;\n      case \"Home\":\n        move(s, 0);\n        break;\n      case \"End\":\n        move(s, len - 1);\n        break;\n      case \"ArrowUp\":\n      case \"ArrowDown\": {\n        const dir = e.key === \"ArrowUp\" ? -1 : 1;\n        for (let k = 1; k <= series.length; k++) {\n          const ns = (s + dir * k + series.length * 2) % series.length;\n          const np = series[ns].points;\n          if (np.length === 0) continue;\n          // nearest x in the other series\n          const x = i >= 0 ? series[s].points[i].x : np[0].x;\n          let best = 0;\n          for (let j = 1; j < np.length; j++) if (Math.abs(np[j].x - x) < Math.abs(np[best].x - x)) best = j;\n          move(ns, best);\n          break;\n        }\n        break;\n      }\n      case \"Escape\":\n        if (!active) return;\n        setCursor(null);\n        break;\n      default:\n        return;\n    }\n    e.preventDefault();\n  };\n\n  const onPointerMove = (e: React.PointerEvent<SVGSVGElement>) => {\n    if (!has || e.pointerType !== \"mouse\") return;\n    const rect = e.currentTarget.getBoundingClientRect();\n    const vx = ((e.clientX - rect.left) / rect.width) * W;\n    let best: { s: number; i: number; d: number } | null = null;\n    series.forEach((s, si) =>\n      s.points.forEach((p, pi) => {\n        const d = Math.abs(xs(p.x) - vx);\n        if (!best || d < best.d) best = { s: si, i: pi, d };\n      }),\n    );\n    if (best) setCursor({ s: (best as { s: number }).s, i: (best as { i: number }).i });\n  };\n\n  // table: one row per distinct x, one column per series\n  const xsAll = Array.from(new Set(all.map((p) => p.x))).sort((a, b) => a - b);\n  const rows = xsAll.map((x) => ({ x, ys: series.map((s) => s.points.find((p) => p.x === x)?.y ?? null) }));\n  type Row = (typeof rows)[number];\n  const columns: Column<Row>[] = [\n    { key: \"x\", label: xLabel, value: (r) => r.x, format: (r) => xFormat(r.x), numeric: true },\n    ...series.map((s, k) => ({\n      key: `s${k}`,\n      label: s.name,\n      value: (r: Row) => r.ys[k] ?? -Infinity,\n      format: (r: Row) => (r.ys[k] === null ? \"–\" : yFormat(r.ys[k] as number)),\n      numeric: true,\n    })),\n  ];\n\n  return (\n    <figure className=\"chart\" aria-labelledby={`${uid}-t`}>\n      <figcaption id={`${uid}-t`} className=\"chart-title\">\n        {title}\n      </figcaption>\n      <p id={`${uid}-s`} className=\"chart-summary\">\n        {summary}\n      </p>\n      <ul className=\"legend\" aria-label=\"Key\">\n        {series.map((s) => (\n          <li key={s.name}>\n            <svg width=\"28\" height=\"16\" aria-hidden=\"true\">\n              {s.line !== false ? <line x1=\"2\" y1=\"8\" x2=\"26\" y2=\"8\" stroke={s.color} strokeWidth=\"2.5\" strokeDasharray={s.dash} /> : null}\n              <MarkerShape m={s.marker} x={14} y={8} size={9} color={s.color} />\n            </svg>\n            {s.name}\n          </li>\n        ))}\n        {refLines.map((r) => (\n          <li key={r.label}>\n            <svg width=\"28\" height=\"16\" aria-hidden=\"true\">\n              <line x1=\"2\" y1=\"8\" x2=\"26\" y2=\"8\" stroke={muted} strokeWidth=\"1.5\" strokeDasharray=\"2 3\" />\n            </svg>\n            {r.label}\n          </li>\n        ))}\n      </ul>\n      {has ? (\n        <div\n          className=\"chart-surface\"\n          tabIndex={0}\n          role=\"application\"\n          aria-roledescription=\"chart\"\n          aria-label={`${title}. Use left and right arrows to read points, up and down to switch lines.`}\n          aria-describedby={`${uid}-s`}\n          onKeyDown={onKeyDown}\n          onBlur={() => setCursor(null)}\n        >\n          <svg viewBox={`0 0 ${W} ${H}`} className=\"chart-svg\" aria-hidden=\"true\" onPointerMove={onPointerMove} onPointerLeave={() => setCursor(null)}>\n            {yt.map((v) => (\n              <g key={`y${v}`}>\n                <line x1={M.l} x2={W - M.r} y1={ys(v)} y2={ys(v)} stroke={grid} />\n                <text x={M.l - 6} y={ys(v)} textAnchor=\"end\" dominantBaseline=\"middle\" fill={muted} fontSize=\"12\">\n                  {yFormat(v)}\n                </text>\n              </g>\n            ))}\n            {xt.map((v) => (\n              <text key={`x${v}`} x={xs(v)} y={H - M.b + 16} textAnchor=\"middle\" fill={muted} fontSize=\"12\">\n                {xFormat(v)}\n              </text>\n            ))}\n            <line x1={M.l} x2={W - M.r} y1={H - M.b} y2={H - M.b} stroke={ink} />\n            <line x1={M.l} x2={M.l} y1={M.t} y2={H - M.b} stroke={ink} />\n            <text x={(M.l + W - M.r) / 2} y={H - 8} textAnchor=\"middle\" fill={ink} fontSize=\"13\">\n              {xLabel}\n            </text>\n            <text transform={`translate(14 ${(M.t + H - M.b) / 2}) rotate(-90)`} textAnchor=\"middle\" fill={ink} fontSize=\"13\">\n              {yLabel}\n            </text>\n            {refLines.map((r) =>\n              r.axis === \"y\" ? (\n                <line key={r.label} x1={M.l} x2={W - M.r} y1={ys(r.value)} y2={ys(r.value)} stroke={muted} strokeWidth=\"1.5\" strokeDasharray=\"2 3\" />\n              ) : (\n                <line key={r.label} y1={M.t} y2={H - M.b} x1={xs(r.value)} x2={xs(r.value)} stroke={muted} strokeWidth=\"1.5\" strokeDasharray=\"2 3\" />\n              ),\n            )}\n            {series.map((s) => (\n              <g key={s.name}>\n                {s.line !== false && s.points.length > 1 ? (\n                  <polyline\n                    fill=\"none\"\n                    stroke={s.color}\n                    strokeWidth=\"2.5\"\n                    strokeDasharray={s.dash}\n                    points={s.points.map((p) => `${xs(p.x).toFixed(1)},${ys(p.y).toFixed(1)}`).join(\" \")}\n                  />\n                ) : null}\n                {s.marker !== \"none\"\n                  ? s.points\n                      .filter((_, i) => s.points.length <= 40 || i % Math.ceil(s.points.length / 40) === 0)\n                      .map((p, i) => <MarkerShape key={i} m={s.marker} x={xs(p.x)} y={ys(p.y)} size={8} color={s.color} />)\n                  : null}\n              </g>\n            ))}\n            {active ? (\n              <g>\n                <line\n                  x1={xs(series[active.s].points[active.i].x)}\n                  x2={xs(series[active.s].points[active.i].x)}\n                  y1={M.t}\n                  y2={H - M.b}\n                  stroke={accent}\n                  strokeWidth=\"1.5\"\n                />\n                <circle\n                  cx={xs(series[active.s].points[active.i].x)}\n                  cy={ys(series[active.s].points[active.i].y)}\n                  r=\"7\"\n                  fill=\"none\"\n                  stroke={accent}\n                  strokeWidth=\"3\"\n                />\n              </g>\n            ) : null}\n          </svg>\n          <p className=\"chart-readout\" aria-hidden=\"true\">\n            {readout ?? \"Focus the chart and use the arrow keys, or point at it, to read values.\"}\n          </p>\n        </div>\n      ) : (\n        <p className=\"empty\">{emptyText}</p>\n      )}\n      {children}\n      {has ? (\n        <details className=\"numbers\">\n          <summary>Show the numbers as a table</summary>\n          <SortableTable caption={`${title}: data`} columns={columns} rows={rows} rowKey={(r) => r.x} limit={tableLimit} />\n        </details>\n      ) : null}\n    </figure>\n  );\n}\n",
    "apps/condensate-lab/components/Panels.tsx": "\"use client\";\n\nimport { announce } from \"@repo/access\";\nimport { useId, useState } from \"react\";\nimport { describeDroplet, formatTime, pct, plural, STATE_LABEL } from \"@/lib/describe\";\nimport { download, frapCsv, historyCsv, importedCsv, scanCsv } from \"@/lib/export\";\nimport { binodal, CRITICAL_CHI, freeEnergy, freeEnergyCurve, spinodal } from \"@/lib/sim/floryHuggins\";\nimport { interpretFit, type FitResult, type FrapPoint } from \"@/lib/sim/frap\";\nimport { effectiveChi } from \"@/lib/sim/params\";\nimport { FRAP_MIN_SIZE, scanThreshold, type Droplet, type FrapRun, type ScanKey } from \"@/lib/store\";\nimport { useSnapshot, useStore } from \"./LabContext\";\nimport { LineChart, type Series } from \"./LineChart\";\nimport { SortableTable } from \"./SortableTable\";\nimport type { ThemeColors } from \"./useTheme\";\n\nfunction chartInk(c: ThemeColors) {\n  return { ink: c.ink, muted: c.muted, grid: c.grid, accent: c.accent };\n}\n\n// ─── Droplets ────────────────────────────────────────────────────────────────\n\nexport function DropletsPanel() {\n  const store = useStore();\n  const snap = useSnapshot();\n  const [frozen, setFrozen] = useState<Droplet[] | null>(null);\n  const rows = frozen ?? snap.droplets;\n  return (\n    <div className=\"panel-body\">\n      <p>\n        {snap.droplets.length === 0\n          ? \"No droplets yet. A droplet is a group of at least 8 touching molecules.\"\n          : `${plural(snap.droplets.length, \"droplet\")}. The largest has ${snap.droplets[0].size} molecules.`}{\" \"}\n        {snap.running && !frozen ? \"The table updates while the simulation runs.\" : \"\"}\n      </p>\n      <div className=\"button-row\">\n        <button\n          type=\"button\"\n          className=\"button secondary\"\n          aria-pressed={frozen !== null}\n          onClick={() => {\n            setFrozen(frozen ? null : snap.droplets);\n            announce(frozen ? \"Table follows the simulation again.\" : \"Table frozen. It shows the droplets as they were just now.\", { topic: \"table\" });\n          }}\n        >\n          {frozen ? \"Unfreeze table\" : \"Freeze table\"}\n        </button>\n      </div>\n      <SortableTable\n        caption={frozen ? \"Droplets (frozen copy)\" : \"Droplets\"}\n        rows={rows}\n        rowKey={(d) => d.id}\n        initialSort={{ key: \"size\", dir: \"desc\" }}\n        columns={[\n          { key: \"id\", label: \"Droplet\", value: (d) => d.id, numeric: true },\n          { key: \"size\", label: \"Molecules\", value: (d) => d.size, numeric: true },\n          { key: \"protein\", label: \"Protein\", value: (d) => d.protein, numeric: true },\n          { key: \"rna\", label: \"RNA\", value: (d) => d.rna, numeric: true },\n          { key: \"state\", label: \"State\", value: (d) => d.solidFraction, format: (d) => STATE_LABEL[d.state] },\n          { key: \"solid\", label: \"Solid\", value: (d) => d.solidFraction, format: (d) => pct(d.solidFraction), numeric: true },\n          { key: \"where\", label: \"Where\", value: (d) => d.region },\n        ]}\n        action={{\n          label: \"Select\",\n          render: (d) => (\n            <button\n              type=\"button\"\n              className=\"button small\"\n              aria-pressed={snap.selectedId === d.id}\n              aria-label={`Select droplet ${d.id}`}\n              onClick={() => {\n                const exists = store.getSnapshot().droplets.some((x) => x.id === d.id);\n                store.select(d.id);\n                announce(exists ? `Selected. ${describeDroplet(d)}` : `Droplet ${d.id} no longer exists.`, { topic: \"selection\" });\n              }}\n            >\n              {snap.selectedId === d.id ? \"Selected\" : \"Select\"}\n            </button>\n          ),\n        }}\n        emptyText=\"No droplets yet.\"\n      />\n    </div>\n  );\n}\n\n// ─── Over time ───────────────────────────────────────────────────────────────\n\nexport function HistoryPanel({ colors }: { colors: ThemeColors }) {\n  const snap = useSnapshot();\n  const h = snap.history;\n  const last = h[h.length - 1];\n  const peak = h.reduce((m, p) => Math.max(m, p.fraction), 0);\n  const frac: Series[] = [\n    { name: \"Protein in droplets\", points: h.map((p) => ({ x: p.t, y: p.fraction * 100 })), color: colors.protein, marker: \"circle\" },\n  ];\n  if (h.some((p) => p.solidFraction > 0))\n    frac.push({ name: \"Protein that is solid\", points: h.map((p) => ({ x: p.t, y: p.solidFraction * 100 })), color: colors.solid, marker: \"square\", dash: \"6 4\" });\n  const summary = last\n    ? `From time 0 to ${formatTime(last.t)}: protein in droplets went from ${pct(h[0].fraction)} to ${pct(last.fraction)} (highest ${pct(peak)}).${last.solidFraction > 0 ? ` ${pct(last.solidFraction)} of the protein is now solid.` : \"\"}`\n    : \"Nothing recorded yet. Press Play, Step or Jump ahead.\";\n  return (\n    <div className=\"panel-body\">\n      <LineChart\n        title=\"Protein in droplets over time\"\n        summary={summary}\n        xLabel=\"Time\"\n        yLabel=\"Percent of protein\"\n        xFormat={formatTime}\n        yFormat={(v) => `${Math.round(v)}%`}\n        yDomain={[0, 100]}\n        series={frac}\n        emptyText=\"Nothing recorded yet. Press Play, Step or Jump ahead.\"\n        {...chartInk(colors)}\n      />\n      <LineChart\n        title=\"Number of droplets over time\"\n        summary={last ? `Now ${plural(last.count, \"droplet\")}; the most at any time was ${h.reduce((m, p) => Math.max(m, p.count), 0)}.` : \"Nothing recorded yet.\"}\n        xLabel=\"Time\"\n        yLabel=\"Droplets\"\n        xFormat={formatTime}\n        yFormat={(v) => String(Math.round(v))}\n        series={[{ name: \"Droplets\", points: h.map((p) => ({ x: p.t, y: p.count })), color: colors.rna, marker: \"triangle\" }]}\n        emptyText=\"Nothing recorded yet.\"\n        {...chartInk(colors)}\n      />\n      <div className=\"button-row\">\n        <button type=\"button\" className=\"button\" disabled={h.length === 0} onClick={() => download(\"condensate-lab-over-time.csv\", historyCsv(snap), \"text/csv\")}>\n          Download as CSV\n        </button>\n      </div>\n    </div>\n  );\n}\n\n// ─── FRAP ────────────────────────────────────────────────────────────────────\n\nfunction fitCurve(points: FrapPoint[], fit: FitResult): { x: number; y: number }[] {\n  if (!fit.ok || !Number.isFinite(fit.fit.halfTime) || points.length < 2) return [];\n  const t1 = points[points.length - 1].t;\n  const { i0, plateau, tau } = fit.fit;\n  return Array.from({ length: 60 }, (_, k) => {\n    const t = (t1 * k) / 59;\n    return { x: t, y: i0 + (plateau - i0) * (1 - Math.exp(-t / tau)) };\n  });\n}\n\nfunction fitLines(fit: FitResult | null): string[] {\n  if (!fit) return [\"Recording… a fit appears after 8 readings.\"];\n  if (!fit.ok) return [fit.reason];\n  const ht = Number.isFinite(fit.fit.halfTime) ? `Half-time ${formatTime(fit.fit.halfTime)}.` : \"Half-time: not measurable (no clear recovery).\";\n  return [interpretFit(fit), ht, fit.note];\n}\n\nexport function FrapPanel({ colors }: { colors: ThemeColors }) {\n  const store = useStore();\n  const snap = useSnapshot();\n  const f = snap.frap;\n  const fileId = useId();\n  const [msg, setMsg] = useState<string | null>(null);\n\n  const runChart = (run: FrapRun) => {\n    const series: Series[] = [{ name: \"Brightness of the spot\", points: run.points.map((p) => ({ x: p.t, y: p.intensity })), color: colors.protein, marker: \"circle\", line: false }];\n    if (run.fit && run.fit.ok) {\n      const c = fitCurve(run.points, run.fit);\n      if (c.length) series.push({ name: \"Fitted recovery curve\", points: c, color: colors.ink, marker: \"none\", dash: \"6 4\" });\n    }\n    return (\n      <LineChart\n        title={`FRAP on droplet ${run.dropletId}`}\n        summary={`${run.status === \"recording\" ? \"Recording.\" : run.endReason ?? \"Finished.\"} Bleached ${run.bleachedCount} molecules in a ${STATE_LABEL[run.stateAtBleach].toLowerCase()} droplet. ${fitLines(run.fit).join(\" \")}`}\n        xLabel=\"Time since bleach\"\n        yLabel=\"Relative brightness\"\n        xFormat={formatTime}\n        yFormat={(v) => v.toFixed(2)}\n        yDomain={[0, 1.2]}\n        refLines={[{ axis: \"y\", value: 1, label: \"Brightness before bleaching (1)\" }]}\n        series={series}\n        emptyText=\"No readings yet.\"\n        {...chartInk(colors)}\n      />\n    );\n  };\n\n  const runs = snap.frapRuns;\n  const imp = snap.imported;\n  const impSeries: Series[] = imp\n    ? [\n        { name: \"Your readings\", points: imp.points.map((p) => ({ x: p.t, y: p.intensity })), color: colors.rna, marker: \"triangle\", line: false },\n        ...(imp.fit.ok ? [{ name: \"Fitted recovery curve\", points: fitCurve(imp.points, imp.fit), color: colors.ink, marker: \"none\" as const, dash: \"6 4\" }] : []),\n      ]\n    : [];\n  const lastRun = runs[runs.length - 1] ?? (f && f.status === \"ended\" ? f : null);\n\n  return (\n    <div className=\"panel-body\">\n      <p>\n        FRAP tests whether a droplet is liquid: bleach a spot dark, then see if glowing molecules move back in. Brightness here is the spot divided by\n        the whole droplet, so a fully mixed liquid returns to 1 and a solid stays low.\n      </p>\n      {!f ? (\n        <p className=\"note\">\n          Select a droplet with at least {FRAP_MIN_SIZE} molecules (Droplets tab, the picture, or Next droplet), then press <strong>Bleach a spot</strong>.\n        </p>\n      ) : (\n        runChart(f)\n      )}\n      <div className=\"button-row\">\n        {f && f.status === \"recording\" ? (\n          <button type=\"button\" className=\"button\" onClick={() => { store.stopFrap(); announce(\"Recording stopped.\", { topic: \"frap\" }); }}>\n            Stop recording\n          </button>\n        ) : null}\n        {f ? (\n          <button type=\"button\" className=\"button\" onClick={() => download(`condensate-lab-frap-droplet-${f.dropletId}.csv`, frapCsv(f), \"text/csv\")}>\n            Download this curve (CSV)\n          </button>\n        ) : null}\n      </div>\n\n      {runs.length > 0 ? (\n        <>\n          <SortableTable\n            caption=\"Finished FRAP runs, to compare\"\n            rows={runs}\n            rowKey={(r) => r.id}\n            columns={[\n              { key: \"run\", label: \"Run\", value: (r) => r.id, numeric: true },\n              { key: \"droplet\", label: \"Droplet\", value: (r) => r.dropletId, numeric: true },\n              { key: \"state\", label: \"State when bleached\", value: (r) => r.solidAtBleach, format: (r) => STATE_LABEL[r.stateAtBleach] },\n              { key: \"mobile\", label: \"Mobile fraction\", value: (r) => (r.fit && r.fit.ok ? r.fit.fit.mobileFraction : -1), format: (r) => (r.fit && r.fit.ok ? pct(r.fit.fit.mobileFraction) : \"–\"), numeric: true },\n              {\n                key: \"half\",\n                label: \"Half-time\",\n                value: (r) => (r.fit && r.fit.ok && Number.isFinite(r.fit.fit.halfTime) ? r.fit.fit.halfTime : Number.MAX_VALUE),\n                format: (r) => (r.fit && r.fit.ok ? (Number.isFinite(r.fit.fit.halfTime) ? formatTime(r.fit.fit.halfTime) : \"not measurable\") : \"–\"),\n                numeric: true,\n              },\n              { key: \"quality\", label: \"Fit\", value: (r) => (r.fit && r.fit.ok && r.fit.reliable ? 1 : 0), format: (r) => (r.fit && r.fit.ok ? (r.fit.reliable ? \"Good\" : \"Uncertain\") : \"None\") },\n            ]}\n          />\n          <div className=\"button-row\">\n            <button type=\"button\" className=\"button secondary\" onClick={() => store.clearFrapRuns()}>\n              Clear finished runs\n            </button>\n          </div>\n        </>\n      ) : null}\n\n      <h3>Compare with your own FRAP data</h3>\n      <p>\n        Load a CSV or tab-separated file with two columns: time and intensity. It is read on this device and never uploaded. Readings before the bleach,\n        if present, are used to scale the curve to 1.\n      </p>\n      <div className=\"file-field\">\n        <label htmlFor={fileId} className=\"button\">\n          Choose a FRAP file\n        </label>\n        <input\n          id={fileId}\n          type=\"file\"\n          accept=\".csv,.tsv,.txt,text/csv,text/plain\"\n          className=\"file-input\"\n          onChange={async (e) => {\n            const file = e.target.files?.[0];\n            if (!file) return;\n            const text = await file.text();\n            const m = store.importFrap(file.name, text);\n            setMsg(m);\n            announce(m, { topic: \"import\" });\n            e.target.value = \"\";\n          }}\n        />\n      </div>\n      {msg ? (\n        <p className=\"note\" role=\"status\">\n          {msg}\n        </p>\n      ) : null}\n      {imp ? (\n        <>\n          <LineChart\n            title={`Your data: ${imp.name}`}\n            summary={`${imp.points.length} readings. ${imp.notes.join(\" \")} ${fitLines(imp.fit).join(\" \")}`}\n            xLabel=\"Time since bleach (your units)\"\n            yLabel=\"Relative brightness\"\n            xFormat={(v) => (Math.abs(v) < 100 ? v.toFixed(1) : Math.round(v).toString())}\n            yFormat={(v) => v.toFixed(2)}\n            yDomain={[0, 1.2]}\n            refLines={[{ axis: \"y\", value: 1, label: \"Brightness before bleaching (1)\" }]}\n            series={impSeries}\n            emptyText=\"No readings.\"\n            {...chartInk(colors)}\n          />\n          {lastRun && lastRun.fit && lastRun.fit.ok && imp.fit.ok ? (\n            <p>\n              Mobile fraction: your data {pct(imp.fit.fit.mobileFraction)}, last simulated run {pct(lastRun.fit.fit.mobileFraction)}. Half-times cannot be compared\n              directly: the simulation uses arbitrary time units.\n            </p>\n          ) : null}\n          <div className=\"button-row\">\n            <button type=\"button\" className=\"button\" onClick={() => download(\"your-frap-rescaled.csv\", importedCsv(imp), \"text/csv\")}>\n              Download rescaled data (CSV)\n            </button>\n            <button type=\"button\" className=\"button secondary\" onClick={() => { store.clearImported(); setMsg(\"Your data was removed from the page.\"); }}>\n              Remove your data\n            </button>\n          </div>\n        </>\n      ) : null}\n    </div>\n  );\n}\n\n// ─── Threshold scan ─────────────────────────────────────────────────────────\n\nconst SCAN_LABEL: Record<ScanKey, { name: string; axis: string; fmt: (v: number) => string }> = {\n  chi: { name: \"Stickiness (χ)\", axis: \"Stickiness (χ)\", fmt: (v) => v.toFixed(1) },\n  proteinCount: { name: \"Protein molecules\", axis: \"Protein molecules\", fmt: (v) => String(Math.round(v)) },\n  temperature: { name: \"Temperature\", axis: \"Temperature (kT)\", fmt: (v) => v.toFixed(1) },\n};\n\nexport function ScanPanel({ colors }: { colors: ThemeColors }) {\n  const store = useStore();\n  const snap = useSnapshot();\n  const [key, setKey] = useState<ScanKey>(\"chi\");\n  const groupId = useId();\n  const scan = snap.scan;\n  const running = scan?.status === \"running\";\n  let verdict = \"\";\n  if (scan && scan.points.length >= 2) {\n    const th = scanThreshold(scan);\n    const L = SCAN_LABEL[scan.key];\n    if (th.kind === \"crossing\")\n      verdict = th.rising\n        ? `Droplets start at about ${L.name.toLowerCase()} ${L.fmt(th.value)} (where 30% of the protein is in droplets), with your other settings.`\n        : `Droplets disappear above about ${L.name.toLowerCase()} ${L.fmt(th.value)} (where protein in droplets drops below 30%), with your other settings.`;\n    else if (th.kind === \"all\") verdict = \"Droplets formed at every value tested, so the threshold is below this range.\";\n    else if (th.kind === \"none\") verdict = \"No droplets formed at any value tested: with your other settings, the mix stays mixed across this range.\";\n    else verdict = \"Uncertain: the results go up and down, so there is no single clear threshold.\";\n  }\n  const L = SCAN_LABEL[scan?.key ?? key];\n  return (\n    <div className=\"panel-body\">\n      <p>\n        Finds where droplets start by running the simulation many times in the background, changing one setting and keeping the rest of your settings.\n        It measures this model&apos;s own threshold (its saturation point), rather than the textbook theory&apos;s.\n      </p>\n      <fieldset className=\"radio-group\">\n        <legend>Change</legend>\n        {(Object.keys(SCAN_LABEL) as ScanKey[]).map((k) => (\n          <label key={k} className=\"radio\">\n            <input type=\"radio\" name={groupId} checked={key === k} onChange={() => setKey(k)} disabled={running} />\n            {SCAN_LABEL[k].name}\n          </label>\n        ))}\n      </fieldset>\n      <div className=\"button-row\">\n        <button\n          type=\"button\"\n          className=\"button primary\"\n          aria-disabled={running}\n          onClick={() => {\n            if (running) return;\n            store.runScan(key);\n            announce(`Scanning ${SCAN_LABEL[key].name.toLowerCase()}. This takes a little while; results appear as they finish.`, { topic: \"scan\" });\n          }}\n        >\n          Find the threshold\n        </button>\n        <button\n          type=\"button\"\n          className=\"button\"\n          aria-disabled={!running}\n          onClick={() => {\n            if (!running) return;\n            store.cancelScan();\n            announce(\"Scan cancelled.\", { topic: \"scan\" });\n          }}\n        >\n          Cancel scan\n        </button>\n      </div>\n      {scan ? (\n        <>\n          <p role=\"status\" className=\"note\">\n            {scan.status === \"running\"\n              ? `Running: ${scan.points.length} of ${scan.total} values done.`\n              : scan.status === \"cancelled\"\n                ? `Cancelled after ${scan.points.length} of ${scan.total} values.`\n                : `Done: ${scan.total} values, each run twice from different random starts for 500 time units.`}{\" \"}\n            {verdict}\n          </p>\n          <LineChart\n            title={`Protein in droplets as ${L.name.toLowerCase()} changes`}\n            summary={`${verdict || \"Results appear as each value finishes.\"} Disease mode is off during the scan.`}\n            xLabel={L.axis}\n            yLabel=\"Percent of protein in droplets\"\n            xFormat={L.fmt}\n            yFormat={(v) => `${Math.round(v)}%`}\n            yDomain={[0, 100]}\n            refLines={[{ axis: \"y\", value: 30, label: \"30%: counted as forming droplets\" }]}\n            series={[\n              { name: \"Average of two runs\", points: scan.points.map((p) => ({ x: p.value, y: p.fraction * 100 })), color: colors.protein, marker: \"circle\" },\n              { name: \"Lowest run\", points: scan.points.map((p) => ({ x: p.value, y: p.min * 100 })), color: colors.muted, marker: \"triangle\", line: false },\n              { name: \"Highest run\", points: scan.points.map((p) => ({ x: p.value, y: p.max * 100 })), color: colors.muted, marker: \"square\", line: false },\n            ]}\n            emptyText=\"Results appear as each value finishes.\"\n            {...chartInk(colors)}\n          />\n          <div className=\"button-row\">\n            <button type=\"button\" className=\"button\" aria-disabled={scan.points.length === 0} onClick={() => scan.points.length && download(`condensate-lab-scan-${scan.key}.csv`, scanCsv(scan), \"text/csv\")}>\n              Download scan (CSV)\n            </button>\n          </div>\n        </>\n      ) : null}\n    </div>\n  );\n}\n\n// ─── Theory ──────────────────────────────────────────────────────────────────\n\nexport function TheoryPanel({ colors }: { colors: ThemeColors }) {\n  const snap = useSnapshot();\n  const p = snap.params;\n  const chi = Number((effectiveChi(p) / p.temperature).toFixed(2));\n  const curve = freeEnergyCurve(chi);\n  const b = binodal(chi);\n  const s = spinodal(chi);\n  const series: Series[] = [{ name: \"Free energy of mixing\", points: curve.map((q) => ({ x: q.phi, y: q.f })), color: colors.protein, marker: \"none\" }];\n  if (b)\n    series.push({\n      name: \"Where the two phases settle (binodal)\",\n      points: [b.low, b.high].map((x) => ({ x: Number(x.toFixed(4)), y: freeEnergy(x, chi) })),\n      color: colors.rna,\n      marker: \"diamond\",\n      line: false,\n    });\n  if (s)\n    series.push({\n      name: \"Edge of instant separation (spinodal)\",\n      points: [s.low, s.high].map((x) => ({ x: Number(x.toFixed(4)), y: freeEnergy(x, chi) })),\n      color: colors.solid,\n      marker: \"square\",\n      line: false,\n    });\n  const summary = b\n    ? `χ = ${chi.toFixed(2)}, above the critical value ${CRITICAL_CHI}: the curve has two dips. A mixture between φ = ${b.low.toFixed(2)} and φ = ${b.high.toFixed(2)} lowers its free energy by splitting into a dilute phase (φ ≈ ${b.low.toFixed(2)}) and a dense phase (φ ≈ ${b.high.toFixed(2)}). Between φ = ${s!.low.toFixed(2)} and ${s!.high.toFixed(2)} it separates at once.`\n    : `χ = ${chi.toFixed(2)}, at or below the critical value ${CRITICAL_CHI}: the curve has a single dip, so every mixture stays mixed.`;\n  return (\n    <div className=\"panel-body\">\n      <p>\n        Flory-Huggins theory, the textbook model of mixing. The horizontal axis, φ (phi), is the share of space taken by the sticky molecules. The\n        curve is the free energy of mixing (in units of kT): lower is more stable.\n      </p>\n      <p className=\"note\">\n        χ here = stickiness × the pH and crowding effects ÷ temperature, from your settings. The theory explains the idea; it does not predict this\n        simulation&apos;s exact threshold. Use the Threshold tab for that.\n      </p>\n      <LineChart\n        title=\"Free energy of mixing against composition\"\n        summary={summary}\n        xLabel=\"φ (share of space)\"\n        yLabel=\"Free energy (kT)\"\n        xFormat={(v) => v.toFixed(2)}\n        yFormat={(v) => v.toFixed(2)}\n        xDomain={[0, 1]}\n        series={series}\n        emptyText=\"No curve.\"\n        {...chartInk(colors)}\n      />\n    </div>\n  );\n}\n\n// ─── Log ─────────────────────────────────────────────────────────────────────\n\nexport function LogPanel() {\n  const snap = useSnapshot();\n  const events = [...snap.events].reverse();\n  return (\n    <div className=\"panel-body\">\n      <p>Every change the simulation reported in this run, newest first. The same messages are spoken to screen readers, a few at a time.</p>\n      {events.length === 0 ? (\n        <p className=\"muted\">Nothing yet.</p>\n      ) : (\n        <ol className=\"log\" reversed tabIndex={0} aria-label=\"Changes, newest first\">\n          {events.map((e) => (\n            <li key={e.id}>\n              <span className=\"mono muted\">t {formatTime(e.t)}</span> {e.text}\n            </li>\n          ))}\n        </ol>\n      )}\n    </div>\n  );\n}\n",
    "apps/condensate-lab/components/Playback.tsx": "\"use client\";\n\nimport { announce } from \"@repo/access\";\nimport { useId } from \"react\";\nimport { formatTime, headline } from \"@/lib/describe\";\nimport { SPEEDS } from \"@/lib/store\";\nimport { useSnapshot, useStore } from \"./LabContext\";\nimport type { PictureMode } from \"./SimCanvas\";\n\nexport function Playback({ mode, setMode }: { mode: PictureMode; setMode: (m: PictureMode) => void }) {\n  const store = useStore();\n  const snap = useSnapshot();\n  const speedId = useId();\n  const modeId = useId();\n\n  const after = (verb: string) => {\n    const s = store.getSnapshot();\n    announce(`${verb} Time ${formatTime(s.time)}. ${headline(s.summary)}`, { topic: \"play\" });\n  };\n\n  return (\n    <div className=\"playback\" role=\"group\" aria-label=\"Simulation controls\">\n      <div className=\"playback-row\">\n        <button\n          type=\"button\"\n          className=\"button primary play\"\n          onClick={() => {\n            store.toggle();\n            announce(store.getSnapshot().running ? \"Playing.\" : `Paused at time ${formatTime(store.getSnapshot().time)}.`, { topic: \"play\" });\n          }}\n        >\n          <span aria-hidden=\"true\" className=\"glyph\">\n            {snap.running ? \"❚❚\" : \"▶\"}\n          </span>\n          {snap.running ? \"Pause\" : \"Play\"}\n        </button>\n        <button\n          type=\"button\"\n          className=\"button\"\n          onClick={() => {\n            store.stepOnce();\n            after(\"Stepped forward.\");\n          }}\n        >\n          Step\n        </button>\n        <button\n          type=\"button\"\n          className=\"button\"\n          onClick={() => {\n            store.jump(100);\n            after(\"Jumped ahead 100 time units.\");\n          }}\n        >\n          Jump ahead 100\n        </button>\n        <button\n          type=\"button\"\n          className=\"button\"\n          onClick={() => {\n            store.jump(1000);\n            after(\"Jumped ahead 1000 time units.\");\n          }}\n        >\n          Jump ahead 1000\n        </button>\n        <button\n          type=\"button\"\n          className=\"button\"\n          onClick={() => {\n            store.reset();\n            announce(\"Reset: a new run with the same settings and the same starting positions.\", { topic: \"play\" });\n          }}\n        >\n          Reset\n        </button>\n        <button\n          type=\"button\"\n          className=\"button\"\n          onClick={() => {\n            store.newSeed();\n            announce(`New random start, seed ${store.getSnapshot().params.seed}.`, { topic: \"play\" });\n          }}\n        >\n          New random start\n        </button>\n      </div>\n      <div className=\"playback-row\">\n        <p className=\"time\" aria-live=\"off\">\n          Time <span className=\"mono\">{formatTime(snap.time)}</span>\n          <span className=\"time-unit\"> (arbitrary units)</span>\n        </p>\n        <div className=\"inline-field\">\n          <label htmlFor={speedId}>Speed</label>\n          <select\n            id={speedId}\n            className=\"select\"\n            value={snap.speed}\n            onChange={(e) => {\n              store.setSpeed(Number(e.target.value));\n            }}\n          >\n            {SPEEDS.map((s) => (\n              <option key={s} value={s}>\n                {s === 1 ? \"Normal\" : s < 1 ? `Slow (${s}×)` : `Fast (${s}×)`}\n              </option>\n            ))}\n          </select>\n        </div>\n        <div className=\"inline-field\">\n          <label htmlFor={modeId}>Picture updates</label>\n          <select id={modeId} className=\"select\" value={mode} onChange={(e) => setMode(e.target.value as PictureMode)}>\n            <option value=\"live\">Smoothly</option>\n            <option value=\"second\">Once a second</option>\n            <option value=\"still\">Only when paused</option>\n          </select>\n        </div>\n      </div>\n    </div>\n  );\n}\n",
    "apps/condensate-lab/components/SimCanvas.tsx": "\"use client\";\n\nimport { announce } from \"@repo/access\";\nimport { useEffect, useRef } from \"react\";\nimport { describeDroplet } from \"@/lib/describe\";\nimport { KIND_RNA, SIGMA, WORLD_H, WORLD_W } from \"@/lib/sim/engine\";\nimport type { LabStore, Snapshot } from \"@/lib/store\";\nimport { useSnapshot, useStore } from \"./LabContext\";\nimport type { ThemeColors } from \"./useTheme\";\n\nexport type PictureMode = \"live\" | \"second\" | \"still\";\n\nfunction draw(canvas: HTMLCanvasElement, store: LabStore, snap: Snapshot, c: ThemeColors) {\n  const ctx = canvas.getContext(\"2d\");\n  if (!ctx) return;\n  const w = store.world;\n  const cssW = canvas.clientWidth || WORLD_W;\n  const cssH = canvas.clientHeight || WORLD_H;\n  const dpr = Math.min(2, window.devicePixelRatio || 1);\n  if (canvas.width !== Math.round(cssW * dpr) || canvas.height !== Math.round(cssH * dpr)) {\n    canvas.width = Math.round(cssW * dpr);\n    canvas.height = Math.round(cssH * dpr);\n  }\n  const k = (cssW / WORLD_W) * dpr;\n  ctx.setTransform(k, 0, 0, k, 0, 0);\n  ctx.fillStyle = c.paper;\n  ctx.fillRect(0, 0, WORLD_W, WORLD_H);\n  // faint grid in thirds, matching the region names (top left, centre, …)\n  ctx.strokeStyle = c.grid;\n  ctx.lineWidth = 1 / (k / dpr);\n  ctx.beginPath();\n  for (const gx of [WORLD_W / 3, (2 * WORLD_W) / 3]) {\n    ctx.moveTo(gx, 0);\n    ctx.lineTo(gx, WORLD_H);\n  }\n  for (const gy of [WORLD_H / 3, (2 * WORLD_H) / 3]) {\n    ctx.moveTo(0, gy);\n    ctx.lineTo(WORLD_W, gy);\n  }\n  ctx.stroke();\n\n  const r = SIGMA / 2 - 0.4;\n  const lw = (c.stroke * 1.2) / (k / dpr);\n  ctx.lineWidth = lw;\n  for (let i = 0; i < w.n; i++) {\n    const x = w.x[i];\n    const y = w.y[i];\n    const bleached = w.bleached[i] === 1;\n    let color: string;\n    ctx.beginPath();\n    if (w.solid[i]) {\n      color = c.solid;\n      const s = r * 1.75;\n      ctx.rect(x - s / 2, y - s / 2, s, s);\n    } else if (w.kind[i] === KIND_RNA) {\n      color = c.rna;\n      ctx.moveTo(x, y - r * 1.15);\n      ctx.lineTo(x + r, y + r * 0.75);\n      ctx.lineTo(x - r, y + r * 0.75);\n      ctx.closePath();\n    } else {\n      color = c.protein;\n      ctx.arc(x, y, r, 0, Math.PI * 2);\n    }\n    if (bleached) {\n      ctx.strokeStyle = color;\n      ctx.stroke();\n    } else {\n      ctx.fillStyle = color;\n      ctx.fill();\n    }\n  }\n\n  // droplet outlines and numbers\n  ctx.font = `600 ${11}px system-ui, sans-serif`;\n  ctx.textAlign = \"center\";\n  ctx.textBaseline = \"bottom\";\n  for (const d of snap.droplets) {\n    const selected = d.id === snap.selectedId;\n    ctx.beginPath();\n    ctx.arc(d.cx, d.cy, d.radius + 2, 0, Math.PI * 2);\n    ctx.setLineDash(selected ? [] : [4, 3]);\n    ctx.lineWidth = (selected ? 3 * c.stroke : 1.2 * c.stroke) / (k / dpr);\n    ctx.strokeStyle = selected ? c.accent : c.muted;\n    ctx.stroke();\n    ctx.setLineDash([]);\n    const label = String(d.id);\n    const ly = Math.max(14, d.cy - d.radius - 4);\n    const tw = ctx.measureText(label).width + 6;\n    ctx.fillStyle = c.paper;\n    ctx.fillRect(d.cx - tw / 2, ly - 12, tw, 13);\n    ctx.fillStyle = selected ? c.accent : c.ink;\n    ctx.fillText(label, d.cx, ly);\n  }\n\n  // FRAP spot\n  const f = snap.frap;\n  if (f && f.status === \"recording\") {\n    ctx.beginPath();\n    ctx.arc(f.cx, f.cy, f.radius, 0, Math.PI * 2);\n    ctx.setLineDash([2, 2]);\n    ctx.lineWidth = (2 * c.stroke) / (k / dpr);\n    ctx.strokeStyle = c.ink;\n    ctx.stroke();\n    ctx.setLineDash([]);\n    ctx.beginPath();\n    ctx.moveTo(f.cx - 4, f.cy);\n    ctx.lineTo(f.cx + 4, f.cy);\n    ctx.moveTo(f.cx, f.cy - 4);\n    ctx.lineTo(f.cx, f.cy + 4);\n    ctx.stroke();\n  }\n}\n\nexport function SimCanvas({\n  colors,\n  mode,\n  labelId,\n  describedBy,\n  onBleach,\n}: {\n  colors: ThemeColors;\n  mode: PictureMode;\n  labelId: string;\n  describedBy: string;\n  onBleach: () => void;\n}) {\n  const store = useStore();\n  const snap = useSnapshot();\n  const ref = useRef<HTMLCanvasElement>(null);\n  const latest = useRef({ snap, colors, mode });\n  const lastDraw = useRef(0);\n\n  // Redraw on every state change, but while running respect the picture mode:\n  // \"second\" = at most once a second, \"still\" = only when paused or stepped.\n  useEffect(() => {\n    latest.current = { snap, colors, mode };\n    const canvas = ref.current;\n    if (!canvas) return;\n    const now = performance.now();\n    if (snap.running && mode === \"still\") return;\n    if (snap.running && mode === \"second\" && now - lastDraw.current < 1000) return;\n    lastDraw.current = now;\n    draw(canvas, store, snap, colors);\n  }, [store, snap, colors, mode]);\n\n  useEffect(() => {\n    const off = store.onFrame(() => {\n      const { colors: c, mode: m } = latest.current;\n      const canvas = ref.current;\n      if (!canvas) return;\n      const now = performance.now();\n      const running = store.getSnapshot().running;\n      if (running && m === \"still\") return;\n      if (running && m === \"second\" && now - lastDraw.current < 1000) return;\n      lastDraw.current = now;\n      draw(canvas, store, store.getSnapshot(), c);\n    });\n    const ro = new ResizeObserver(() => {\n      const canvas = ref.current;\n      if (canvas) draw(canvas, store, store.getSnapshot(), latest.current.colors);\n    });\n    if (ref.current) ro.observe(ref.current);\n    return () => {\n      off();\n      ro.disconnect();\n    };\n  }, [store]);\n\n  const selectAndSay = (how: \"next\" | \"prev\" | \"first\" | \"last\") => {\n    const d = store.moveSelection(how);\n    if (!d) {\n      announce(\"No droplets to select yet.\", { topic: \"selection\" });\n      return;\n    }\n    const order = store.readingOrder();\n    announce(describeDroplet(d, order.findIndex((x) => x.id === d.id), order.length), { topic: \"selection\" });\n  };\n\n  const onKeyDown = (e: React.KeyboardEvent<HTMLCanvasElement>) => {\n    switch (e.key) {\n      case \"ArrowRight\":\n      case \"ArrowDown\":\n        selectAndSay(\"next\");\n        break;\n      case \"ArrowLeft\":\n      case \"ArrowUp\":\n        selectAndSay(\"prev\");\n        break;\n      case \"Home\":\n        selectAndSay(\"first\");\n        break;\n      case \"End\":\n        selectAndSay(\"last\");\n        break;\n      case \"Enter\":\n      case \"b\":\n      case \"B\":\n        onBleach();\n        break;\n      case \" \":\n        store.toggle();\n        announce(store.getSnapshot().running ? \"Playing.\" : \"Paused.\", { topic: \"play\" });\n        break;\n      case \"Escape\":\n        if (snap.selectedId !== null) {\n          store.select(null);\n          announce(\"No droplet selected.\", { topic: \"selection\" });\n        } else return;\n        break;\n      default:\n        return;\n    }\n    e.preventDefault();\n  };\n\n  const onPointerDown = (e: React.PointerEvent<HTMLCanvasElement>) => {\n    const canvas = ref.current;\n    if (!canvas) return;\n    const rect = canvas.getBoundingClientRect();\n    const x = ((e.clientX - rect.left) / rect.width) * WORLD_W;\n    const y = ((e.clientY - rect.top) / rect.height) * WORLD_H;\n    // generous reach for touch and tremor: up to 3 molecule widths outside a droplet\n    const d = store.dropletAt(x, y, e.pointerType === \"mouse\" ? 1.5 * SIGMA : 3 * SIGMA);\n    store.select(d ? d.id : null);\n    announce(d ? describeDroplet(d) : \"No droplet there. Selection cleared.\", { topic: \"selection\" });\n  };\n\n  return (\n    <canvas\n      ref={ref}\n      className=\"sim-canvas\"\n      tabIndex={0}\n      role=\"application\"\n      aria-roledescription=\"simulation picture\"\n      aria-labelledby={labelId}\n      aria-describedby={describedBy}\n      onKeyDown={onKeyDown}\n      onPointerDown={onPointerDown}\n    />\n  );\n}\n",
    "apps/condensate-lab/components/SortableTable.tsx": "\"use client\";\n\nimport { useState, type ReactNode } from \"react\";\n\nexport interface Column<R> {\n  key: string;\n  label: string;\n  value: (r: R) => number | string;\n  format?: (r: R) => ReactNode;\n  numeric?: boolean;\n}\n\n/**\n * A plain HTML table with sortable columns. Sort buttons sit in the column\n * headers and report their state with aria-sort, so screen readers and\n * braille displays get the same table everyone sees.\n */\nexport function SortableTable<R>({\n  caption,\n  columns,\n  rows,\n  rowKey,\n  initialSort,\n  action,\n  limit,\n  emptyText = \"No rows yet.\",\n}: {\n  caption: ReactNode;\n  columns: Column<R>[];\n  rows: R[];\n  rowKey: (r: R) => string | number;\n  initialSort?: { key: string; dir: \"asc\" | \"desc\" };\n  action?: { label: string; render: (r: R) => ReactNode };\n  /** Show at most this many rows (evenly spaced); the caption says so. */\n  limit?: number;\n  emptyText?: string;\n}) {\n  const [sort, setSort] = useState(initialSort ?? { key: columns[0].key, dir: \"asc\" as const });\n  const col = columns.find((c) => c.key === sort.key) ?? columns[0];\n  let shown = rows;\n  let thinned = false;\n  if (limit && rows.length > limit) {\n    const stepBy = rows.length / limit;\n    shown = Array.from({ length: limit }, (_, i) => rows[Math.floor(i * stepBy)]);\n    thinned = true;\n  }\n  const sorted = [...shown].sort((a, b) => {\n    const va = col.value(a);\n    const vb = col.value(b);\n    const c = typeof va === \"number\" && typeof vb === \"number\" ? va - vb : String(va).localeCompare(String(vb));\n    return sort.dir === \"asc\" ? c : -c;\n  });\n  return (\n    <div className=\"table-wrap\" role=\"region\" aria-label={typeof caption === \"string\" ? caption : undefined} tabIndex={0}>\n      <table className=\"data-table\">\n        <caption>\n          {caption}\n          {thinned ? ` (${limit} of ${rows.length} rows shown, evenly spaced; download the CSV for all)` : \"\"}\n        </caption>\n        <thead>\n          <tr>\n            {columns.map((c) => {\n              const active = c.key === sort.key;\n              return (\n                <th\n                  key={c.key}\n                  scope=\"col\"\n                  aria-sort={active ? (sort.dir === \"asc\" ? \"ascending\" : \"descending\") : \"none\"}\n                  className={c.numeric ? \"num\" : undefined}\n                >\n                  <button\n                    type=\"button\"\n                    className=\"sort-button\"\n                    onClick={() =>\n                      setSort({ key: c.key, dir: active && sort.dir === \"asc\" ? \"desc\" : \"asc\" })\n                    }\n                  >\n                    {c.label}\n                    <span aria-hidden=\"true\" className=\"sort-mark\">\n                      {active ? (sort.dir === \"asc\" ? \" ▲\" : \" ▼\") : \" ⇅\"}\n                    </span>\n                  </button>\n                </th>\n              );\n            })}\n            {action ? <th scope=\"col\">{action.label}</th> : null}\n          </tr>\n        </thead>\n        <tbody>\n          {sorted.length === 0 ? (\n            <tr>\n              <td colSpan={columns.length + (action ? 1 : 0)}>{emptyText}</td>\n            </tr>\n          ) : (\n            sorted.map((r) => (\n              <tr key={rowKey(r)}>\n                {columns.map((c, i) =>\n                  i === 0 ? (\n                    <th key={c.key} scope=\"row\" className={c.numeric ? \"num\" : undefined}>\n                      {c.format ? c.format(r) : c.value(r)}\n                    </th>\n                  ) : (\n                    <td key={c.key} className={c.numeric ? \"num\" : undefined}>\n                      {c.format ? c.format(r) : c.value(r)}\n                    </td>\n                  ),\n                )}\n                {action ? <td>{action.render(r)}</td> : null}\n              </tr>\n            ))\n          )}\n        </tbody>\n      </table>\n    </div>\n  );\n}\n",
    "apps/condensate-lab/components/Status.tsx": "\"use client\";\n\nimport { announce, useAccess, vibrate } from \"@repo/access\";\nimport { useEffect, useRef } from \"react\";\nimport { describeDroplet, digest, formatTime, headline, PHASE_LABEL, pct, rnaSentence, STATE_LABEL, trendSentence } from \"@/lib/describe\";\nimport { earcon, setDrone } from \"@/lib/sonify\";\nimport { FRAP_MIN_SIZE, type EventKind, type LabEvent } from \"@/lib/store\";\nimport { useSnapshot, useStore } from \"./LabContext\";\n\nconst PRIORITY: EventKind[] = [\"solidified\", \"dissolved\", \"merged\", \"formed\", \"info\"];\nconst BUZZ: Partial<Record<EventKind, number[]>> = {\n  formed: [40],\n  merged: [40, 60, 40],\n  dissolved: [120],\n  solidified: [200, 80, 200],\n};\n\n/**\n * Turns state changes into announcements, sounds and vibration. Visual and\n * text channels are always on; sound and vibration follow the settings.\n */\nexport function useChangeChannels(spoken: boolean, listen: boolean) {\n  const snap = useSnapshot();\n  const access = useAccess();\n  const lastEvent = useRef(0);\n  const lastRun = useRef(snap.runId);\n  const prev = useRef<{ count: number; fraction: number } | null>(null);\n\n  useEffect(() => {\n    if (lastRun.current !== snap.runId) {\n      lastRun.current = snap.runId;\n      lastEvent.current = 0;\n      prev.current = null;\n    }\n    const fresh: LabEvent[] = snap.events.filter((e) => e.id > lastEvent.current);\n    if (fresh.length) lastEvent.current = fresh[fresh.length - 1].id;\n    if (!snap.running && fresh.every((e) => e.kind === \"info\")) {\n      // actions while paused announce their own result\n      prev.current = { count: snap.summary.count, fraction: snap.summary.fraction };\n      return;\n    }\n    const kinds = new Set(fresh.map((e) => e.kind));\n    const top = PRIORITY.find((k) => kinds.has(k) && k !== \"info\");\n    if (top && access.settings.sound) earcon(top);\n    if (top && BUZZ[top]) vibrate(BUZZ[top]!, access.settings);\n    if (spoken) {\n      const text = digest(fresh, snap.summary, prev.current);\n      if (text) {\n        announce(text, { topic: \"digest\" });\n        prev.current = { count: snap.summary.count, fraction: snap.summary.fraction };\n      }\n    }\n  }, [snap, access.settings, spoken]);\n\n  useEffect(() => {\n    if (listen) setDrone(snap.summary.fraction);\n  }, [listen, snap.summary.fraction]);\n  useEffect(() => {\n    if (!listen) setDrone(null);\n    return () => setDrone(null);\n  }, [listen]);\n}\n\nexport function StatusSummary({ id }: { id: string }) {\n  const snap = useSnapshot();\n  const s = snap.summary;\n  const latest = [...snap.events].reverse().find((e) => e.kind !== \"info\") ?? snap.events[snap.events.length - 1];\n  const rna = rnaSentence(s);\n  return (\n    <div className=\"status\">\n      <p className=\"status-phase\">\n        <span className={`badge phase-${s.phase}`}>\n          <span aria-hidden=\"true\" className=\"badge-glyph\">\n            {s.phase === \"separated\" ? \"●●\" : s.phase === \"borderline\" ? \"●·\" : \"··\"}\n          </span>\n          {PHASE_LABEL[s.phase]}\n        </span>\n        <span className=\"status-stats\">\n          <span>\n            <strong>{s.count}</strong> droplets\n          </span>\n          <span>\n            <strong>{pct(s.fraction)}</strong> of protein in droplets\n          </span>\n          {s.solidFraction > 0 ? (\n            <span>\n              <strong>{pct(s.solidFraction)}</strong> solid\n            </span>\n          ) : null}\n        </span>\n      </p>\n      <p id={id} className=\"status-text\">\n        {headline(s)} {trendSentence(s, snap.running)} {rna}\n      </p>\n      {latest ? (\n        <p className=\"status-latest\">\n          <span className=\"label\">Latest change</span> {latest.text}{\" \"}\n          <span className=\"muted\">(time {formatTime(latest.t)})</span>\n        </p>\n      ) : null}\n    </div>\n  );\n}\n\nexport function SelectionCard({ onBleach }: { onBleach: () => void }) {\n  const store = useStore();\n  const snap = useSnapshot();\n  const order = store.readingOrder();\n  const d = snap.droplets.find((x) => x.id === snap.selectedId) ?? null;\n  const nextRef = useRef<HTMLButtonElement>(null);\n  const say = (how: \"next\" | \"prev\") => {\n    const nd = store.moveSelection(how);\n    if (!nd) announce(\"No droplets to select yet.\", { topic: \"selection\" });\n    else {\n      const o = store.readingOrder();\n      announce(describeDroplet(nd, o.findIndex((x) => x.id === nd.id), o.length), { topic: \"selection\" });\n    }\n  };\n  return (\n    <section className=\"selection\" aria-labelledby=\"sel-h\">\n      <h3 id=\"sel-h\">Selected droplet</h3>\n      {d ? (\n        <>\n          <p>{describeDroplet(d, order.findIndex((x) => x.id === d.id), order.length)}</p>\n          <p className=\"muted\">\n            State: {STATE_LABEL[d.state]}\n            {d.state !== \"liquid\" ? ` (${pct(d.solidFraction)} of its protein is solid)` : \"\"}. About {Math.max(1, Math.round((2 * d.radius) / 10))} molecules across.\n          </p>\n          {d.size < FRAP_MIN_SIZE ? (\n            <p className=\"note\">Too small to bleach part of it: bleaching needs at least {FRAP_MIN_SIZE} molecules.</p>\n          ) : null}\n        </>\n      ) : (\n        <p className=\"muted\">\n          {snap.droplets.length === 0\n            ? \"No droplets yet.\"\n            : \"None. Click or tap a droplet, use the buttons below, or focus the picture and use the arrow keys.\"}\n        </p>\n      )}\n      {/* aria-disabled rather than disabled: a button that loses its droplet keeps keyboard focus */}\n      <div className=\"button-row\">\n        <button type=\"button\" className=\"button\" onClick={() => say(\"prev\")} aria-disabled={snap.droplets.length === 0}>\n          Previous droplet\n        </button>\n        <button ref={nextRef} type=\"button\" className=\"button\" onClick={() => say(\"next\")} aria-disabled={snap.droplets.length === 0}>\n          Next droplet\n        </button>\n        <button\n          type=\"button\"\n          className=\"button primary\"\n          aria-disabled={!d}\n          onClick={() => (d ? onBleach() : announce(\"Select a droplet first.\", { topic: \"selection\" }))}\n        >\n          Bleach a spot\n        </button>\n        <button\n          type=\"button\"\n          className=\"button secondary\"\n          aria-disabled={!d}\n          onClick={() => {\n            if (!d) return;\n            store.select(null);\n            announce(\"No droplet selected.\", { topic: \"selection\" });\n            nextRef.current?.focus();\n          }}\n        >\n          Deselect\n        </button>\n      </div>\n    </section>\n  );\n}\n",
    "apps/condensate-lab/components/Tabs.tsx": "\"use client\";\n\nimport { useId, useRef, type ReactNode } from \"react\";\n\nexport interface TabDef {\n  id: string;\n  label: string;\n  content: ReactNode;\n}\n\n/** ARIA tabs: arrow keys move between tabs, Tab moves into the open panel. */\nexport function Tabs({ label, tabs, current, onChange }: { label: string; tabs: TabDef[]; current: string; onChange: (id: string) => void }) {\n  const uid = useId();\n  const refs = useRef<(HTMLButtonElement | null)[]>([]);\n  const idx = Math.max(0, tabs.findIndex((t) => t.id === current));\n  const go = (i: number) => {\n    const j = (i + tabs.length) % tabs.length;\n    onChange(tabs[j].id);\n    refs.current[j]?.focus();\n  };\n  return (\n    <div className=\"tabs\">\n      <div role=\"tablist\" aria-label={label} className=\"tablist\">\n        {tabs.map((t, i) => (\n          <button\n            key={t.id}\n            ref={(el) => {\n              refs.current[i] = el;\n            }}\n            role=\"tab\"\n            type=\"button\"\n            id={`${uid}-tab-${t.id}`}\n            aria-selected={i === idx}\n            aria-controls={`${uid}-panel-${t.id}`}\n            tabIndex={i === idx ? 0 : -1}\n            className=\"tab\"\n            onClick={() => onChange(t.id)}\n            onKeyDown={(e) => {\n              if (e.key === \"ArrowRight\") go(i + 1);\n              else if (e.key === \"ArrowLeft\") go(i - 1);\n              else if (e.key === \"Home\") go(0);\n              else if (e.key === \"End\") go(tabs.length - 1);\n              else return;\n              e.preventDefault();\n            }}\n          >\n            {t.label}\n          </button>\n        ))}\n      </div>\n      {tabs.map((t, i) => (\n        <div\n          key={t.id}\n          role=\"tabpanel\"\n          id={`${uid}-panel-${t.id}`}\n          aria-labelledby={`${uid}-tab-${t.id}`}\n          hidden={i !== idx}\n          tabIndex={0}\n          className=\"tabpanel\"\n        >\n          {i === idx ? t.content : null}\n        </div>\n      ))}\n    </div>\n  );\n}\n",
    "apps/condensate-lab/components/useTheme.ts": "\"use client\";\n\nimport { categoryColors, useAccess } from \"@repo/access\";\nimport { useEffect, useState } from \"react\";\n\nexport interface ThemeColors {\n  protein: string;\n  rna: string;\n  solid: string;\n  paper: string;\n  ink: string;\n  muted: string;\n  accent: string;\n  grid: string;\n  /** Outline width multiplier (thicker in high contrast). */\n  stroke: number;\n}\n\nconst FALLBACK: ThemeColors = {\n  protein: \"#0072B2\",\n  rna: \"#D55E00\",\n  solid: \"#009E73\",\n  paper: \"#FBFAF7\",\n  ink: \"#1A1D21\",\n  muted: \"#4B5563\",\n  accent: \"#0B5FA5\",\n  grid: \"#E5E3DC\",\n  stroke: 1,\n};\n\nfunction cssVar(name: string, fallback: string): string {\n  if (typeof document === \"undefined\") return fallback;\n  const v = getComputedStyle(document.documentElement).getPropertyValue(name).trim();\n  return v || fallback;\n}\n\n/** Colours for drawing (canvas, SVG), from the shared palette and the page's CSS variables. */\nexport function useThemeColors(): ThemeColors {\n  const access = useAccess();\n  const [colors, setColors] = useState<ThemeColors>(FALLBACK);\n  useEffect(() => {\n    // CSS variables change with the data attributes applied by the settings; read them after they apply.\n    const id = requestAnimationFrame(() => {\n      const cat = categoryColors(access.paletteName, access.dark);\n      setColors({\n        protein: cat[0],\n        rna: cat[1],\n        solid: cat[2],\n        paper: cssVar(\"--canvas\", FALLBACK.paper),\n        ink: cssVar(\"--ink\", FALLBACK.ink),\n        muted: cssVar(\"--muted\", FALLBACK.muted),\n        accent: cssVar(\"--accent\", FALLBACK.accent),\n        grid: cssVar(\"--grid\", FALLBACK.grid),\n        stroke: access.highContrast ? 2 : 1,\n      });\n    });\n    return () => cancelAnimationFrame(id);\n  }, [access]);\n  return colors;\n}\n",
    "apps/condensate-lab/lib/content.ts": "// Words the app uses: presets, the guide, glossary and model limits.\n// Kept together so the explanations stay consistent everywhere.\n\nimport type { SimParams } from \"./sim/params\";\n\nexport interface Preset {\n  id: string;\n  name: string;\n  /** One line on what it shows. */\n  summary: string;\n  params: Partial<SimParams>;\n}\n\n/** Illustrative settings inspired by real structures. Not measurements of them. */\nexport const PRESETS: readonly Preset[] = [\n  {\n    id: \"default\",\n    name: \"Starting mix\",\n    summary: \"A moderate mix that forms droplets: a good place to start.\",\n    params: { proteinCount: 160, rnaCount: 40, chi: 3, temperature: 1, pH: 7, crowding: 1, multiComponent: true, diseaseMode: false, aggregationRate: 1 },\n  },\n  {\n    id: \"stress-granule\",\n    name: \"Stress granule\",\n    summary: \"Lots of RNA pulled into protein droplets, as when a stressed cell parks its RNA.\",\n    params: { proteinCount: 200, rnaCount: 140, chi: 3.2, temperature: 1, pH: 7.2, crowding: 1.1, multiComponent: true, diseaseMode: false },\n  },\n  {\n    id: \"threshold\",\n    name: \"Near the threshold\",\n    summary: \"Just sticky enough: small droplets appear and vanish.\",\n    params: { proteinCount: 160, rnaCount: 40, chi: 1.8, temperature: 1, pH: 7, crowding: 1, multiComponent: true, diseaseMode: false },\n  },\n  {\n    id: \"heat\",\n    name: \"Melting by heat\",\n    summary: \"The same molecules at a higher temperature: droplets dissolve.\",\n    params: { proteinCount: 160, rnaCount: 40, chi: 3, temperature: 2.6, pH: 7, crowding: 1, multiComponent: true, diseaseMode: false },\n  },\n  {\n    id: \"dense\",\n    name: \"Crowded and dense\",\n    summary: \"Many sticky proteins and strong crowding, loosely like the packed nucleolus.\",\n    params: { proteinCount: 320, rnaCount: 80, chi: 4, temperature: 0.9, pH: 7.4, crowding: 1.4, multiComponent: true, diseaseMode: false },\n  },\n  {\n    id: \"als\",\n    name: \"Hardening (ALS-like)\",\n    summary: \"Disease mode on: droplets slowly harden into solid clumps, a simplified picture of what happens with some ALS mutations.\",\n    params: { proteinCount: 200, rnaCount: 30, chi: 4, temperature: 0.9, pH: 6.8, crowding: 1.4, multiComponent: true, diseaseMode: true, aggregationRate: 1.5 },\n  },\n];\n\nexport interface GuideStep {\n  id: string;\n  title: string;\n  body: string[];\n  /** Settings the \"Try it\" button applies. */\n  tryParams?: Partial<SimParams>;\n  tryLabel?: string;\n  /** What to look for after trying. */\n  lookFor?: string;\n}\n\nexport const GUIDE: readonly GuideStep[] = [\n  {\n    id: \"what\",\n    title: \"What is a condensate?\",\n    body: [\n      \"Cells have compartments without walls. Some proteins and RNA gather into droplets, the way oil gathers into drops in vinegar. These droplets are called biomolecular condensates.\",\n      \"A droplet collects the molecules a job needs, so the job goes faster, and it can dissolve again in seconds.\",\n    ],\n    tryParams: { proteinCount: 160, rnaCount: 40, chi: 3, temperature: 1, pH: 7, crowding: 1, diseaseMode: false, multiComponent: true },\n    tryLabel: \"Start the starting mix\",\n    lookFor: \"Within a few seconds, molecules gather into droplets, each outlined and numbered.\",\n  },\n  {\n    id: \"sticky\",\n    title: \"Stickiness decides\",\n    body: [\n      \"Phase separation means one mixture splitting into two parts (phases): a dense part (the droplets) and a dilute part (the liquid around them).\",\n      \"It happens only when molecules are sticky enough. Scientists measure this with a number called χ (chi, said “kai”). Below a threshold, the mixture stays evenly mixed.\",\n    ],\n    tryParams: { chi: 1.0 },\n    tryLabel: \"Lower stickiness to 1.0\",\n    lookFor: \"The droplets break up and the molecules spread out evenly. Then raise stickiness to 3 and watch them come back.\",\n  },\n  {\n    id: \"concentration\",\n    title: \"There is a threshold concentration\",\n    body: [\n      \"Even sticky molecules need company. Below a certain concentration (called the saturation concentration), there are too few to hold a droplet together.\",\n      \"Above it, extra molecules join droplets rather than staying in the liquid.\",\n    ],\n    tryParams: { proteinCount: 60, chi: 2 },\n    tryLabel: \"Use 60 proteins at stickiness 2\",\n    lookFor: \"Few or no droplets. Use “Find the threshold” to measure where droplets start for these settings.\",\n  },\n  {\n    id: \"heat\",\n    title: \"Heat melts droplets\",\n    body: [\n      \"Temperature makes molecules jiggle. When the jiggling beats the stickiness, droplets dissolve, like ice melting.\",\n      \"Many real condensates dissolve when warmed, which is one way cells switch them off.\",\n    ],\n    tryParams: { temperature: 2.6, chi: 3 },\n    tryLabel: \"Raise the temperature to 2.6\",\n    lookFor: \"Droplets shrink and vanish. Lower the temperature again and they reform.\",\n  },\n  {\n    id: \"theory\",\n    title: \"The theory: two dips mean two phases\",\n    body: [\n      \"Flory-Huggins theory gives a curve of “free energy” (roughly, how unhappy the mixture is) against how much of the space the sticky molecules fill.\",\n      \"When χ is above 2, the curve has two dips. The mixture can lower its free energy by splitting into a dilute phase and a dense phase, one at each dip.\",\n    ],\n    lookFor: \"Open the Theory tab and move the stickiness slider: watch one dip turn into two.\",\n  },\n  {\n    id: \"rna\",\n    title: \"Scaffolds and clients\",\n    body: [\n      \"Scaffolds are molecules that build droplets by sticking to each other. Clients only stick to scaffolds, so they join droplets without being able to make them.\",\n      \"Here, proteins are scaffolds and RNA is a client: RNA barely sticks to RNA.\",\n    ],\n    tryParams: { rnaCount: 120, multiComponent: true, chi: 3 },\n    tryLabel: \"Add more RNA\",\n    lookFor: \"The droplets table shows how much RNA each droplet holds. RNA gathers in droplets even though it can't form them on its own.\",\n  },\n  {\n    id: \"frap\",\n    title: \"Liquid or solid? Bleach and watch\",\n    body: [\n      \"FRAP (fluorescence recovery after photobleaching) is how labs test whether a droplet is liquid. They make the molecules glow, then use a laser to bleach a spot dark.\",\n      \"In a liquid, glowing molecules swim back in and the spot recovers quickly. In a solid, molecules are stuck and the spot stays dark.\",\n    ],\n    lookFor: \"Select a droplet and press “Bleach a spot”. The FRAP tab draws the recovery and measures how fast it is.\",\n  },\n  {\n    id: \"disease\",\n    title: \"When liquid turns solid\",\n    body: [\n      \"In diseases such as ALS (a disease that damages nerve cells), some mutations make liquid droplets harden into solid clumps (aggregates) that cells cannot dissolve.\",\n      \"Liquid droplets do their job; solid clumps get in the way. Stopping this hardening is a target for new drugs.\",\n    ],\n    tryParams: { diseaseMode: true, aggregationRate: 1.5, chi: 4, proteinCount: 200 },\n    tryLabel: \"Turn on disease mode\",\n    lookFor: \"Some droplets harden: their molecules turn into squares and stop moving. Bleach one and compare the recovery with a liquid droplet. Turning disease mode off does not undo the clumps.\",\n  },\n];\n\nexport const LIMITS: readonly string[] = [\n  \"It is flat (2D). Real droplets are 3D.\",\n  \"Each molecule is one bead. Real proteins and RNA are long chains with specific sticky patches.\",\n  \"There is no flowing water, no electric charge and no chemistry. pH and crowding are simple multipliers on stickiness.\",\n  \"Units are arbitrary. Times, temperatures and sizes are not seconds, degrees or nanometres.\",\n  \"Hardening in disease mode is a probability rule, not a model of how mutations act.\",\n  \"Simulated droplets hold only tens of molecules, so a single FRAP curve is noisy. Bleach several droplets and compare them in the runs table, as a lab would.\",\n  \"The Theory tab draws the textbook Flory-Huggins curve. It explains the idea but does not predict this simulation's exact threshold; “Find the threshold” measures that.\",\n  \"Presets are illustrative settings inspired by real structures, not measurements of them.\",\n];\n\nexport interface GlossaryEntry {\n  term: string;\n  definition: string;\n}\n\nexport const GLOSSARY: readonly GlossaryEntry[] = [\n  { term: \"Condensate\", definition: \"A droplet of proteins and RNA inside a cell, with no membrane around it.\" },\n  { term: \"Phase separation\", definition: \"A mixture splitting into two parts (phases) with different concentrations, such as droplets and the liquid around them.\" },\n  { term: \"Dense phase\", definition: \"The crowded part: inside the droplets.\" },\n  { term: \"Dilute phase\", definition: \"The sparse part: the liquid between droplets.\" },\n  { term: \"χ (chi)\", definition: \"A number for how much molecules prefer each other over water. Higher means stickier.\" },\n  { term: \"Saturation concentration\", definition: \"The concentration above which droplets form. Below it, everything stays mixed.\" },\n  { term: \"Scaffold\", definition: \"A molecule that builds droplets by sticking to its own kind (here, protein).\" },\n  { term: \"Client\", definition: \"A molecule that joins droplets by sticking to scaffolds but cannot build them (here, RNA).\" },\n  { term: \"FRAP\", definition: \"Fluorescence recovery after photobleaching: bleach a glowing spot and time how fast brightness returns.\" },\n  { term: \"Mobile fraction\", definition: \"The share of molecules that are free to move. Near 100% means liquid; near 0% means solid.\" },\n  { term: \"Half-time\", definition: \"How long the bleached spot takes to recover half of its lost brightness.\" },\n  { term: \"Aggregate\", definition: \"A solid clump of molecules that no longer moves or dissolves.\" },\n  { term: \"Spinodal\", definition: \"On the theory curve, the region where a mixture is so unstable that it separates immediately everywhere.\" },\n  { term: \"Binodal\", definition: \"The two concentrations a separating mixture settles into: one for the dilute phase, one for the dense phase.\" },\n];\n",
    "apps/condensate-lab/lib/describe.ts": "// Text versions of what the picture shows. The same words feed the visible\n// summary, the screen-reader announcements, exported figure descriptions and\n// the droplet list, so every route tells the same story.\n\nimport { SIGMA } from \"./sim/engine\";\nimport type { Droplet, LabEvent, Snapshot, Summary } from \"./store\";\n\nexport function pct(x: number): string {\n  return `${Math.round(x * 100)}%`;\n}\n\nexport function plural(n: number, one: string, many = `${one}s`): string {\n  return `${n} ${n === 1 ? one : many}`;\n}\n\nexport const PHASE_LABEL: Record<Summary[\"phase\"], string> = {\n  mixed: \"Mixed\",\n  borderline: \"Borderline\",\n  separated: \"Phase-separated\",\n};\n\nexport const STATE_LABEL: Record<Droplet[\"state\"], string> = {\n  liquid: \"Liquid\",\n  hardening: \"Hardening\",\n  solid: \"Solid\",\n};\n\n/** One sentence on the overall state. */\nexport function headline(s: Summary): string {\n  const solid = s.solidFraction > 0.02 ? ` ${pct(s.solidFraction)} of the protein has hardened into solid clumps.` : \"\";\n  if (s.phase === \"mixed\") {\n    return s.count === 0\n      ? `Mixed: no droplets. The molecules are spread out evenly.${solid}`\n      : `Mixed: only ${plural(s.count, \"small chance clump\")}, holding ${pct(s.fraction)} of the protein.${solid}`;\n  }\n  if (s.phase === \"borderline\") {\n    return `Borderline: ${plural(s.count, \"small droplet\")} hold ${pct(s.fraction)} of the protein; droplets come and go.${solid}`;\n  }\n  return `Phase-separated: ${plural(s.count, \"droplet\")} hold ${pct(s.fraction)} of the protein.${solid}`;\n}\n\nexport function trendSentence(s: Summary, running: boolean): string {\n  if (s.trend === \"unknown\") return running ? \"Still settling: watch for a few seconds.\" : \"Run the simulation to see where it settles.\";\n  if (s.trend === \"rising\") return \"More protein is joining droplets.\";\n  if (s.trend === \"falling\") return \"Droplets are losing protein: they are shrinking or dissolving.\";\n  return \"Steady: about the same amount of protein stays in droplets.\";\n}\n\nexport function rnaSentence(s: Summary): string | null {\n  if (s.rnaTotal === 0) return null;\n  return `${s.rnaInDroplets} of ${s.rnaTotal} RNA molecules (${pct(s.rnaInDroplets / s.rnaTotal)}) are inside droplets.`;\n}\n\n/** Size across, in molecule widths, for a compact droplet of this many molecules. */\nexport function acrossMolecules(d: Droplet): number {\n  return Math.max(1, Math.round((2 * d.radius) / SIGMA));\n}\n\nexport function describeDroplet(d: Droplet, index?: number, total?: number): string {\n  const pos = index !== undefined && total !== undefined ? ` (${index + 1} of ${total})` : \"\";\n  const state =\n    d.state === \"liquid\" ? \"liquid\" : d.state === \"solid\" ? \"solid\" : `hardening, ${pct(d.solidFraction)} solid`;\n  return `Droplet ${d.id}${pos}: ${plural(d.size, \"molecule\")} (${d.protein} protein, ${d.rna} RNA), ${state}, ${d.region}.`;\n}\n\n/** The complete text equivalent of the picture right now. */\nexport function fullDescription(snap: Snapshot): string {\n  const parts = [headline(snap.summary), trendSentence(snap.summary, snap.running)];\n  const rna = rnaSentence(snap.summary);\n  if (rna) parts.push(rna);\n  if (snap.droplets.length > 0) {\n    const biggest = snap.droplets.slice(0, 3).map((d) => `droplet ${d.id} with ${d.size} molecules (${d.region})`);\n    parts.push(`Largest: ${biggest.join(\"; \")}.`);\n  }\n  return parts.join(\" \");\n}\n\n/**\n * A short spoken update from what changed since the last one: events first,\n * then the new total. Returns null when nothing worth saying happened.\n */\nexport function digest(events: LabEvent[], s: Summary, prev: { count: number; fraction: number } | null): string | null {\n  const counts = { formed: 0, merged: 0, dissolved: 0, solidified: 0 };\n  const info: string[] = [];\n  for (const e of events) {\n    if (e.kind === \"info\") info.push(e.text);\n    else counts[e.kind]++;\n  }\n  const bits: string[] = [];\n  if (counts.formed) bits.push(`${plural(counts.formed, \"droplet\")} formed`);\n  if (counts.merged) bits.push(`${plural(counts.merged, \"merge\")}`);\n  if (counts.dissolved) bits.push(`${plural(counts.dissolved, \"droplet\")} dissolved`);\n  if (counts.solidified) bits.push(`${plural(counts.solidified, \"droplet\")} turned solid`);\n  const changedTotal = !prev || prev.count !== s.count || Math.abs(prev.fraction - s.fraction) >= 0.1;\n  if (bits.length === 0 && info.length === 0 && !changedTotal) return null;\n  const out: string[] = [];\n  if (info.length) out.push(info[info.length - 1]);\n  if (bits.length) out.push(capitalise(bits.join(\", \")) + \".\");\n  out.push(\n    s.count === 0 ? \"No droplets.\" : `${plural(s.count, \"droplet\")}, holding ${pct(s.fraction)} of the protein.`,\n  );\n  return out.join(\" \");\n}\n\nfunction capitalise(t: string): string {\n  return t.charAt(0).toUpperCase() + t.slice(1);\n}\n\nexport function formatTime(t: number): string {\n  return t < 100 ? t.toFixed(1) : Math.round(t).toString();\n}\n",
    "apps/condensate-lab/lib/export.ts": "// Exports carry their meaning with them: every CSV starts with a comment line\n// saying it is simulated data from a simplified model, and the SVG picture has\n// a <title> and <desc> with the same text summary the page shows.\n\nimport { fullDescription, pct } from \"./describe\";\nimport { KIND_RNA, SIGMA, WORLD_H, WORLD_W, type World } from \"./sim/engine\";\nimport type { FrapRun, ImportedFrap, Scan, Snapshot } from \"./store\";\n\nconst NOTE = \"# Simulated data from Condensate Lab (a simplified 2D model; arbitrary units). Not experimental measurements.\";\n\nfunction csvCell(v: string | number | boolean | null): string {\n  if (v === null) return \"\";\n  const s = typeof v === \"number\" ? (Number.isInteger(v) ? String(v) : v.toFixed(4)) : String(v);\n  return /[\",\\n]/.test(s) ? `\"${s.replace(/\"/g, '\"\"')}\"` : s;\n}\n\nfunction csv(header: string[], rows: (string | number | boolean | null)[][], note = NOTE): string {\n  return [note, header.join(\",\"), ...rows.map((r) => r.map(csvCell).join(\",\"))].join(\"\\n\") + \"\\n\";\n}\n\nfunction paramsLine(snap: Snapshot): string {\n  const p = snap.params;\n  return `# Settings: stickiness ${p.chi}, temperature ${p.temperature}, protein ${p.proteinCount}, RNA ${p.multiComponent ? p.rnaCount : 0}, pH ${p.pH}, crowding ${p.crowding}, disease mode ${p.diseaseMode ? \"on\" : \"off\"}, seed ${p.seed}`;\n}\n\nexport function dropletsCsv(snap: Snapshot): string {\n  return csv(\n    [\"droplet\", \"molecules\", \"protein\", \"rna\", \"state\", \"solid_fraction\", \"centre_x\", \"centre_y\", \"radius\", \"region\"],\n    snap.droplets.map((d) => [d.id, d.size, d.protein, d.rna, d.state, d.solidFraction, d.cx, d.cy, d.radius, d.region]),\n    `${NOTE}\\n${paramsLine(snap)}\\n# Time ${snap.time.toFixed(1)}`,\n  );\n}\n\nexport function historyCsv(snap: Snapshot): string {\n  return csv(\n    [\"time\", \"protein_in_droplets_fraction\", \"droplets\", \"largest_droplet\", \"solid_protein_fraction\"],\n    snap.history.map((h) => [h.t, h.fraction, h.count, h.largest, h.solidFraction]),\n    `${NOTE}\\n${paramsLine(snap)}`,\n  );\n}\n\nexport function frapCsv(run: FrapRun): string {\n  return csv(\n    [\"time_since_bleach\", \"relative_intensity\"],\n    run.points.map((p) => [p.t, p.intensity]),\n    `${NOTE}\\n# FRAP on droplet ${run.dropletId} (${run.stateAtBleach} when bleached). Intensity is the spot divided by the whole droplet (double normalised).`,\n  );\n}\n\nexport function importedCsv(imp: ImportedFrap): string {\n  return csv(\n    [\"time_since_bleach\", \"relative_intensity\"],\n    imp.points.map((p) => [p.t, p.intensity]),\n    `# Your data from ${imp.name}, rescaled by Condensate Lab. ${imp.notes.join(\" \")}`,\n  );\n}\n\nexport function scanCsv(scan: Scan): string {\n  return csv(\n    [scan.key, \"protein_in_droplets_mean\", \"lowest\", \"highest\"],\n    scan.points.map((p) => [p.value, p.fraction, p.min, p.max]),\n    `${NOTE}\\n# Threshold scan: each value run twice from different random starts for 500 time units.`,\n  );\n}\n\nexport function settingsJson(snap: Snapshot): string {\n  return JSON.stringify(\n    {\n      app: \"Condensate Lab\",\n      note: \"Settings for a simplified simulation. Load this file to reproduce the run: the same seed and settings give the same start.\",\n      params: snap.params,\n    },\n    null,\n    2,\n  );\n}\n\nfunction esc(t: string): string {\n  return t.replace(/&/g, \"&amp;\").replace(/</g, \"&lt;\").replace(/>/g, \"&gt;\").replace(/\"/g, \"&quot;\");\n}\n\n/** The current picture as SVG, with shapes per kind and a full text description. */\nexport function pictureSvg(world: World, snap: Snapshot, colors: { protein: string; rna: string; solid: string; ink: string; paper: string }): string {\n  const r = SIGMA / 2 - 0.5;\n  const parts: string[] = [];\n  for (let i = 0; i < world.n; i++) {\n    const x = world.x[i].toFixed(1);\n    const y = world.y[i].toFixed(1);\n    const bleached = world.bleached[i] === 1;\n    if (world.solid[i]) {\n      const s = r * 1.7;\n      parts.push(`<rect x=\"${(world.x[i] - s / 2).toFixed(1)}\" y=\"${(world.y[i] - s / 2).toFixed(1)}\" width=\"${s.toFixed(1)}\" height=\"${s.toFixed(1)}\" fill=\"${bleached ? \"none\" : colors.solid}\" stroke=\"${colors.solid}\"/>`);\n    } else if (world.kind[i] === KIND_RNA) {\n      const cx = world.x[i];\n      const cy = world.y[i];\n      const pts = `${cx.toFixed(1)},${(cy - r * 1.15).toFixed(1)} ${(cx + r).toFixed(1)},${(cy + r * 0.75).toFixed(1)} ${(cx - r).toFixed(1)},${(cy + r * 0.75).toFixed(1)}`;\n      parts.push(`<polygon points=\"${pts}\" fill=\"${bleached ? \"none\" : colors.rna}\" stroke=\"${colors.rna}\"/>`);\n    } else {\n      parts.push(`<circle cx=\"${x}\" cy=\"${y}\" r=\"${r.toFixed(1)}\" fill=\"${bleached ? \"none\" : colors.protein}\" stroke=\"${colors.protein}\"/>`);\n    }\n  }\n  const halos = snap.droplets\n    .map(\n      (d) =>\n        `<circle cx=\"${d.cx.toFixed(1)}\" cy=\"${d.cy.toFixed(1)}\" r=\"${d.radius.toFixed(1)}\" fill=\"none\" stroke=\"${colors.ink}\" stroke-dasharray=\"4 3\" opacity=\"0.6\"/><text x=\"${d.cx.toFixed(1)}\" y=\"${(d.cy - d.radius - 3).toFixed(1)}\" font-size=\"10\" text-anchor=\"middle\" fill=\"${colors.ink}\">${d.id}</text>`,\n    )\n    .join(\"\");\n  const title = `Condensate Lab at time ${snap.time.toFixed(0)}: ${snap.summary.count} droplets, ${pct(snap.summary.fraction)} of protein in droplets`;\n  const desc = `${fullDescription(snap)} Circles are protein, triangles are RNA, squares are solid (hardened) protein, hollow shapes are bleached. Dashed rings mark droplets, numbered. Simulated with a simplified 2D model; arbitrary units.`;\n  return `<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 ${WORLD_W} ${WORLD_H}\" width=\"${WORLD_W * 2}\" height=\"${WORLD_H * 2}\" role=\"img\" aria-labelledby=\"t d\"><title id=\"t\">${esc(title)}</title><desc id=\"d\">${esc(desc)}</desc><rect width=\"100%\" height=\"100%\" fill=\"${colors.paper}\"/>${parts.join(\"\")}${halos}</svg>`;\n}\n\n/** Saves text as a file on the person's device. Nothing is uploaded. */\nexport function download(filename: string, text: string, type: string) {\n  const blob = new Blob([text], { type });\n  const url = URL.createObjectURL(blob);\n  const a = document.createElement(\"a\");\n  a.href = url;\n  a.download = filename;\n  document.body.appendChild(a);\n  a.click();\n  a.remove();\n  setTimeout(() => URL.revokeObjectURL(url), 1000);\n}\n",
    "apps/condensate-lab/lib/sim/engine.ts": "// Condensate Lab simulation engine.\n//\n// A 2D Brownian-dynamics model (overdamped Langevin): every molecule is a bead\n// that gets random thermal kicks and feels short-range forces from its\n// neighbours. Proteins attract proteins; RNA attracts protein but barely RNA.\n// Above a threshold of stickiness and concentration, the beads gather into\n// droplets (a dense phase) that coexist with a dilute phase.\n//\n// What it leaves out (also shown in the app): it is 2D, molecules are single\n// beads rather than chains, there is no water flow (hydrodynamics), no charges\n// or specific binding sites, and all units are arbitrary. \"Hardening\" in\n// disease mode is a probability rule, not a molecular mechanism.\n\nimport { effectiveChi, type SimParams } from \"./params\";\nimport { makeRng, type Rng } from \"./rng\";\n\nexport const WORLD_W = 420;\nexport const WORLD_H = 280;\n/** Bead diameter. */\nexport const SIGMA = 10;\n/**\n * Model constants. Tuned so that at the default mix droplets appear between\n * χ ≈ 1 and 2, dissolve above a temperature of about 2 (at χ = 3), and stay\n * liquid inside (bleached spots recover). A soft, longer-range attraction keeps\n * droplets round and liquid; short, hard attraction made frozen, stringy clumps.\n */\nexport const TUNE = {\n  /** Attraction reaches this far (centre to centre), in bead diameters. */\n  rCut: 3,\n  /** Stiffness of the soft core: low enough that beads can squeeze past each other. */\n  kRepel: 8,\n  /** Scales slider stickiness to bead attraction. */\n  epsScale: 0.04,\n};\nlet R_CUT = TUNE.rCut * SIGMA;\n/** Beads closer than this belong to the same cluster. */\nexport const CLUSTER_R = 1.4 * SIGMA;\n/** A cluster needs this many molecules to count as a droplet. */\nexport const MIN_DROPLET = 8;\n/** Time step, in the arbitrary time units shown in the interface. */\nexport const DT = 0.2;\n/** Movement of solid (aggregated) molecules relative to liquid ones. */\nconst SOLID_MOBILITY = 0.002;\n\nexport const KIND_PROTEIN = 0;\nexport const KIND_RNA = 1;\n\n/** Attraction between kinds, relative to protein-protein. */\nconst PAIR = [\n  [1.0, 0.75],\n  [0.75, 0.12],\n];\n\nexport interface World {\n  n: number;\n  x: Float64Array;\n  y: Float64Array;\n  kind: Uint8Array;\n  solid: Uint8Array;\n  bleached: Uint8Array;\n  /** Index into the latest cluster list, or -1 when not in a droplet. */\n  cluster: Int32Array;\n  time: number;\n  steps: number;\n  rng: Rng;\n  // scratch\n  fx: Float64Array;\n  fy: Float64Array;\n  cellHead: Int32Array;\n  cellNext: Int32Array;\n  cols: number;\n  rows: number;\n}\n\nexport function createWorld(p: SimParams): World {\n  R_CUT = TUNE.rCut * SIGMA;\n  const rng = makeRng(p.seed);\n  const nP = Math.round(p.proteinCount);\n  const nR = p.multiComponent ? Math.round(p.rnaCount) : 0;\n  const n = nP + nR;\n  const cols = Math.floor(WORLD_W / R_CUT);\n  const rows = Math.floor(WORLD_H / R_CUT);\n  const w: World = {\n    n,\n    x: new Float64Array(n),\n    y: new Float64Array(n),\n    kind: new Uint8Array(n),\n    solid: new Uint8Array(n),\n    bleached: new Uint8Array(n),\n    cluster: new Int32Array(n).fill(-1),\n    time: 0,\n    steps: 0,\n    rng,\n    fx: new Float64Array(n),\n    fy: new Float64Array(n),\n    cellHead: new Int32Array(cols * rows),\n    cellNext: new Int32Array(n),\n    cols,\n    rows,\n  };\n  const m = SIGMA;\n  for (let i = 0; i < n; i++) {\n    w.kind[i] = i < nP ? KIND_PROTEIN : KIND_RNA;\n    w.x[i] = m + rng() * (WORLD_W - 2 * m);\n    w.y[i] = m + rng() * (WORLD_H - 2 * m);\n  }\n  return w;\n}\n\nfunction buildGrid(w: World) {\n  const { cols, rows } = w;\n  w.cellHead.fill(-1);\n  const cw = WORLD_W / cols;\n  const ch = WORLD_H / rows;\n  for (let i = 0; i < w.n; i++) {\n    let cx = Math.floor(w.x[i] / cw);\n    let cy = Math.floor(w.y[i] / ch);\n    if (cx >= cols) cx = cols - 1;\n    if (cy >= rows) cy = rows - 1;\n    if (cx < 0) cx = 0;\n    if (cy < 0) cy = 0;\n    const c = cy * cols + cx;\n    w.cellNext[i] = w.cellHead[c];\n    w.cellHead[c] = i;\n  }\n}\n\n/** Calls fn(i, j) once for every pair closer than `range` (range must be ≤ R_CUT). */\nfunction forEachPair(w: World, range: number, fn: (i: number, j: number, dx: number, dy: number, r: number) => void) {\n  const { cols, rows, cellHead, cellNext, x, y } = w;\n  const r2max = range * range;\n  for (let cy = 0; cy < rows; cy++) {\n    for (let cx = 0; cx < cols; cx++) {\n      const c = cy * cols + cx;\n      for (let i = cellHead[c]; i !== -1; i = cellNext[i]) {\n        // same cell: j after i in the list; neighbour cells: half of the 8\n        for (let j = cellNext[i]; j !== -1; j = cellNext[j]) {\n          const dx = x[j] - x[i];\n          const dy = y[j] - y[i];\n          const r2 = dx * dx + dy * dy;\n          if (r2 < r2max && r2 > 1e-12) fn(i, j, dx, dy, Math.sqrt(r2));\n        }\n        for (let k = 0; k < 4; k++) {\n          const nx = cx + (k === 0 ? 1 : k === 1 ? -1 : k === 2 ? 0 : 1);\n          const ny = cy + (k === 0 ? 0 : 1);\n          if (nx < 0 || nx >= cols || ny >= rows) continue;\n          for (let j = cellHead[ny * cols + nx]; j !== -1; j = cellNext[j]) {\n            const dx = x[j] - x[i];\n            const dy = y[j] - y[i];\n            const r2 = dx * dx + dy * dy;\n            if (r2 < r2max && r2 > 1e-12) fn(i, j, dx, dy, Math.sqrt(r2));\n          }\n        }\n      }\n    }\n  }\n}\n\n/** Gaussian random number (Box–Muller). */\nfunction gauss(rng: Rng): number {\n  let u = 0;\n  while (u === 0) u = rng();\n  return Math.sqrt(-2 * Math.log(u)) * Math.cos(2 * Math.PI * rng());\n}\n\n/** Advances the world by `count` time steps. */\nexport function step(w: World, p: SimParams, count = 1) {\n  const chiEff = effectiveChi(p);\n  const T = p.temperature;\n  const eps = TUNE.epsScale * chiEff;\n  const noise = Math.sqrt(2 * T * DT);\n  const { x, y, fx, fy, kind, solid } = w;\n  for (let s = 0; s < count; s++) {\n    buildGrid(w);\n    fx.fill(0);\n    fy.fill(0);\n    forEachPair(w, R_CUT, (i, j, dx, dy, r) => {\n      let f: number; // positive pushes apart\n      if (r < SIGMA) {\n        f = (TUNE.kRepel * (SIGMA - r)) / SIGMA;\n      } else {\n        let e = eps * PAIR[kind[i]][kind[j]];\n        if (solid[i] && solid[j]) e *= 2.5;\n        f = -e * Math.sin((Math.PI * (r - SIGMA)) / (R_CUT - SIGMA));\n      }\n      const ux = dx / r;\n      const uy = dy / r;\n      fx[i] -= f * ux;\n      fy[i] -= f * uy;\n      fx[j] += f * ux;\n      fy[j] += f * uy;\n    });\n    const half = SIGMA / 2;\n    for (let i = 0; i < w.n; i++) {\n      const mob = solid[i] ? SOLID_MOBILITY : 1;\n      let nx = x[i] + mob * fx[i] * DT + Math.sqrt(mob) * noise * gauss(w.rng);\n      let ny = y[i] + mob * fy[i] * DT + Math.sqrt(mob) * noise * gauss(w.rng);\n      // reflecting walls\n      if (nx < half) nx = 2 * half - nx;\n      if (nx > WORLD_W - half) nx = 2 * (WORLD_W - half) - nx;\n      if (ny < half) ny = 2 * half - ny;\n      if (ny > WORLD_H - half) ny = 2 * (WORLD_H - half) - ny;\n      x[i] = Math.min(WORLD_W - half, Math.max(half, nx));\n      y[i] = Math.min(WORLD_H - half, Math.max(half, ny));\n    }\n    w.time += DT;\n    w.steps++;\n  }\n}\n\n// ─── Clusters ────────────────────────────────────────────────────────────────\n\nexport interface RawCluster {\n  members: number[];\n  protein: number;\n  rna: number;\n  solid: number;\n  cx: number;\n  cy: number;\n  /** Radius of a circle holding the members (from their spread). */\n  radius: number;\n}\n\n/** Groups touching molecules; returns clusters big enough to be droplets, largest first. */\nexport function findClusters(w: World): RawCluster[] {\n  buildGrid(w);\n  const parent = new Int32Array(w.n);\n  for (let i = 0; i < w.n; i++) parent[i] = i;\n  const find = (a: number): number => {\n    while (parent[a] !== a) {\n      parent[a] = parent[parent[a]];\n      a = parent[a];\n    }\n    return a;\n  };\n  forEachPair(w, CLUSTER_R, (i, j) => {\n    // RNA-RNA contacts alone don't make a cluster (RNA is a client)\n    if (w.kind[i] === KIND_RNA && w.kind[j] === KIND_RNA) return;\n    const a = find(i);\n    const b = find(j);\n    if (a !== b) parent[a] = b;\n  });\n  const groups = new Map<number, number[]>();\n  for (let i = 0; i < w.n; i++) {\n    const r = find(i);\n    let g = groups.get(r);\n    if (!g) groups.set(r, (g = []));\n    g.push(i);\n  }\n  const out: RawCluster[] = [];\n  for (const members of groups.values()) {\n    let protein = 0;\n    for (const m of members) if (w.kind[m] === KIND_PROTEIN) protein++;\n    if (members.length < MIN_DROPLET || protein < MIN_DROPLET / 2) continue;\n    let sx = 0;\n    let sy = 0;\n    let solid = 0;\n    for (const m of members) {\n      sx += w.x[m];\n      sy += w.y[m];\n      if (w.solid[m]) solid++;\n    }\n    const cx = sx / members.length;\n    const cy = sy / members.length;\n    // 90th-percentile distance, so one stray molecule at the edge doesn't balloon the outline\n    const dists = members.map((m) => Math.hypot(w.x[m] - cx, w.y[m] - cy)).sort((a, b) => a - b);\n    const maxR = dists[Math.min(dists.length - 1, Math.floor(0.9 * dists.length))];\n    out.push({\n      members,\n      protein,\n      rna: members.length - protein,\n      solid,\n      cx,\n      cy,\n      radius: maxR + SIGMA / 2,\n    });\n  }\n  out.sort((a, b) => b.members.length - a.members.length);\n  w.cluster.fill(-1);\n  out.forEach((c, k) => {\n    for (const m of c.members) w.cluster[m] = k;\n  });\n  return out;\n}\n\n/**\n * Disease mode: each molecule in a droplet of at least 8 molecules may turn solid.\n * Hardening starts at contacts with solid neighbours or at random seeds, so a\n * droplet hardens progressively. Solid molecules stay solid even if disease\n * mode is turned off (as real aggregates do); Reset clears them.\n */\nexport function harden(w: World, p: SimParams, clusters: RawCluster[], dtElapsed: number) {\n  if (!p.diseaseMode) return;\n  const seedRate = 0.004 * p.aggregationRate;\n  const spreadRate = 0.25 * p.aggregationRate;\n  for (const c of clusters) {\n    if (c.members.length < 8) continue;\n    const sizeFactor = Math.min(3, c.members.length / 20);\n    if (c.solid === 0) {\n      if (w.rng() < 1 - Math.exp(-seedRate * sizeFactor * dtElapsed)) {\n        const m = c.members[Math.floor(w.rng() * c.members.length)];\n        if (w.kind[m] === KIND_PROTEIN) w.solid[m] = 1;\n      }\n      continue;\n    }\n    // spread: a liquid protein next to a solid one hardens\n    const pSpread = 1 - Math.exp(-spreadRate * dtElapsed);\n    for (const m of c.members) {\n      if (w.solid[m] || w.kind[m] !== KIND_PROTEIN) continue;\n      for (const o of c.members) {\n        if (!w.solid[o]) continue;\n        const d2 = (w.x[m] - w.x[o]) ** 2 + (w.y[m] - w.y[o]) ** 2;\n        if (d2 < CLUSTER_R * CLUSTER_R) {\n          if (w.rng() < pSpread) w.solid[m] = 1;\n          break;\n        }\n      }\n    }\n  }\n}\n\n/**\n * Bleaches every protein within `radius` of (cx, cy); returns how many.\n * As in a lab, only one kind of molecule carries the glowing label: here the protein.\n */\nexport function bleach(w: World, cx: number, cy: number, radius: number): number {\n  let k = 0;\n  for (let i = 0; i < w.n; i++) {\n    if (w.kind[i] !== KIND_PROTEIN) continue;\n    if ((w.x[i] - cx) ** 2 + (w.y[i] - cy) ** 2 <= radius * radius) {\n      w.bleached[i] = 1;\n      k++;\n    }\n  }\n  return k;\n}\n\n/** Share of the proteins inside the circle that still glow, or null if there are none. */\nexport function brightFraction(w: World, cx: number, cy: number, radius: number): number | null {\n  let total = 0;\n  let bright = 0;\n  for (let i = 0; i < w.n; i++) {\n    if (w.kind[i] !== KIND_PROTEIN) continue;\n    if ((w.x[i] - cx) ** 2 + (w.y[i] - cy) ** 2 <= radius * radius) {\n      total++;\n      if (!w.bleached[i]) bright++;\n    }\n  }\n  return total === 0 ? null : bright / total;\n}\n\nexport function proteinCount(w: World): number {\n  let k = 0;\n  for (let i = 0; i < w.n; i++) if (w.kind[i] === KIND_PROTEIN) k++;\n  return k;\n}\n\n/** Protein area fraction (φ) of the whole box: the concentration used by the theory panel. */\nexport function proteinAreaFraction(p: SimParams): number {\n  const a = Math.PI * (SIGMA / 2) ** 2;\n  return (p.proteinCount * a) / (WORLD_W * WORLD_H);\n}\n",
    "apps/condensate-lab/lib/sim/floryHuggins.ts": "// Textbook Flory-Huggins theory for a symmetric two-part mixture.\n// Free energy of mixing per site, in units of kT:\n//   f(φ) = φ ln φ + (1 − φ) ln(1 − φ) + χ φ (1 − φ)\n// φ is the share of space taken by the sticky molecules (0–1).\n// Above the critical value χc = 2 the curve has two dips (two stable phases).\n\nexport const CRITICAL_CHI = 2;\n\nexport function freeEnergy(phi: number, chi: number): number {\n  return phi * Math.log(phi) + (1 - phi) * Math.log(1 - phi) + chi * phi * (1 - phi);\n}\n\nexport function freeEnergyCurve(chi: number, steps = 98): { phi: number; f: number }[] {\n  const out: { phi: number; f: number }[] = [];\n  for (let k = 1; k <= steps; k++) {\n    const phi = k / (steps + 1);\n    out.push({ phi: Number(phi.toFixed(4)), f: freeEnergy(phi, chi) });\n  }\n  return out;\n}\n\n/** Spinodal: where the curve bends the other way (f'' = 0). Inside it, a mix separates at once. */\nexport function spinodal(chi: number): { low: number; high: number } | null {\n  if (chi <= CRITICAL_CHI) return null;\n  const d = Math.sqrt(1 - 2 / chi);\n  return { low: (1 - d) / 2, high: (1 + d) / 2 };\n}\n\n/**\n * Binodal (coexistence): the two compositions the mixture splits into.\n * For the symmetric model they satisfy ln(φ / (1 − φ)) = χ(2φ − 1).\n */\nexport function binodal(chi: number): { low: number; high: number } | null {\n  if (chi <= CRITICAL_CHI) return null;\n  const g = (phi: number) => Math.log(phi / (1 - phi)) - chi * (2 * phi - 1);\n  // g → −∞ at 0, g(0.5) = 0, and g > 0 just below 0.5 when χ > 2; bisect on (1e-12, spinodal low)\n  let lo = 1e-12;\n  let hi = spinodal(chi)!.low;\n  for (let k = 0; k < 200; k++) {\n    const mid = (lo + hi) / 2;\n    if (g(mid) < 0) lo = mid;\n    else hi = mid;\n  }\n  const low = (lo + hi) / 2;\n  return { low, high: 1 - low };\n}\n\nexport type TheoryVerdict = \"mixed\" | \"metastable\" | \"unstable\";\n\n/** Where a mixture of composition φ sits for a given χ. */\nexport function classify(phi: number, chi: number): TheoryVerdict {\n  const b = binodal(chi);\n  if (!b || phi <= b.low || phi >= b.high) return \"mixed\";\n  const s = spinodal(chi)!;\n  return phi > s.low && phi < s.high ? \"unstable\" : \"metastable\";\n}\n",
    "apps/condensate-lab/lib/sim/frap.ts": "// FRAP (fluorescence recovery after photobleaching): bleach part of a droplet,\n// then watch brightness come back as unbleached molecules move in. Fast, full\n// recovery = liquid; slow or partial recovery = gel or solid.\n\nexport interface FrapPoint {\n  /** Time since the bleach. */\n  t: number;\n  /** Brightness in the bleached spot: 1 = as before the bleach, 0 = fully dark. */\n  intensity: number;\n}\n\nexport interface FrapFit {\n  /** Brightness straight after the bleach. */\n  i0: number;\n  /** Brightness the curve levels off at. */\n  plateau: number;\n  /** Time constant of the exponential. */\n  tau: number;\n  /** Time to recover half of the way to the plateau. */\n  halfTime: number;\n  /** Share of the bleached molecules that are free to move (0–1). */\n  mobileFraction: number;\n  /** How well the curve fits (1 = perfectly). */\n  r2: number;\n}\n\nexport type FitResult =\n  | { ok: true; fit: FrapFit; reliable: boolean; note: string }\n  | { ok: false; reason: string };\n\n/**\n * Fits I(t) = i0 + (plateau − i0)(1 − e^(−t/τ)) by scanning τ and solving the\n * rest by least squares. Returns a reason instead of a fit when the data\n * cannot support one: \"not enough data\" is a valid answer.\n */\nexport function fitRecovery(points: FrapPoint[], preBleach = 1): FitResult {\n  const pts = points.filter((p) => Number.isFinite(p.t) && Number.isFinite(p.intensity));\n  if (pts.length < 8) return { ok: false, reason: \"Not enough data yet: at least 8 readings are needed.\" };\n  const tMax = pts[pts.length - 1].t - pts[0].t;\n  if (!(tMax > 0)) return { ok: false, reason: \"The readings all have the same time.\" };\n  const t0 = pts[0].t;\n  let best: { tau: number; a: number; b: number; sse: number } | null = null;\n  // τ from tMax/400 to 3·tMax on a log grid\n  for (let k = 0; k <= 240; k++) {\n    const tau = (tMax / 400) * Math.pow(1200, k / 240);\n    // I = a + b·g, g = 1 − e^(−t/τ); linear least squares in a, b\n    let sg = 0, sgg = 0, si = 0, sgi = 0;\n    const n = pts.length;\n    for (const p of pts) {\n      const g = 1 - Math.exp(-(p.t - t0) / tau);\n      sg += g;\n      sgg += g * g;\n      si += p.intensity;\n      sgi += g * p.intensity;\n    }\n    const det = n * sgg - sg * sg;\n    if (Math.abs(det) < 1e-12) continue;\n    const b = (n * sgi - sg * si) / det;\n    const a = (si - b * sg) / n;\n    let sse = 0;\n    for (const p of pts) {\n      const g = 1 - Math.exp(-(p.t - t0) / tau);\n      sse += (p.intensity - (a + b * g)) ** 2;\n    }\n    if (!best || sse < best.sse) best = { tau, a, b, sse };\n  }\n  if (!best) return { ok: false, reason: \"The curve could not be fitted.\" };\n  const mean = pts.reduce((s, p) => s + p.intensity, 0) / pts.length;\n  const sst = pts.reduce((s, p) => s + (p.intensity - mean) ** 2, 0);\n  const r2 = sst > 0 ? 1 - best.sse / sst : 0;\n  const i0 = best.a;\n  const plateau = best.a + best.b;\n  const denom = preBleach - i0;\n  const mobileFraction = denom > 1e-6 ? Math.max(0, Math.min(1, (plateau - i0) / denom)) : 0;\n  const fit: FrapFit = { i0, plateau, tau: best.tau, halfTime: best.tau * Math.LN2, mobileFraction, r2 };\n  const recovered = plateau - i0;\n  if (recovered < 0.05) {\n    return {\n      ok: true,\n      fit: { ...fit, halfTime: Number.POSITIVE_INFINITY, mobileFraction: Math.max(0, recovered / Math.max(denom, 1e-6)) },\n      reliable: tMax > 0,\n      note: \"Almost no recovery: the molecules in the spot are not moving. That is how a solid behaves.\",\n    };\n  }\n  const coversCurve = tMax >= 2 * best.tau;\n  if (best.tau > 1.5 * tMax) {\n    // Still creeping up at the end: the plateau cannot be known. Report what was seen as a lower bound.\n    const tail = pts.slice(-Math.max(3, Math.floor(pts.length / 10)));\n    const end = tail.reduce((s, p) => s + p.intensity, 0) / tail.length;\n    const seen = denom > 1e-6 ? Math.max(0, Math.min(1, (end - i0) / denom)) : 0;\n    return {\n      ok: true,\n      fit: { ...fit, plateau: end, halfTime: Number.POSITIVE_INFINITY, mobileFraction: seen },\n      reliable: false,\n      note: `Uncertain: recovery is slow and has not levelled off, so the half-time cannot be measured. At least ${Math.round(seen * 100)}% has recovered so far.`,\n    };\n  }\n  const reliable = r2 >= 0.8 && coversCurve;\n  const note = !coversCurve\n    ? \"Uncertain: the curve has not levelled off yet, so the half-time and plateau are rough. Keep recording.\"\n    : r2 < 0.8\n      ? \"Uncertain: the readings are noisy and the curve fits them loosely.\"\n      : \"The curve fits the readings well.\";\n  return { ok: true, fit, reliable, note };\n}\n\n/** Plain-language reading of a fit. */\nexport function interpretFit(r: FitResult): string {\n  if (!r.ok) return r.reason;\n  const m = r.fit.mobileFraction;\n  const kind =\n    m >= 0.75 ? \"liquid-like: most molecules swap in and out freely\" :\n    m >= 0.35 ? \"gel-like: some molecules move, others are stuck\" :\n    \"solid-like: most molecules are stuck in place\";\n  return `Mobile fraction ${Math.round(m * 100)}%, ${kind}.`;\n}\n\n/**\n * Parses an experimental FRAP curve from CSV or tab-separated text.\n * Two numeric columns are used: time and intensity. A header row is optional.\n * Intensities are scaled so the pre-bleach value (first reading before the\n * lowest point, if present) is 1; otherwise the largest value is 1.\n */\nexport function parseFrapCsv(text: string): { points: FrapPoint[]; notes: string[] } | { error: string } {\n  const notes: string[] = [];\n  const rows = text\n    .split(/\\r?\\n/)\n    .map((l) => l.trim())\n    .filter((l) => l.length > 0 && !l.startsWith(\"#\"));\n  const data: [number, number][] = [];\n  let skipped = 0;\n  for (const row of rows) {\n    const cells = row.split(/[,\\t;]|\\s{2,}/).map((c) => c.trim());\n    const nums = cells.map((c) => Number(c)).filter((v) => Number.isFinite(v));\n    if (cells.length >= 2 && Number.isFinite(Number(cells[0])) && Number.isFinite(Number(cells[1]))) {\n      data.push([Number(cells[0]), Number(cells[1])]);\n    } else if (nums.length < 2) {\n      skipped++;\n    }\n  }\n  if (data.length < 4) return { error: \"No usable data found. The file needs two number columns: time and intensity.\" };\n  if (skipped > 0) notes.push(`${skipped} row${skipped === 1 ? \"\" : \"s\"} without two numbers skipped (for example a header).`);\n  data.sort((a, b) => a[0] - b[0]);\n  let minIdx = 0;\n  for (let i = 1; i < data.length; i++) if (data[i][1] < data[minIdx][1]) minIdx = i;\n  let scale: number;\n  if (minIdx > 0) {\n    const pre = data.slice(0, minIdx).reduce((s, d) => s + d[1], 0) / minIdx;\n    scale = pre;\n    notes.push(`Scaled so the ${minIdx} reading${minIdx === 1 ? \"\" : \"s\"} before the bleach average 1.`);\n  } else {\n    scale = Math.max(...data.map((d) => d[1]));\n    notes.push(\"No pre-bleach readings found, so the largest value is taken as 1.\");\n  }\n  if (!(scale > 0)) return { error: \"The intensities are all zero or negative.\" };\n  const t0 = data[minIdx][0];\n  const points = data.slice(minIdx).map(([t, v]) => ({ t: t - t0, intensity: v / scale }));\n  return { points, notes };\n}\n",
    "apps/condensate-lab/lib/sim/params.ts": "// Every setting the simulation reads, with its range and plain-language meaning.\n// One source for sliders, presets, exports and descriptions.\n\nexport interface SimParams {\n  /** Scaffold proteins: the \"sticky\" molecules that drive droplet formation. */\n  proteinCount: number;\n  /** RNA molecules: clients that are pulled into droplets by sticking to protein. */\n  rnaCount: number;\n  /** Stickiness (chi, written χ): how strongly molecules prefer each other over water. */\n  chi: number;\n  /** Temperature (thermal energy, kT). Higher = more jiggling, droplets melt. */\n  temperature: number;\n  /** pH. Stickiness is strongest near neutral (7) and weakens towards acid or base. */\n  pH: number;\n  /** Crowding: other big molecules filling the cell, which push ours together. */\n  crowding: number;\n  /** Include RNA in the mixture. */\n  multiComponent: boolean;\n  /** Disease mode: droplets can harden into solid aggregates. */\n  diseaseMode: boolean;\n  /** How quickly droplets harden in disease mode. */\n  aggregationRate: number;\n  /** Random seed: the same seed and settings give the same run. */\n  seed: number;\n}\n\nexport type NumericKey =\n  | \"proteinCount\"\n  | \"rnaCount\"\n  | \"chi\"\n  | \"temperature\"\n  | \"pH\"\n  | \"crowding\"\n  | \"aggregationRate\";\n\nexport interface ParamSpec {\n  key: NumericKey;\n  label: string;\n  short: string;\n  min: number;\n  max: number;\n  step: number;\n  /** Shown after the value, e.g. \" kT\". Empty for counts. */\n  unit: string;\n  /** Plain-language help shown under the control. */\n  help: string;\n  /** Hidden in the simpler interface (still reachable through presets and \"Show all settings\"). */\n  advanced: boolean;\n  /** Changing this restarts the run (new molecules), rather than changing it live. */\n  restarts: boolean;\n  decimals: number;\n}\n\nexport const PARAM_SPECS: readonly ParamSpec[] = [\n  {\n    key: \"chi\",\n    label: \"Stickiness (χ)\",\n    short: \"stickiness\",\n    min: 0,\n    max: 6,\n    step: 0.1,\n    unit: \"\",\n    help: \"How strongly the proteins prefer touching each other over touching water. Droplets need enough stickiness.\",\n    advanced: false,\n    restarts: false,\n    decimals: 1,\n  },\n  {\n    key: \"temperature\",\n    label: \"Temperature\",\n    short: \"temperature\",\n    min: 0.2,\n    max: 3,\n    step: 0.1,\n    unit: \" kT\",\n    help: \"Heat makes molecules jiggle harder. Enough heat shakes droplets apart.\",\n    advanced: false,\n    restarts: false,\n    decimals: 1,\n  },\n  {\n    key: \"proteinCount\",\n    label: \"Protein molecules\",\n    short: \"protein count\",\n    min: 20,\n    max: 400,\n    step: 10,\n    unit: \"\",\n    help: \"More protein in the same space means a higher concentration. Below a threshold concentration, droplets cannot form.\",\n    advanced: false,\n    restarts: true,\n    decimals: 0,\n  },\n  {\n    key: \"rnaCount\",\n    label: \"RNA molecules\",\n    short: \"RNA count\",\n    min: 0,\n    max: 200,\n    step: 10,\n    unit: \"\",\n    help: \"RNA sticks to protein but barely to itself, so it joins droplets without making them.\",\n    advanced: false,\n    restarts: true,\n    decimals: 0,\n  },\n  {\n    key: \"pH\",\n    label: \"pH\",\n    short: \"pH\",\n    min: 4,\n    max: 10,\n    step: 0.1,\n    unit: \"\",\n    help: \"How acidic (low) or basic (high) the liquid is. In this model, stickiness is strongest at pH 7.\",\n    advanced: true,\n    restarts: false,\n    decimals: 1,\n  },\n  {\n    key: \"crowding\",\n    label: \"Crowding\",\n    short: \"crowding\",\n    min: 0.5,\n    max: 2,\n    step: 0.1,\n    unit: \"×\",\n    help: \"Cells are packed with other large molecules. More crowding squeezes our molecules together and helps droplets form.\",\n    advanced: true,\n    restarts: false,\n    decimals: 1,\n  },\n  {\n    key: \"aggregationRate\",\n    label: \"Hardening speed\",\n    short: \"hardening speed\",\n    min: 0.1,\n    max: 3,\n    step: 0.1,\n    unit: \"×\",\n    help: \"In disease mode, how quickly large droplets turn solid. Only used when disease mode is on.\",\n    advanced: true,\n    restarts: false,\n    decimals: 1,\n  },\n];\n\nexport const DEFAULT_PARAMS: SimParams = {\n  proteinCount: 160,\n  rnaCount: 40,\n  chi: 3.0,\n  temperature: 1.0,\n  pH: 7.0,\n  crowding: 1.0,\n  multiComponent: true,\n  diseaseMode: false,\n  aggregationRate: 1.0,\n  seed: 1,\n};\n\nexport function specFor(key: NumericKey): ParamSpec {\n  const s = PARAM_SPECS.find((p) => p.key === key);\n  if (!s) throw new Error(`Unknown parameter ${key}`);\n  return s;\n}\n\nexport function clampParam(key: NumericKey, value: number): number {\n  const s = specFor(key);\n  if (!Number.isFinite(value)) return s.min;\n  const stepped = Math.round((value - s.min) / s.step) * s.step + s.min;\n  const v = Math.min(s.max, Math.max(s.min, stepped));\n  return Number(v.toFixed(s.decimals));\n}\n\nexport function formatParam(key: NumericKey, value: number): string {\n  const s = specFor(key);\n  return `${value.toFixed(s.decimals)}${s.unit}`;\n}\n\n/** Validates params read from a file or URL; unknown or bad values fall back to defaults. */\nexport function sanitizeParams(input: unknown): SimParams {\n  const out: SimParams = { ...DEFAULT_PARAMS };\n  if (!input || typeof input !== \"object\") return out;\n  const o = input as Record<string, unknown>;\n  for (const s of PARAM_SPECS) {\n    const v = o[s.key];\n    if (typeof v === \"number\") out[s.key] = clampParam(s.key, v);\n  }\n  if (typeof o.multiComponent === \"boolean\") out.multiComponent = o.multiComponent;\n  if (typeof o.diseaseMode === \"boolean\") out.diseaseMode = o.diseaseMode;\n  if (typeof o.seed === \"number\" && Number.isInteger(o.seed) && o.seed > 0) out.seed = o.seed;\n  return out;\n}\n\n/**\n * Effective stickiness the molecules feel, after pH and crowding.\n * Also the χ used by the textbook Flory-Huggins curve (divided by temperature there).\n */\nexport function effectiveChi(p: Pick<SimParams, \"chi\" | \"pH\" | \"crowding\">): number {\n  const pHFactor = Math.max(0.2, 1 - 0.12 * Math.abs(p.pH - 7));\n  return p.chi * pHFactor * p.crowding;\n}\n",
    "apps/condensate-lab/lib/sim/rng.ts": "/** Seeded random numbers (mulberry32): the same seed always gives the same run. */\nexport type Rng = () => number;\n\nexport function makeRng(seed: number): Rng {\n  let a = seed >>> 0 || 1;\n  return () => {\n    a = (a + 0x6d2b79f5) >>> 0;\n    let t = a;\n    t = Math.imul(t ^ (t >>> 15), t | 1);\n    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);\n    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;\n  };\n}\n",
    "apps/condensate-lab/lib/sonify.ts": "// Optional sound: short tones for events and a steady tone whose pitch follows\n// how much protein is in droplets. Always an extra channel; everything heard\n// is also shown as text. Browsers only allow sound after a press or key, so\n// sound starts when the person turns it on.\n\nimport type { EventKind } from \"./store\";\n\nlet ctx: AudioContext | null = null;\nlet drone: { osc: OscillatorNode; gain: GainNode } | null = null;\n\nfunction audio(): AudioContext | null {\n  if (typeof window === \"undefined\") return null;\n  const AC = window.AudioContext || (window as unknown as { webkitAudioContext?: typeof AudioContext }).webkitAudioContext;\n  if (!AC) return null;\n  if (!ctx) ctx = new AC();\n  if (ctx.state === \"suspended\") void ctx.resume();\n  return ctx;\n}\n\nexport function soundSupported(): boolean {\n  return typeof window !== \"undefined\" && (\"AudioContext\" in window || \"webkitAudioContext\" in window);\n}\n\nfunction tone(freq: number, start: number, dur: number, type: OscillatorType = \"sine\", level = 0.12) {\n  const a = audio();\n  if (!a) return;\n  const o = a.createOscillator();\n  const g = a.createGain();\n  o.type = type;\n  o.frequency.value = freq;\n  const t0 = a.currentTime + start;\n  g.gain.setValueAtTime(0, t0);\n  g.gain.linearRampToValueAtTime(level, t0 + 0.02);\n  g.gain.exponentialRampToValueAtTime(0.0001, t0 + dur);\n  o.connect(g).connect(a.destination);\n  o.start(t0);\n  o.stop(t0 + dur + 0.05);\n}\n\n/** A short, distinct tone pattern per kind of event. */\nexport function earcon(kind: EventKind) {\n  switch (kind) {\n    case \"formed\": // rising pair\n      tone(523, 0, 0.18);\n      tone(784, 0.14, 0.22);\n      break;\n    case \"dissolved\": // falling pair\n      tone(659, 0, 0.18);\n      tone(392, 0.14, 0.25);\n      break;\n    case \"merged\": // two notes together\n      tone(523, 0, 0.3);\n      tone(659, 0, 0.3);\n      break;\n    case \"solidified\": // low buzz\n      tone(147, 0, 0.35, \"square\", 0.06);\n      break;\n    default:\n      tone(880, 0, 0.08, \"sine\", 0.06);\n  }\n}\n\n/** Starts or updates the steady tone: 0 → low (220 Hz), 1 → high (880 Hz). */\nexport function setDrone(fraction: number | null) {\n  const a = audio();\n  if (!a) return;\n  if (fraction === null) {\n    if (drone) {\n      drone.gain.gain.setTargetAtTime(0, a.currentTime, 0.1);\n      const d = drone;\n      setTimeout(() => d.osc.stop(), 400);\n      drone = null;\n    }\n    return;\n  }\n  const f = 220 * Math.pow(4, Math.min(1, Math.max(0, fraction)));\n  if (!drone) {\n    const osc = a.createOscillator();\n    const gain = a.createGain();\n    osc.type = \"triangle\";\n    osc.frequency.value = f;\n    gain.gain.value = 0;\n    osc.connect(gain).connect(a.destination);\n    osc.start();\n    gain.gain.setTargetAtTime(0.05, a.currentTime, 0.2);\n    drone = { osc, gain };\n  } else {\n    drone.osc.frequency.setTargetAtTime(f, a.currentTime, 0.3);\n  }\n}\n",
    "apps/condensate-lab/lib/store.ts": "// The single state model. The canvas, text summary, tables, charts, sounds\n// and announcements all read from here; every control writes to here.\n\nimport {\n  bleach,\n  brightFraction,\n  createWorld,\n  DT,\n  findClusters,\n  harden,\n  KIND_PROTEIN,\n  proteinCount,\n  SIGMA,\n  step,\n  WORLD_H,\n  WORLD_W,\n  type World,\n} from \"./sim/engine\";\nimport { fitRecovery, parseFrapCsv, type FitResult, type FrapPoint } from \"./sim/frap\";\nimport { clampParam, DEFAULT_PARAMS, sanitizeParams, specFor, type NumericKey, type SimParams } from \"./sim/params\";\nimport { makeRng } from \"./sim/rng\";\n\nexport type DropletState = \"liquid\" | \"hardening\" | \"solid\";\n\nexport interface Droplet {\n  id: number;\n  size: number;\n  protein: number;\n  rna: number;\n  solid: number;\n  solidFraction: number;\n  state: DropletState;\n  cx: number;\n  cy: number;\n  radius: number;\n  region: string;\n}\n\nexport interface HistoryPoint {\n  t: number;\n  /** Share of protein inside droplets (0–1). */\n  fraction: number;\n  count: number;\n  /** Share of protein that is solid (0–1). */\n  solidFraction: number;\n  largest: number;\n}\n\nexport type EventKind = \"formed\" | \"merged\" | \"dissolved\" | \"solidified\" | \"info\";\n\nexport interface LabEvent {\n  id: number;\n  t: number;\n  kind: EventKind;\n  text: string;\n}\n\nexport interface FrapRun {\n  id: number;\n  dropletId: number;\n  /** State of the droplet when it was bleached. */\n  stateAtBleach: DropletState;\n  solidAtBleach: number;\n  startT: number;\n  cx: number;\n  cy: number;\n  radius: number;\n  bleachedCount: number;\n  points: FrapPoint[];\n  status: \"recording\" | \"ended\";\n  endReason: string | null;\n  fit: FitResult | null;\n}\n\nexport type ScanKey = \"chi\" | \"proteinCount\" | \"temperature\";\n\nexport interface ScanPoint {\n  value: number;\n  /** Mean share of protein in droplets. */\n  fraction: number;\n  min: number;\n  max: number;\n}\n\nexport interface Scan {\n  key: ScanKey;\n  status: \"running\" | \"done\" | \"cancelled\";\n  points: ScanPoint[];\n  total: number;\n  /** Settings the scan was run with (all except the scanned one). */\n  base: SimParams;\n}\n\nexport interface ImportedFrap {\n  name: string;\n  points: FrapPoint[];\n  notes: string[];\n  fit: FitResult;\n}\n\nexport type Phase = \"mixed\" | \"borderline\" | \"separated\";\nexport type Trend = \"rising\" | \"falling\" | \"steady\" | \"unknown\";\n\nexport interface Summary {\n  fraction: number;\n  count: number;\n  solidFraction: number;\n  largest: number;\n  phase: Phase;\n  trend: Trend;\n  rnaInDroplets: number;\n  rnaTotal: number;\n}\n\nexport interface Snapshot {\n  params: SimParams;\n  running: boolean;\n  speed: number;\n  time: number;\n  droplets: Droplet[];\n  summary: Summary;\n  history: HistoryPoint[];\n  events: LabEvent[];\n  selectedId: number | null;\n  frap: FrapRun | null;\n  frapRuns: FrapRun[];\n  scan: Scan | null;\n  imported: ImportedFrap | null;\n  /** Increases on every reset, so views can tell a new run from a continued one. */\n  runId: number;\n}\n\nexport const SPEEDS = [0.25, 0.5, 1, 2, 4] as const;\nconst STEPS_PER_FRAME = 8;\nconst ANALYSE_EVERY = 5; // steps\nconst ESTABLISHED_AGE = 3; // analyses before a droplet counts as formed\nconst HISTORY_MAX = 800;\nconst FRAP_MAX_T = 1000;\n/** Share of a droplet's protein that is bleached. */\nconst FRAP_SHARE = 1 / 3;\n/** Smallest droplet that can be partly bleached. */\nexport const FRAP_MIN_SIZE = 15;\n\nexport const SCAN_VALUES: Record<ScanKey, number[]> = {\n  chi: [0.5, 1, 1.5, 2, 2.5, 3, 3.5, 4, 5],\n  proteinCount: [20, 40, 60, 80, 120, 160, 200, 260, 320, 400],\n  temperature: [0.4, 0.7, 1, 1.3, 1.6, 2, 2.4, 2.8],\n};\nconst SCAN_STEPS = 2500;\nconst SCAN_SEEDS = [11, 23];\n\nexport function regionName(x: number, y: number): string {\n  const col = x < WORLD_W / 3 ? \"left\" : x < (2 * WORLD_W) / 3 ? \"centre\" : \"right\";\n  const row = y < WORLD_H / 3 ? \"top\" : y < (2 * WORLD_H) / 3 ? \"middle\" : \"bottom\";\n  if (row === \"middle\" && col === \"centre\") return \"centre\";\n  if (row === \"middle\") return `middle ${col}`;\n  return `${row} ${col}`;\n}\n\nfunction dropletState(solidFraction: number): DropletState {\n  return solidFraction >= 0.8 ? \"solid\" : solidFraction > 0 ? \"hardening\" : \"liquid\";\n}\n\ninterface Track {\n  age: number;\n  announcedFormed: boolean;\n  announcedSolid: boolean;\n  size: number;\n}\n\ntype Listener = () => void;\n\nexport class LabStore {\n  private params: SimParams;\n  world: World;\n  private running = false;\n  private speed = 1;\n  private droplets: Droplet[] = [];\n  private history: HistoryPoint[] = [];\n  private events: LabEvent[] = [];\n  private selectedId: number | null = null;\n  private frap: FrapRun | null = null;\n  private frapRuns: FrapRun[] = [];\n  private scan: Scan | null = null;\n  private imported: ImportedFrap | null = null;\n  private runId = 0;\n\n  private owner: Int32Array; // droplet id per molecule from the last analysis\n  private membersById = new Map<number, number[]>();\n  private tracks = new Map<number, Track>();\n  private nextDropletId = 1;\n  private nextEventId = 1;\n  private nextFrapId = 1;\n  private stepAcc = 0;\n  private sinceAnalysis = 0;\n  private raf = 0;\n  private lastPublish = 0;\n  private scanTimer: ReturnType<typeof setTimeout> | null = null;\n\n  private snapshot: Snapshot;\n  private listeners = new Set<Listener>();\n  private frameListeners = new Set<Listener>();\n\n  constructor(params: SimParams = DEFAULT_PARAMS) {\n    this.params = sanitizeParams(params);\n    this.world = createWorld(this.params);\n    this.owner = new Int32Array(this.world.n).fill(-1);\n    this.analyse(false);\n    this.snapshot = this.build();\n  }\n\n  // ─── subscription ──────────────────────────────────────────────────────\n\n  subscribe = (l: Listener) => {\n    this.listeners.add(l);\n    return () => {\n      this.listeners.delete(l);\n    };\n  };\n\n  getSnapshot = () => this.snapshot;\n\n  /** Called after every simulated frame (for the canvas), even between published snapshots. */\n  onFrame(l: Listener) {\n    this.frameListeners.add(l);\n    return () => {\n      this.frameListeners.delete(l);\n    };\n  }\n\n  private publish(force = true) {\n    const now = typeof performance !== \"undefined\" ? performance.now() : Date.now();\n    if (!force && now - this.lastPublish < 250) return;\n    this.lastPublish = now;\n    this.snapshot = this.build();\n    for (const l of this.listeners) l();\n  }\n\n  private frame() {\n    for (const l of this.frameListeners) l();\n  }\n\n  private build(): Snapshot {\n    const pTotal = proteinCount(this.world);\n    const rnaTotal = this.world.n - pTotal;\n    const inDroplets = this.droplets.reduce((s, d) => s + d.protein, 0);\n    let solidAll = 0;\n    for (let i = 0; i < this.world.n; i++) if (this.world.solid[i]) solidAll++;\n    const fraction = pTotal > 0 ? inDroplets / pTotal : 0;\n    const phase: Phase = fraction < 0.15 ? \"mixed\" : fraction < 0.35 ? \"borderline\" : \"separated\";\n    return {\n      params: this.params,\n      running: this.running,\n      speed: this.speed,\n      time: this.world.time,\n      droplets: this.droplets,\n      summary: {\n        fraction,\n        count: this.droplets.length,\n        solidFraction: pTotal > 0 ? solidAll / pTotal : 0,\n        largest: this.droplets[0]?.size ?? 0,\n        phase,\n        trend: this.trend(),\n        rnaInDroplets: this.droplets.reduce((s, d) => s + d.rna, 0),\n        rnaTotal,\n      },\n      history: this.history,\n      events: this.events,\n      selectedId: this.selectedId,\n      frap: this.frap,\n      frapRuns: this.frapRuns,\n      scan: this.scan,\n      imported: this.imported,\n      runId: this.runId,\n    };\n  }\n\n  private trend(): Trend {\n    const h = this.history;\n    if (h.length < 12) return \"unknown\";\n    const recent = h.slice(-6).reduce((s, p) => s + p.fraction, 0) / 6;\n    const before = h.slice(-12, -6).reduce((s, p) => s + p.fraction, 0) / 6;\n    const d = recent - before;\n    return d > 0.03 ? \"rising\" : d < -0.03 ? \"falling\" : \"steady\";\n  }\n\n  // ─── running ───────────────────────────────────────────────────────────\n\n  play = () => {\n    if (this.running) return;\n    this.running = true;\n    this.publish();\n    this.loop();\n  };\n\n  pause = () => {\n    if (!this.running) return;\n    this.running = false;\n    if (this.raf) cancelAnimationFrame(this.raf);\n    this.raf = 0;\n    this.publish();\n  };\n\n  toggle = () => (this.running ? this.pause() : this.play());\n\n  private loop = () => {\n    if (!this.running) return;\n    this.stepAcc += STEPS_PER_FRAME * this.speed;\n    const n = Math.floor(this.stepAcc);\n    this.stepAcc -= n;\n    if (n > 0) this.advance(n, true);\n    this.frame();\n    this.publish(false);\n    this.raf = requestAnimationFrame(this.loop);\n  };\n\n  /** Advances `n` steps, analysing on schedule. */\n  private advance(n: number, record: boolean) {\n    let left = n;\n    while (left > 0) {\n      const chunk = Math.min(left, ANALYSE_EVERY - this.sinceAnalysis);\n      step(this.world, this.params, chunk);\n      this.sinceAnalysis += chunk;\n      left -= chunk;\n      if (this.sinceAnalysis >= ANALYSE_EVERY) {\n        this.sinceAnalysis = 0;\n        this.analyse(record);\n      }\n    }\n  }\n\n  /** Runs one analysis interval (5 steps) and stops. */\n  stepOnce = () => {\n    this.pause();\n    this.advance(ANALYSE_EVERY - this.sinceAnalysis, true);\n    this.frame();\n    this.publish();\n  };\n\n  /** Computes `timeUnits` of simulation instantly, without animating. */\n  jump = (timeUnits: number) => {\n    const wasRunning = this.running;\n    this.pause();\n    this.advance(Math.round(timeUnits / DT), true);\n    this.frame();\n    this.publish();\n    if (wasRunning) this.play();\n  };\n\n  setSpeed = (s: number) => {\n    this.speed = s;\n    this.publish();\n  };\n\n  // ─── settings ──────────────────────────────────────────────────────────\n\n  setParam = (key: NumericKey, value: number) => {\n    const v = clampParam(key, value);\n    if (this.params[key] === v) return;\n    this.params = { ...this.params, [key]: v };\n    if (specFor(key).restarts) this.restart(`Restarted with ${this.params.proteinCount} proteins and ${this.params.multiComponent ? this.params.rnaCount : 0} RNA.`);\n    else this.publish();\n  };\n\n  setFlag = (key: \"multiComponent\" | \"diseaseMode\", value: boolean) => {\n    if (this.params[key] === value) return;\n    this.params = { ...this.params, [key]: value };\n    if (key === \"multiComponent\") {\n      this.restart(value ? \"RNA added. Restarted.\" : \"RNA removed. Restarted with protein only.\");\n      return;\n    }\n    if (value) this.log(\"info\", \"Disease mode on: large droplets can now harden.\");\n    else this.log(\"info\", \"Disease mode off: no new hardening. Clumps that already formed stay solid until you reset.\");\n    this.publish();\n  };\n\n  /** Applies several settings; restarts only if the molecules themselves change. */\n  applyParams = (partial: Partial<SimParams>, label?: string) => {\n    const next = sanitizeParams({ ...this.params, ...partial });\n    const needsRestart =\n      next.proteinCount !== this.params.proteinCount ||\n      next.rnaCount !== this.params.rnaCount ||\n      next.multiComponent !== this.params.multiComponent ||\n      next.seed !== this.params.seed;\n    const diseaseTurnedOff = this.params.diseaseMode && !next.diseaseMode;\n    this.params = next;\n    if (needsRestart) this.restart(label ? `${label}: restarted with new molecules.` : \"Restarted with new molecules.\");\n    else {\n      if (label) this.log(\"info\", `${label} applied.`);\n      if (diseaseTurnedOff) this.log(\"info\", \"Disease mode off: clumps that already formed stay solid until you reset.\");\n      this.publish();\n    }\n  };\n\n  /** New molecules in new random places (same settings). */\n  reset = () => this.restart(\"Reset: new run with the same settings.\");\n\n  newSeed = () => {\n    const rng = makeRng(Date.now() & 0xffffff);\n    this.params = { ...this.params, seed: 1 + Math.floor(rng() * 999999) };\n    this.restart(`New random start (seed ${this.params.seed}).`);\n  };\n\n  private restart(message: string) {\n    this.world = createWorld(this.params);\n    this.owner = new Int32Array(this.world.n).fill(-1);\n    this.tracks.clear();\n    this.droplets = [];\n    this.history = [];\n    this.selectedId = null;\n    if (this.frap && this.frap.status === \"recording\") this.endFrap(\"The run restarted.\");\n    this.frap = null;\n    this.stepAcc = 0;\n    this.sinceAnalysis = 0;\n    this.runId++;\n    this.events = [];\n    this.analyse(false);\n    this.log(\"info\", message);\n    this.frame();\n    this.publish();\n  }\n\n  // ─── analysis ──────────────────────────────────────────────────────────\n\n  private log(kind: EventKind, text: string) {\n    this.events = [...this.events, { id: this.nextEventId++, t: this.world.time, kind, text }].slice(-60);\n  }\n\n  private analyse(record: boolean) {\n    const w = this.world;\n    let clusters = findClusters(w);\n    if (this.params.diseaseMode) {\n      harden(w, this.params, clusters, ANALYSE_EVERY * DT);\n      // solid counts changed: refresh\n      clusters = clusters.map((c) => ({ ...c, solid: c.members.reduce((s, m) => s + w.solid[m], 0) }));\n    }\n\n    // match clusters to the previous droplets by shared molecules\n    const taken = new Set<number>();\n    const newOwner = new Int32Array(w.n).fill(-1);\n    const next: Droplet[] = [];\n    const absorbedBy = new Map<number, number>();\n    const members = new Map<number, number[]>();\n    for (const c of clusters) {\n      const overlap = new Map<number, number>();\n      for (const m of c.members) {\n        const o = this.owner[m];\n        if (o >= 0) overlap.set(o, (overlap.get(o) ?? 0) + 1);\n      }\n      const ranked = [...overlap.entries()].sort((a, b) => b[1] - a[1]);\n      let id = -1;\n      for (const [cand, k] of ranked) {\n        if (k >= 3 && !taken.has(cand)) {\n          id = cand;\n          break;\n        }\n      }\n      if (id < 0) id = this.nextDropletId++;\n      taken.add(id);\n      for (const [cand, k] of ranked) {\n        if (cand === id || k < 3) continue;\n        const prev = this.tracks.get(cand);\n        if (prev && k >= 0.3 * prev.size) absorbedBy.set(cand, id);\n      }\n      for (const m of c.members) newOwner[m] = id;\n      members.set(id, c.members);\n      const solidFraction = c.protein > 0 ? c.solid / c.protein : 0;\n      next.push({\n        id,\n        size: c.members.length,\n        protein: c.protein,\n        rna: c.rna,\n        solid: c.solid,\n        solidFraction,\n        state: dropletState(solidFraction),\n        cx: c.cx,\n        cy: c.cy,\n        radius: c.radius,\n        region: regionName(c.cx, c.cy),\n      });\n    }\n\n    // events\n    const nextTracks = new Map<number, Track>();\n    for (const d of next) {\n      const prev = this.tracks.get(d.id);\n      const t: Track = prev\n        ? { ...prev, age: prev.age + 1, size: d.size }\n        : { age: 0, announcedFormed: false, announcedSolid: false, size: d.size };\n      if (record && !t.announcedFormed && t.age >= ESTABLISHED_AGE) {\n        t.announcedFormed = true;\n        this.log(\"formed\", `Droplet ${d.id} formed (${d.size} molecules, ${d.region}).`);\n      }\n      if (record && !t.announcedSolid && d.state === \"solid\") {\n        t.announcedSolid = true;\n        this.log(\"solidified\", `Droplet ${d.id} turned solid.`);\n      }\n      nextTracks.set(d.id, t);\n    }\n    if (record) {\n      const mergedInto = new Map<number, number[]>();\n      for (const [oldId, track] of this.tracks) {\n        if (nextTracks.has(oldId) || !track.announcedFormed) continue;\n        const into = absorbedBy.get(oldId);\n        if (into !== undefined) {\n          const list = mergedInto.get(into) ?? [];\n          list.push(oldId);\n          mergedInto.set(into, list);\n        } else {\n          this.log(\"dissolved\", `Droplet ${oldId} dissolved.`);\n        }\n      }\n      for (const [into, olds] of mergedInto) {\n        this.log(\"merged\", `Droplet${olds.length > 1 ? \"s\" : \"\"} ${olds.join(\" and \")} merged into droplet ${into}.`);\n        // a merged droplet keeps being followed\n        if (this.frap && olds.includes(this.frap.dropletId)) this.frap = { ...this.frap, dropletId: into };\n        if (this.selectedId !== null && olds.includes(this.selectedId)) this.selectedId = into;\n      }\n    }\n    this.tracks = nextTracks;\n    this.owner = newOwner;\n    this.droplets = next;\n    this.membersById = members;\n\n    if (this.selectedId !== null && !next.some((d) => d.id === this.selectedId)) {\n      if (record) this.log(\"info\", `The selected droplet (${this.selectedId}) is gone.`);\n      this.selectedId = null;\n    }\n\n    if (record) {\n      const pTotal = Math.max(1, proteinCount(w));\n      let solidAll = 0;\n      for (let i = 0; i < w.n; i++) if (w.kind[i] === KIND_PROTEIN && w.solid[i]) solidAll++;\n      this.history.push({\n        t: Number(w.time.toFixed(2)),\n        fraction: next.reduce((s, d) => s + d.protein, 0) / pTotal,\n        count: next.length,\n        solidFraction: solidAll / pTotal,\n        largest: next[0]?.size ?? 0,\n      });\n      if (this.history.length > HISTORY_MAX) {\n        // keep the recent half at full detail, thin the older half\n        const half = Math.floor(this.history.length / 2);\n        this.history = [...this.history.slice(0, half).filter((_, i) => i % 2 === 0), ...this.history.slice(half)];\n      } else {\n        this.history = [...this.history];\n      }\n      this.sampleFrap();\n    }\n  }\n\n  // ─── selection ─────────────────────────────────────────────────────────\n\n  select = (id: number | null) => {\n    this.selectedId = id !== null && this.droplets.some((d) => d.id === id) ? id : null;\n    this.frame();\n    this.publish();\n  };\n\n  /** Droplets in reading order (top to bottom, then left to right) for keyboard movement. */\n  readingOrder(): Droplet[] {\n    const band = WORLD_H / 6;\n    return [...this.droplets].sort((a, b) => Math.floor(a.cy / band) - Math.floor(b.cy / band) || a.cx - b.cx);\n  }\n\n  /** Moves the selection; returns the newly selected droplet. */\n  moveSelection = (how: \"next\" | \"prev\" | \"first\" | \"last\"): Droplet | null => {\n    const order = this.readingOrder();\n    if (order.length === 0) {\n      this.select(null);\n      return null;\n    }\n    const i = order.findIndex((d) => d.id === this.selectedId);\n    let j: number;\n    if (how === \"first\") j = 0;\n    else if (how === \"last\") j = order.length - 1;\n    else if (i < 0) j = how === \"next\" ? 0 : order.length - 1;\n    else j = (i + (how === \"next\" ? 1 : -1) + order.length) % order.length;\n    this.select(order[j].id);\n    return order[j];\n  };\n\n  /** The droplet under a point in world coordinates, or the nearest one within reach. */\n  dropletAt(x: number, y: number, reach = 2 * SIGMA): Droplet | null {\n    let best: Droplet | null = null;\n    let bestD = Infinity;\n    for (const d of this.droplets) {\n      const dist = Math.hypot(d.cx - x, d.cy - y) - d.radius;\n      if (dist < bestD) {\n        bestD = dist;\n        best = d;\n      }\n    }\n    return best && bestD <= reach ? best : null;\n  }\n\n  // ─── FRAP ──────────────────────────────────────────────────────────────\n\n  /** Bleaches a spot in the middle of a droplet and starts recording. */\n  bleachDroplet = (id: number): string => {\n    const d = this.droplets.find((x) => x.id === id);\n    if (!d) return \"That droplet is gone. Select another one.\";\n    if (d.size < FRAP_MIN_SIZE)\n      return `Droplet ${d.id} has only ${d.size} molecules: too small to bleach part of it. Pick a droplet with at least ${FRAP_MIN_SIZE}.`;\n    if (this.frap && this.frap.status === \"recording\") this.endFrap(\"A new bleach started.\");\n    // fresh label: earlier bleaching is cleared so each experiment starts bright\n    this.world.bleached.fill(0);\n    // Bleach the third of the droplet's protein nearest its centre. A fixed share\n    // (rather than a fixed size) keeps the rest of the droplet bright, which the\n    // double normalisation needs: a spot covering nearly all of a dense droplet\n    // would read as \"recovered\" even in a solid.\n    const w = this.world;\n    const prot = (this.membersById.get(d.id) ?? [])\n      .filter((m) => w.kind[m] === KIND_PROTEIN)\n      .map((m) => ({ m, r: Math.hypot(w.x[m] - d.cx, w.y[m] - d.cy) }))\n      .sort((a, b) => a.r - b.r);\n    const share = Math.max(3, Math.round(prot.length * FRAP_SHARE));\n    const radius = prot.length ? prot[Math.min(share, prot.length) - 1].r + 0.25 * SIGMA : SIGMA;\n    const k = bleach(w, d.cx, d.cy, radius);\n    this.frap = {\n      id: this.nextFrapId++,\n      dropletId: d.id,\n      stateAtBleach: d.state,\n      solidAtBleach: d.solidFraction,\n      startT: this.world.time,\n      cx: d.cx,\n      cy: d.cy,\n      radius,\n      bleachedCount: k,\n      points: [{ t: 0, intensity: this.spotIntensity(d.id, d.cx, d.cy, radius) ?? 0 }],\n      status: \"recording\",\n      endReason: null,\n      fit: null,\n    };\n    this.selectedId = d.id;\n    this.log(\"info\", `Bleached a spot in droplet ${d.id} (${k} protein molecules). Recording recovery.`);\n    this.frame();\n    this.publish();\n    return `Bleached ${k} protein molecules in droplet ${d.id}. Recording recovery.`;\n  };\n\n  /**\n   * Brightness of the spot relative to the whole droplet (double normalisation,\n   * as labs do): bleaching removes part of the droplet's glow for good, so a\n   * fully mixed liquid droplet reads 1 and a frozen spot stays near 0.\n   */\n  private spotIntensity(dropletId: number, cx: number, cy: number, radius: number): number | null {\n    const spot = brightFraction(this.world, cx, cy, radius);\n    const mem = this.membersById.get(dropletId);\n    if (spot === null || !mem || mem.length === 0) return spot;\n    let bright = 0;\n    let protein = 0;\n    for (const m of mem) {\n      if (this.world.kind[m] !== KIND_PROTEIN) continue;\n      protein++;\n      if (!this.world.bleached[m]) bright++;\n    }\n    if (protein === 0) return spot;\n    const whole = bright / protein;\n    return whole > 0 ? Math.min(1.2, spot / whole) : 0;\n  }\n\n  private sampleFrap() {\n    const f = this.frap;\n    if (!f || f.status !== \"recording\") return;\n    const d = this.droplets.find((x) => x.id === f.dropletId);\n    if (!d) {\n      this.endFrap(`Droplet ${f.dropletId} dissolved, so the recording stopped.`);\n      return;\n    }\n    // The spot moves with the bleached material, as a bleach mark would: in a\n    // liquid the dark molecules spread out and their centre drifts to the\n    // droplet's centre; in a solid they stay together and the spot stays on them.\n    // (Following the droplet's centre instead let the spot slide off a solid's dark\n    // patch as liquid molecules joined one side.)\n    let bx = 0;\n    let by = 0;\n    let nb = 0;\n    for (const m of this.membersById.get(d.id) ?? []) {\n      if (this.world.bleached[m] && this.world.kind[m] === KIND_PROTEIN) {\n        bx += this.world.x[m];\n        by += this.world.y[m];\n        nb++;\n      }\n    }\n    const cx = nb >= 3 ? bx / nb : d.cx;\n    const cy = nb >= 3 ? by / nb : d.cy;\n    const v = this.spotIntensity(d.id, cx, cy, f.radius);\n    const t = Number((this.world.time - f.startT).toFixed(2));\n    const points = v === null ? f.points : [...f.points, { t, intensity: v }];\n    this.frap = { ...f, cx, cy, points, fit: points.length >= 8 ? fitRecovery(points) : null };\n    if (t >= FRAP_MAX_T) this.endFrap(\"Recording finished.\");\n  }\n\n  stopFrap = () => {\n    if (this.frap && this.frap.status === \"recording\") {\n      this.endFrap(\"Recording stopped.\");\n      this.publish();\n    }\n  };\n\n  private endFrap(reason: string) {\n    const f = this.frap;\n    if (!f) return;\n    const done: FrapRun = { ...f, status: \"ended\", endReason: reason, fit: fitRecovery(f.points) };\n    this.frap = done;\n    this.frapRuns = [...this.frapRuns, done].slice(-6);\n    this.log(\"info\", `FRAP on droplet ${f.dropletId}: ${reason}`);\n  }\n\n  clearFrapRuns = () => {\n    this.frapRuns = [];\n    if (this.frap?.status === \"ended\") this.frap = null;\n    this.publish();\n  };\n\n  // ─── imported data ─────────────────────────────────────────────────────\n\n  importFrap = (name: string, text: string): string => {\n    const r = parseFrapCsv(text);\n    if (\"error\" in r) return r.error;\n    this.imported = { name, points: r.points, notes: r.notes, fit: fitRecovery(r.points) };\n    this.publish();\n    return `Loaded ${r.points.length} readings from ${name}.`;\n  };\n\n  clearImported = () => {\n    this.imported = null;\n    this.publish();\n  };\n\n  // ─── threshold scan ────────────────────────────────────────────────────\n\n  /** Measures droplet formation across a range of one setting, in the background. */\n  runScan = (key: ScanKey) => {\n    this.cancelScan(false);\n    const values = SCAN_VALUES[key];\n    const base = { ...this.params };\n    const jobs: { value: number; seed: number }[] = [];\n    for (const value of values) for (const seed of SCAN_SEEDS) jobs.push({ value, seed });\n    const results = new Map<number, number[]>();\n    this.scan = { key, status: \"running\", points: [], total: values.length, base };\n    this.publish();\n    let j = 0;\n    let world: World | null = null;\n    let done = 0;\n    let params: SimParams = base;\n    const tick = () => {\n      if (!this.scan || this.scan.status !== \"running\") return;\n      const job = jobs[j];\n      if (!world) {\n        params = { ...base, [key]: job.value, seed: job.seed, diseaseMode: false };\n        world = createWorld(params);\n        done = 0;\n      }\n      const chunk = 500;\n      step(world, params, chunk);\n      done += chunk;\n      if (done >= SCAN_STEPS) {\n        const cl = findClusters(world);\n        const frac = cl.reduce((s, c) => s + c.protein, 0) / Math.max(1, proteinCount(world));\n        const list = results.get(job.value) ?? [];\n        list.push(frac);\n        results.set(job.value, list);\n        world = null;\n        j++;\n        const points: ScanPoint[] = values\n          .filter((v) => (results.get(v)?.length ?? 0) === SCAN_SEEDS.length)\n          .map((v) => {\n            const r = results.get(v)!;\n            return { value: v, fraction: r.reduce((a, b) => a + b, 0) / r.length, min: Math.min(...r), max: Math.max(...r) };\n          });\n        const finished = j >= jobs.length;\n        this.scan = { ...this.scan, points, status: finished ? \"done\" : \"running\" };\n        this.publish();\n        if (finished) return;\n      }\n      this.scanTimer = setTimeout(tick, 0);\n    };\n    this.scanTimer = setTimeout(tick, 0);\n  };\n\n  cancelScan = (publish = true) => {\n    if (this.scanTimer) clearTimeout(this.scanTimer);\n    this.scanTimer = null;\n    if (this.scan && this.scan.status === \"running\") this.scan = { ...this.scan, status: \"cancelled\" };\n    if (publish) this.publish();\n  };\n\n  dispose() {\n    this.pause();\n    this.cancelScan(false);\n    this.listeners.clear();\n    this.frameListeners.clear();\n  }\n}\n\n/** Where the scan says droplets start: the first crossing of 30% protein in droplets. */\nexport function scanThreshold(scan: Scan): { kind: \"crossing\"; value: number; rising: boolean } | { kind: \"none\" | \"all\" | \"unclear\" } {\n  const pts = scan.points;\n  if (pts.length < 2) return { kind: \"unclear\" };\n  const level = 0.3;\n  const above = pts.map((p) => p.fraction >= level);\n  if (above.every(Boolean)) return { kind: \"all\" };\n  if (!above.some(Boolean)) return { kind: \"none\" };\n  for (let i = 1; i < pts.length; i++) {\n    if (above[i] !== above[i - 1]) {\n      const a = pts[i - 1];\n      const b = pts[i];\n      const f = (level - a.fraction) / (b.fraction - a.fraction);\n      return { kind: \"crossing\", value: a.value + f * (b.value - a.value), rising: above[i] };\n    }\n  }\n  return { kind: \"unclear\" };\n}\n",
    "packages/access/README.md": "# @repo/access\n\nOne place for what every LogueBio tool needs to adapt to the person using it:\n\n- **Settings** (`useAccess`, `updateSettings`, `AccessSettingsPanel`): colour scheme,\n  contrast, colour-blind palette, text size and spacing, motion, autoplay, simpler\n  interface, reading time, explanations, sound and vibration. Saved in a cookie that\n  every tool shares (localhost ports share cookies in development; `.loguebio.com`\n  in production), with a localStorage copy. Nothing leaves the device.\n- **What the person declares wins**: `resolveSettings` only falls back to the\n  device's own settings (reduced motion, dark mode) when the choice is \"Follow my device\".\n- **Palette** (`categoryColors`, `cividis`): Okabe-Ito categories, a blue-yellow\n  (tritan) set and a high-contrast set, in one fixed order; cividis for scales.\n  Always pair colour with a shape or a word.\n- **Announcer** (`announce`): hidden live regions; drops repeats, merges polite\n  messages by `topic`, and spaces them out (`setAnnounceGap`, longer with\n  \"longer reading time\").\n- **Vibration** (`canVibrate`, `vibrate`): only when turned on and supported.\n\n```tsx\n// app/layout.tsx: apply saved settings before first paint\nimport { ACCESS_BOOT_SCRIPT } from '@repo/access/boot';   // server-safe entry\n<head><script dangerouslySetInnerHTML={{ __html: ACCESS_BOOT_SCRIPT }} /></head>\n\n// any client component\n'use client';\nimport { useAccess, applySettingsToDocument, AccessSettingsPanel, announce } from '@repo/access';\nconst access = useAccess();\nuseEffect(() => applySettingsToDocument(access), [access]);\nannounce('3 droplets formed', { topic: 'droplets' });\n```\n\nThe `<html>` element then carries `data-theme`, `data-contrast`, `data-motion`,\n`data-spacing`, `data-palette`, `data-simpler` and `data-text-size` (100, 125,\n150, 200), and `--access-text-scale` for CSS. Screen-width media queries ignore\nthe text size, so use `data-text-size` to drop columns when text is large.\n\nPlain JavaScript with type declarations, like `@repo/suite`, so it needs no build\nstep and no `transpilePackages`.\n",
    "packages/access/announce.js": "// One screen-reader announcer for the suite.\n//\n// Two hidden live regions (polite and assertive) are added to <body> on first\n// use. Messages announce changes, not re-reads: an identical message is\n// dropped, and polite messages with the same `topic` replace each other while\n// they wait, so a fast simulation produces one up-to-date sentence instead of\n// a flood. The gap between polite messages grows with \"longer reading time\".\n\nconst regions = { polite: null, assertive: null };\nlet gapMs = 1500;\nlet lastText = '';\nlet lastAt = 0;\nlet pending = new Map(); // topic -> text\nlet timer = null;\nlet lastFlush = 0;\nconst history = [];\nconst historyListeners = new Set();\n\nfunction region(priority) {\n  if (typeof document === 'undefined') return null;\n  if (regions[priority] && document.body.contains(regions[priority])) return regions[priority];\n  const el = document.createElement('div');\n  el.setAttribute('aria-live', priority);\n  el.setAttribute('aria-atomic', 'true');\n  el.setAttribute('role', priority === 'assertive' ? 'alert' : 'status');\n  el.dataset.accessAnnouncer = priority;\n  Object.assign(el.style, {\n    position: 'absolute', width: '1px', height: '1px', margin: '-1px', padding: '0',\n    overflow: 'hidden', clip: 'rect(0 0 0 0)', whiteSpace: 'nowrap', border: '0',\n  });\n  document.body.appendChild(el);\n  regions[priority] = el;\n  return el;\n}\n\nfunction speak(priority, text) {\n  const el = region(priority);\n  if (!el) return;\n  el.textContent = '';\n  // A short delay makes screen readers treat the new text as a change.\n  setTimeout(() => {\n    el.textContent = text;\n  }, 60);\n  lastText = text;\n  lastAt = Date.now();\n  history.push({ at: lastAt, text, priority });\n  if (history.length > 100) history.shift();\n  for (const l of historyListeners) l();\n}\n\nfunction flush() {\n  timer = null;\n  if (pending.size === 0) return;\n  const text = Array.from(pending.values()).join(' ');\n  pending = new Map();\n  lastFlush = Date.now();\n  if (text === lastText && Date.now() - lastAt < 10000) return;\n  speak('polite', text);\n}\n\n/**\n * Queues a message for screen readers.\n * @param {string} text\n * @param {{priority?: 'polite'|'assertive', topic?: string}} [opts]\n */\nexport function announce(text, opts = {}) {\n  if (!text) return;\n  const priority = opts.priority || 'polite';\n  if (priority === 'assertive') {\n    speak('assertive', text);\n    return;\n  }\n  pending.set(opts.topic || text, text);\n  if (timer) return;\n  const wait = Math.max(0, gapMs - (Date.now() - lastFlush));\n  timer = setTimeout(flush, wait);\n}\n\n/** Sets the minimum gap between polite announcements (ms). */\nexport function setAnnounceGap(ms) {\n  gapMs = Math.max(250, ms);\n}\n\n/** Recent announcements, newest last, so a page can show them as text too. */\nexport function getAnnouncementHistory() {\n  return history.slice();\n}\n\nexport function subscribeAnnouncements(listener) {\n  historyListeners.add(listener);\n  return () => historyListeners.delete(listener);\n}\n\n/** Device vibration, if the person turned it on and the device supports it. */\nexport function canVibrate() {\n  return typeof navigator !== 'undefined' && typeof navigator.vibrate === 'function';\n}\n\nexport function vibrate(pattern, settings) {\n  if (!settings || !settings.vibration || !canVibrate()) return false;\n  try {\n    return navigator.vibrate(pattern);\n  } catch {\n    return false;\n  }\n}\n",
    "packages/access/boot.d.ts": "/** Inline <head> script that applies saved settings before first paint. Safe in server components. */\nexport const ACCESS_BOOT_SCRIPT: string;\n",
    "packages/access/boot.js": "// Server-safe: no React. Import from '@repo/access/boot' in layouts.\n\nconst COOKIE = 'loguebio_access';\nconst STORAGE_KEY = 'loguebio.access.v1';\nconst SETTINGS_VERSION = 1;\n\n/**\n * Inline script for <head>: applies saved settings before the first paint, so\n * a person who chose dark, high contrast or large text never sees a flash of\n * the defaults. Kept dependency-free and tolerant of bad cookies.\n */\nexport const ACCESS_BOOT_SCRIPT = `(function(){try{var m=document.cookie.match(/(?:^|; )${COOKIE}=([^;]*)/);var r=m?JSON.parse(decodeURIComponent(m[1])):JSON.parse(localStorage.getItem('${STORAGE_KEY}')||'null');var s=(r&&r.v===${SETTINGS_VERSION}&&r.s)||{};var mm=function(q){return window.matchMedia&&matchMedia(q).matches};var e=document.documentElement;var dark=s.theme==='dark'||((!s.theme||s.theme==='system')&&mm('(prefers-color-scheme: dark)'));e.dataset.theme=dark?'dark':'light';e.dataset.contrast=s.contrast==='high'?'high':'normal';e.dataset.motion=(s.motion==='reduce'||((!s.motion||s.motion==='system')&&mm('(prefers-reduced-motion: reduce)')))?'reduce':'allow';e.dataset.spacing=s.spacing==='wide'?'wide':'normal';e.dataset.palette=s.contrast==='high'?'high-contrast':(s.palette==='tritan'?'tritan':'standard');e.dataset.simpler=s.simpler?'true':'false';var t=[100,125,150,200].indexOf(s.textSize)>=0?s.textSize:100;e.dataset.textSize=String(t);e.style.setProperty('--access-text-scale',String(t/100));}catch(_){}})();`;\n",
    "packages/access/index.d.ts": "import type { ReactElement } from 'react';\n\nexport interface AccessSettings {\n  /** Colour scheme. */\n  theme: 'system' | 'light' | 'dark';\n  contrast: 'normal' | 'high';\n  /** Category colours: standard (Okabe-Ito) or tuned for blue-yellow colour blindness. */\n  palette: 'standard' | 'tritan';\n  /** Percent. */\n  textSize: 100 | 125 | 150 | 200;\n  spacing: 'normal' | 'wide';\n  motion: 'system' | 'reduce' | 'allow';\n  /** Whether simulations start by themselves. 'auto' follows the motion setting. */\n  autoplay: 'auto' | 'never' | 'always';\n  /** Main controls first, the rest one step away. */\n  simpler: boolean;\n  readingTime: 'normal' | 'longer';\n  guidance: 'beginner' | 'expert';\n  sound: boolean;\n  vibration: boolean;\n}\n\nexport type PaletteName = 'standard' | 'tritan' | 'high-contrast';\n\nexport interface ResolvedAccess {\n  settings: AccessSettings;\n  reducedMotion: boolean;\n  dark: boolean;\n  highContrast: boolean;\n  /** Whether a simulation may start without the person pressing Play. */\n  autoplay: boolean;\n  paletteName: PaletteName;\n  /** 1 normally, larger with \"longer reading time\". Multiply message durations by it. */\n  readingFactor: number;\n  beginner: boolean;\n  systemContrastMore: boolean;\n  /** True only during server rendering, before the person's settings are known. */\n  server?: boolean;\n}\n\nexport const DEFAULT_SETTINGS: Readonly<AccessSettings>;\nexport const SETTINGS_VERSION: number;\n/** Inline <head> script that applies saved settings before first paint. */\nexport const ACCESS_BOOT_SCRIPT: string;\nexport function sanitizeSettings(input: unknown): AccessSettings;\nexport function getSettings(): Readonly<AccessSettings>;\nexport function updateSettings(partial: Partial<AccessSettings>): void;\nexport function resetSettings(): void;\nexport function subscribeSettings(listener: () => void): () => void;\nexport function resolveSettings(s: AccessSettings): ResolvedAccess;\n/** React hook: settings resolved against system preferences. */\nexport function useAccess(): ResolvedAccess;\n/** Sets data-theme, data-contrast, data-motion, data-spacing, data-palette, data-simpler, data-text-size and --access-text-scale on <html>. */\nexport function applySettingsToDocument(resolved: ResolvedAccess): void;\n\nexport const PALETTES: Readonly<Record<PaletteName, { light: string[]; dark: string[] }>>;\nexport const OKABE_ITO: Readonly<Record<string, string>>;\n/** Category colours in the suite's fixed order. */\nexport function categoryColors(paletteName: PaletteName, dark: boolean): string[];\n/** Perceptually uniform sequential colour (cividis) for t in 0–1. */\nexport function cividis(t: number): string;\n/** WCAG contrast ratio of two #rrggbb colours. */\nexport function contrastRatio(hexA: string, hexB: string): number;\n\nexport interface AnnounceOptions {\n  priority?: 'polite' | 'assertive';\n  /** Polite messages with the same topic replace each other while waiting. */\n  topic?: string;\n}\nexport function announce(text: string, opts?: AnnounceOptions): void;\nexport function setAnnounceGap(ms: number): void;\nexport function getAnnouncementHistory(): { at: number; text: string; priority: 'polite' | 'assertive' }[];\nexport function subscribeAnnouncements(listener: () => void): () => void;\nexport function canVibrate(): boolean;\nexport function vibrate(pattern: number | number[], settings: AccessSettings): boolean;\n\nexport interface AccessSettingsPanelProps {\n  /** Heading level for the section titles. Default 3. */\n  headingLevel?: 2 | 3 | 4;\n  onReset?: () => void;\n}\n/** The suite's settings form: applies and saves every change at once. */\nexport function AccessSettingsPanel(props?: AccessSettingsPanelProps): ReactElement;\n",
    "packages/access/index.js": "export {\n  DEFAULT_SETTINGS,\n  SETTINGS_VERSION,\n  ACCESS_BOOT_SCRIPT,\n  sanitizeSettings,\n  getSettings,\n  updateSettings,\n  resetSettings,\n  subscribeSettings,\n  resolveSettings,\n  useAccess,\n  applySettingsToDocument,\n} from './settings.js';\nexport { PALETTES, OKABE_ITO, categoryColors, cividis, contrastRatio } from './palette.js';\nexport {\n  announce,\n  setAnnounceGap,\n  getAnnouncementHistory,\n  subscribeAnnouncements,\n  canVibrate,\n  vibrate,\n} from './announce.js';\nexport { AccessSettingsPanel } from './panel.js';\n",
    "packages/access/package.json": "{\n  \"name\": \"@repo/access\",\n  \"version\": \"0.0.0\",\n  \"private\": true,\n  \"description\": \"One settings source, palette and screen-reader announcer for every LogueBio tool\",\n  \"type\": \"module\",\n  \"main\": \"./index.js\",\n  \"types\": \"./index.d.ts\",\n  \"exports\": {\n    \".\": {\n      \"types\": \"./index.d.ts\",\n      \"default\": \"./index.js\"\n    },\n    \"./boot\": {\n      \"types\": \"./boot.d.ts\",\n      \"default\": \"./boot.js\"\n    }\n  },\n  \"sideEffects\": false,\n  \"peerDependencies\": {\n    \"react\": \">=18\"\n  }\n}",
    "packages/access/palette.js": "// One palette for the suite. Categories always come with a shape and a word\n// as well; colour is never the only carrier of meaning.\n//\n// standard: Okabe-Ito (Wong 2011), safe for red-green colour blindness.\n// tritan:   for blue-yellow colour blindness (tritanopia); avoids blue/green\n//           and yellow/pink pairs that tritan vision merges.\n// high-contrast: maximum contrast against the background.\n\nconst OKABE_ITO = {\n  orange: '#E69F00',\n  skyBlue: '#56B4E9',\n  bluishGreen: '#009E73',\n  yellow: '#F0E442',\n  blue: '#0072B2',\n  vermillion: '#D55E00',\n  reddishPurple: '#CC79A7',\n  grey: '#999999',\n};\n\n/**\n * Category colours in a fixed order, per palette and background.\n * Pick by index (category 0, 1, 2 …) so every tool uses the same order.\n */\nexport const PALETTES = Object.freeze({\n  standard: {\n    light: ['#0072B2', '#D55E00', '#009E73', '#CC79A7', '#E69F00', '#56B4E9', '#000000'],\n    dark: ['#56B4E9', '#E69F00', '#009E73', '#CC79A7', '#F0E442', '#D55E00', '#FFFFFF'],\n  },\n  tritan: {\n    light: ['#1F5FA8', '#C2410C', '#111111', '#8B5CF6', '#B91C1C', '#0E7490', '#6B7280'],\n    dark: ['#7DB7FF', '#FF8A4C', '#F5F5F5', '#C4A7FF', '#FF6B6B', '#5EEAD4', '#9CA3AF'],\n  },\n  'high-contrast': {\n    light: ['#0033CC', '#B30000', '#000000', '#6600AA', '#8A4B00', '#006060', '#444444'],\n    dark: ['#66CCFF', '#FFD400', '#FFFFFF', '#FF66FF', '#00FF7F', '#FF9966', '#CCCCCC'],\n  },\n});\n\nexport { OKABE_ITO };\n\nexport function categoryColors(paletteName, dark) {\n  const p = PALETTES[paletteName] || PALETTES.standard;\n  return dark ? p.dark : p.light;\n}\n\n// Cividis (Nuñez et al. 2018): perceptually uniform and readable with any\n// colour vision. 9 stops, linearly interpolated.\nconst CIVIDIS = [\n  [0, 34, 78], [18, 53, 112], [59, 73, 108], [87, 92, 109], [112, 113, 115],\n  [138, 134, 120], [165, 156, 116], [195, 179, 105], [254, 232, 56],\n];\n\n/** Sequential colour for t in 0–1, as an rgb() string. */\nexport function cividis(t) {\n  const x = Math.min(1, Math.max(0, Number.isFinite(t) ? t : 0)) * (CIVIDIS.length - 1);\n  const i = Math.min(CIVIDIS.length - 2, Math.floor(x));\n  const f = x - i;\n  const a = CIVIDIS[i];\n  const b = CIVIDIS[i + 1];\n  const c = a.map((v, k) => Math.round(v + (b[k] - v) * f));\n  return `rgb(${c[0]}, ${c[1]}, ${c[2]})`;\n}\n\n/** WCAG contrast ratio between two #rrggbb colours. */\nexport function contrastRatio(hexA, hexB) {\n  const lum = (hex) => {\n    const n = parseInt(hex.replace('#', ''), 16);\n    const ch = [(n >> 16) & 255, (n >> 8) & 255, n & 255].map((v) => {\n      const s = v / 255;\n      return s <= 0.03928 ? s / 12.92 : Math.pow((s + 0.055) / 1.055, 2.4);\n    });\n    return 0.2126 * ch[0] + 0.7152 * ch[1] + 0.0722 * ch[2];\n  };\n  const [l1, l2] = [lum(hexA), lum(hexB)].sort((a, b) => b - a);\n  return (l1 + 0.05) / (l2 + 0.05);\n}\n",
    "packages/access/panel.js": "// The suite's settings form. Plain radios and checkboxes, so it works with a\n// keyboard, screen reader, braille display, switch access and voice control\n// (\"click Dark\"). Every change applies at once and is saved for all tools.\n// Colours inherit from the page, so it fits any tool's theme.\n\nimport { createElement as h, useId } from 'react';\nimport { useAccess, updateSettings, resetSettings } from './settings.js';\nimport { canVibrate } from './announce.js';\n\nconst S = {\n  group: { border: '1px solid color-mix(in srgb, currentColor 30%, transparent)', borderRadius: 10, padding: '10px 14px 12px', margin: '0 0 14px' },\n  legend: { fontWeight: 650, padding: '0 6px' },\n  hint: { margin: '2px 0 8px', fontSize: '0.9em', opacity: 0.85 },\n  options: { display: 'flex', flexWrap: 'wrap', gap: 8 },\n  option: { display: 'inline-flex', alignItems: 'center', gap: 8, minHeight: 44, padding: '4px 12px 4px 8px', border: '1px solid color-mix(in srgb, currentColor 35%, transparent)', borderRadius: 8, cursor: 'pointer' },\n  input: { width: 22, height: 22, margin: 0, accentColor: 'currentColor', flex: 'none' },\n  section: { margin: '0 0 6px', fontSize: '1.05em' },\n  button: { minHeight: 44, padding: '8px 16px', borderRadius: 8, border: '1px solid currentColor', background: 'transparent', color: 'inherit', font: 'inherit', cursor: 'pointer' },\n  small: { fontSize: '0.9em', opacity: 0.85, margin: '8px 0 0' },\n};\n\nfunction Radios({ name, legend, hint, value, options, onChange }) {\n  const id = useId();\n  return h(\n    'fieldset',\n    { style: S.group, 'aria-describedby': hint ? id + '-hint' : undefined },\n    h('legend', { style: S.legend }, legend),\n    hint ? h('p', { id: id + '-hint', style: S.hint }, hint) : null,\n    h(\n      'div',\n      { style: S.options },\n      options.map((o) =>\n        h(\n          'label',\n          { key: String(o.value), style: S.option },\n          h('input', {\n            type: 'radio',\n            name: id + name,\n            value: String(o.value),\n            checked: value === o.value,\n            onChange: () => onChange(o.value),\n            style: S.input,\n          }),\n          h('span', null, o.label),\n        ),\n      ),\n    ),\n  );\n}\n\nfunction Check({ label, hint, checked, onChange, disabled }) {\n  const id = useId();\n  return h(\n    'div',\n    { style: { margin: '0 0 10px' } },\n    h(\n      'label',\n      { style: { ...S.option, opacity: disabled ? 0.6 : 1 } },\n      h('input', {\n        type: 'checkbox',\n        checked,\n        disabled,\n        onChange: (e) => onChange(e.target.checked),\n        style: S.input,\n        'aria-describedby': hint ? id + '-hint' : undefined,\n      }),\n      h('span', null, label),\n    ),\n    hint ? h('p', { id: id + '-hint', style: { ...S.hint, margin: '4px 0 0' } }, hint) : null,\n  );\n}\n\n/**\n * The settings form.\n * @param {{ headingLevel?: 2|3|4, onReset?: () => void }} props\n */\nexport function AccessSettingsPanel(props) {\n  const { settings: s, reducedMotion, server } = useAccess();\n  const level = props && props.headingLevel ? props.headingLevel : 3;\n  const head = (text) => h('h' + level, { style: S.section }, text);\n  const set = (key) => (v) => updateSettings({ [key]: v });\n  const vibrateSupported = !server && canVibrate();\n  return h(\n    'div',\n    { className: 'access-settings' },\n    head('Seeing'),\n    h(Radios, {\n      name: 'theme', legend: 'Colour scheme', value: s.theme, onChange: set('theme'),\n      options: [{ value: 'system', label: 'Follow my device' }, { value: 'light', label: 'Light' }, { value: 'dark', label: 'Dark' }],\n    }),\n    h(Radios, {\n      name: 'contrast', legend: 'Contrast', value: s.contrast, onChange: set('contrast'),\n      hint: 'High contrast uses the strongest colours and thicker outlines.',\n      options: [{ value: 'normal', label: 'Normal contrast' }, { value: 'high', label: 'High contrast' }],\n    }),\n    h(Radios, {\n      name: 'palette', legend: 'Colours for categories', value: s.palette, onChange: set('palette'),\n      hint: 'Both sets also use shapes and labels, so colour is never the only clue. High contrast overrides this.',\n      options: [\n        { value: 'standard', label: 'Standard (safe for red-green colour blindness)' },\n        { value: 'tritan', label: 'Blue-yellow colour blindness' },\n      ],\n    }),\n    h(Radios, {\n      name: 'textSize', legend: 'Text size', value: s.textSize, onChange: set('textSize'),\n      options: [100, 125, 150, 200].map((v) => ({ value: v, label: v + '%' })),\n    }),\n    h(Radios, {\n      name: 'spacing', legend: 'Text spacing', value: s.spacing, onChange: set('spacing'),\n      hint: 'Wider spacing between letters, words and lines can make reading easier, for example with dyslexia.',\n      options: [{ value: 'normal', label: 'Normal spacing' }, { value: 'wide', label: 'Wide spacing' }],\n    }),\n    head('Movement'),\n    h(Radios, {\n      name: 'motion', legend: 'Motion', value: s.motion, onChange: set('motion'),\n      hint: reducedMotion ? 'Motion is reduced now.' : 'Motion is allowed now.',\n      options: [\n        { value: 'system', label: 'Follow my device' },\n        { value: 'reduce', label: 'Reduce motion' },\n        { value: 'allow', label: 'Allow motion' },\n      ],\n    }),\n    h(Radios, {\n      name: 'autoplay', legend: 'Start simulations by themselves', value: s.autoplay, onChange: set('autoplay'),\n      hint: 'Simulations can always be paused, stepped and slowed down.',\n      options: [\n        { value: 'auto', label: 'Only if motion is allowed' },\n        { value: 'never', label: 'Never: I press Play' },\n        { value: 'always', label: 'Always' },\n      ],\n    }),\n    head('Reading and pace'),\n    h(Check, {\n      label: 'Simpler interface', checked: s.simpler, onChange: set('simpler'),\n      hint: 'Shows the main controls first and tucks the rest away. Nothing is removed: every feature stays one step away.',\n    }),\n    h(Radios, {\n      name: 'readingTime', legend: 'Reading time', value: s.readingTime, onChange: set('readingTime'),\n      hint: 'Longer keeps messages on screen longer and spaces out spoken updates.',\n      options: [{ value: 'normal', label: 'Normal' }, { value: 'longer', label: 'Longer' }],\n    }),\n    h(Radios, {\n      name: 'guidance', legend: 'Explanations', value: s.guidance, onChange: set('guidance'),\n      options: [\n        { value: 'beginner', label: 'Show explanations and the guide' },\n        { value: 'expert', label: 'Expert: start with them hidden' },\n      ],\n    }),\n    head('Sound and touch'),\n    h(Check, {\n      label: 'Sounds for changes', checked: s.sound, onChange: set('sound'),\n      hint: 'Short tones when something changes, and an optional tone that follows the main result. Every sound also appears as text.',\n    }),\n    h(Check, {\n      label: 'Vibration for changes', checked: s.vibration, onChange: set('vibration'),\n      hint: vibrateSupported\n        ? 'Short buzzes when something changes. Every buzz also appears as text.'\n        : 'This browser cannot vibrate from a web page (iPhones and most computers cannot). Text and sound still work.',\n    }),\n    h(\n      'div',\n      { style: { display: 'flex', flexWrap: 'wrap', gap: 12, alignItems: 'center', marginTop: 8 } },\n      h('button', { type: 'button', style: S.button, onClick: () => { resetSettings(); if (props && props.onReset) props.onReset(); } }, 'Reset all settings'),\n    ),\n    h('p', { style: S.small }, 'Saved on this device only, and shared by every LogueBio tool. Nothing is sent anywhere.'),\n  );\n}\n",
    "packages/access/settings.js": "// One settings source for every LogueBio tool.\n//\n// Saved in a cookie so a person's choices follow them from tool to tool:\n// in development every tool is a different localhost port, and ports share\n// cookies; in production the cookie is set for .loguebio.com, which all the\n// tool subdomains share. Nothing is sent to a server; the cookie is only read\n// by the page. localStorage keeps a copy in case cookies are blocked.\n\nimport { useSyncExternalStore } from 'react';\n\nexport const SETTINGS_VERSION = 1;\nconst COOKIE = 'loguebio_access';\nconst STORAGE_KEY = 'loguebio.access.v1';\n\n/** @type {import('./index').AccessSettings} */\nexport const DEFAULT_SETTINGS = Object.freeze({\n  theme: 'system',\n  contrast: 'normal',\n  palette: 'standard',\n  textSize: 100,\n  spacing: 'normal',\n  motion: 'system',\n  autoplay: 'auto',\n  simpler: false,\n  readingTime: 'normal',\n  guidance: 'beginner',\n  sound: false,\n  vibration: false,\n});\n\nconst CHOICES = {\n  theme: ['system', 'light', 'dark'],\n  contrast: ['normal', 'high'],\n  palette: ['standard', 'tritan'],\n  textSize: [100, 125, 150, 200],\n  spacing: ['normal', 'wide'],\n  motion: ['system', 'reduce', 'allow'],\n  autoplay: ['auto', 'never', 'always'],\n  readingTime: ['normal', 'longer'],\n  guidance: ['beginner', 'expert'],\n};\n\n/** Keeps only known keys with allowed values; anything else falls back to the default. */\nexport function sanitizeSettings(input) {\n  const out = { ...DEFAULT_SETTINGS };\n  if (!input || typeof input !== 'object') return out;\n  for (const key of Object.keys(CHOICES)) {\n    if (CHOICES[key].includes(input[key])) out[key] = input[key];\n  }\n  for (const key of ['simpler', 'sound', 'vibration']) {\n    if (typeof input[key] === 'boolean') out[key] = input[key];\n  }\n  return out;\n}\n\nfunction cookieDomain() {\n  if (typeof location === 'undefined') return '';\n  const h = location.hostname;\n  return h === 'loguebio.com' || h.endsWith('.loguebio.com') ? '; Domain=.loguebio.com' : '';\n}\n\nfunction readRaw() {\n  if (typeof document === 'undefined') return null;\n  try {\n    const m = document.cookie.match(new RegExp('(?:^|; )' + COOKIE + '=([^;]*)'));\n    if (m) return JSON.parse(decodeURIComponent(m[1]));\n  } catch {\n    /* unreadable cookie: fall through */\n  }\n  try {\n    const s = localStorage.getItem(STORAGE_KEY);\n    if (s) return JSON.parse(s);\n  } catch {\n    /* storage blocked */\n  }\n  return null;\n}\n\nlet current = DEFAULT_SETTINGS;\nlet loaded = false;\nconst listeners = new Set();\n\nfunction load() {\n  const raw = readRaw();\n  const next = sanitizeSettings(raw && raw.v === SETTINGS_VERSION ? raw.s : null);\n  if (JSON.stringify(next) !== JSON.stringify(current)) current = Object.freeze(next);\n  loaded = true;\n}\n\nfunction emit() {\n  for (const l of listeners) l();\n}\n\n/** Current settings (read once from the cookie on first use). */\nexport function getSettings() {\n  if (!loaded && typeof document !== 'undefined') load();\n  return current;\n}\n\n/** Saves a change and tells every subscriber, including other tabs of the same tool. */\nexport function updateSettings(partial) {\n  const next = Object.freeze(sanitizeSettings({ ...getSettings(), ...partial }));\n  current = next;\n  const payload = JSON.stringify({ v: SETTINGS_VERSION, s: next });\n  try {\n    const secure = typeof location !== 'undefined' && location.protocol === 'https:' ? '; Secure' : '';\n    document.cookie =\n      COOKIE + '=' + encodeURIComponent(payload) + '; Path=/; Max-Age=31536000; SameSite=Lax' + cookieDomain() + secure;\n  } catch {\n    /* cookies blocked */\n  }\n  try {\n    localStorage.setItem(STORAGE_KEY, payload);\n  } catch {\n    /* storage blocked */\n  }\n  try {\n    if (channel) channel.postMessage('changed');\n  } catch {\n    /* ignore */\n  }\n  emit();\n}\n\nexport function resetSettings() {\n  updateSettings(DEFAULT_SETTINGS);\n}\n\nlet channel = null;\nlet wired = false;\nfunction wire() {\n  if (wired || typeof window === 'undefined') return;\n  wired = true;\n  const reload = () => {\n    const before = current;\n    load();\n    if (before !== current) emit();\n  };\n  try {\n    channel = new BroadcastChannel('loguebio-access');\n    channel.onmessage = reload;\n  } catch {\n    channel = null;\n  }\n  window.addEventListener('storage', (e) => {\n    if (e.key === STORAGE_KEY) reload();\n  });\n  // Another tool (another port or subdomain) may have changed the cookie while this tab was hidden.\n  document.addEventListener('visibilitychange', () => {\n    if (document.visibilityState === 'visible') reload();\n  });\n  window.addEventListener('focus', reload);\n  for (const q of ['(prefers-reduced-motion: reduce)', '(prefers-color-scheme: dark)', '(prefers-contrast: more)']) {\n    try {\n      window.matchMedia(q).addEventListener('change', emitSystem);\n    } catch {\n      /* old browsers */\n    }\n  }\n}\n\nlet systemVersion = 0;\nfunction emitSystem() {\n  systemVersion++;\n  emit();\n}\n\nexport function subscribeSettings(listener) {\n  wire();\n  listeners.add(listener);\n  return () => listeners.delete(listener);\n}\n\nfunction media(q) {\n  try {\n    return typeof window !== 'undefined' && window.matchMedia(q).matches;\n  } catch {\n    return false;\n  }\n}\n\n/**\n * Turns choices into what the interface should do, combining the person's\n * declared choices with their system settings. What the person declares wins.\n */\nexport function resolveSettings(s) {\n  const systemReduce = media('(prefers-reduced-motion: reduce)');\n  const reducedMotion = s.motion === 'reduce' || (s.motion === 'system' && systemReduce);\n  const dark = s.theme === 'dark' || (s.theme === 'system' && media('(prefers-color-scheme: dark)'));\n  const highContrast = s.contrast === 'high';\n  const autoplay = s.autoplay === 'always' ? true : s.autoplay === 'never' ? false : !reducedMotion;\n  return {\n    settings: s,\n    reducedMotion,\n    dark,\n    highContrast,\n    autoplay,\n    paletteName: highContrast ? 'high-contrast' : s.palette,\n    /** Multiplier for how long messages stay and how far apart announcements are. */\n    readingFactor: s.readingTime === 'longer' ? 2.5 : 1,\n    beginner: s.guidance === 'beginner',\n    systemContrastMore: media('(prefers-contrast: more)'),\n  };\n}\n\nlet resolvedCache = { key: '', value: null };\nfunction getResolved() {\n  const s = getSettings();\n  const key = JSON.stringify(s) + ':' + systemVersion;\n  if (resolvedCache.key !== key) resolvedCache = { key, value: resolveSettings(s) };\n  return resolvedCache.value;\n}\n\nconst serverResolved = Object.freeze({\n  settings: DEFAULT_SETTINGS,\n  reducedMotion: false,\n  dark: false,\n  highContrast: false,\n  autoplay: false, // never start before the page knows the person's settings\n  paletteName: 'standard',\n  readingFactor: 1,\n  beginner: true,\n  systemContrastMore: false,\n  server: true,\n});\n\n/** React hook: the person's settings, resolved against their system preferences. */\nexport function useAccess() {\n  return useSyncExternalStore(subscribeSettings, getResolved, () => serverResolved);\n}\n\n/** Writes the settings onto <html> as data attributes for CSS to use. */\nexport function applySettingsToDocument(resolved) {\n  if (typeof document === 'undefined') return;\n  const el = document.documentElement;\n  el.dataset.theme = resolved.dark ? 'dark' : 'light';\n  el.dataset.contrast = resolved.highContrast ? 'high' : 'normal';\n  el.dataset.motion = resolved.reducedMotion ? 'reduce' : 'allow';\n  el.dataset.spacing = resolved.settings.spacing;\n  el.dataset.palette = resolved.paletteName;\n  el.dataset.simpler = resolved.settings.simpler ? 'true' : 'false';\n  el.dataset.textSize = String(resolved.settings.textSize);\n  el.style.setProperty('--access-text-scale', String(resolved.settings.textSize / 100));\n}\n\nexport { ACCESS_BOOT_SCRIPT } from './boot.js';\n",
}  # {relative path: content}
STARTER = {
    APP + "/app/page.tsx": "To get started, edit the page.tsx file.",
    APP + "/app/globals.css": "--background: #ffffff;",
    APP + "/README.md": "bootstrapped with [`create-next-app`]",
}
REPLACED = {"page": APP + "/app/page.tsx", "styles": APP + "/app/globals.css", "readme": APP + "/README.md"}
LAYOUT = APP + "/app/layout.tsx"
LAYOUT_EDITS = [
    ("layout-import", "import the settings boot script",
     'import { SuiteNav } from "@repo/suite";\n',
     'import { SuiteNav } from "@repo/suite";\nimport { ACCESS_BOOT_SCRIPT } from "@repo/access/boot";\n'),
    ("layout-title", 'tab title "Condensate Lab"',
     '  title: "Create Next App",\n  description: "Generated by create next app",\n',
     '  title: "Condensate Lab",\n  description:\n    "Watch proteins and RNA gather into droplets (phase separation), test whether they are liquid with FRAP, and see how disease mutations harden them. A simplified model for learning.",\n'),
    ("layout-head", "apply saved settings before first paint",
     '      <body className="min-h-full flex flex-col"><SuiteNav />',
     '      <head>\n        <script dangerouslySetInnerHTML={{ __html: ACCESS_BOOT_SCRIPT }} />\n      </head>\n      <body className="min-h-full flex flex-col"><SuiteNav />'),
]
PKG = APP + "/package.json"
ROOT_README = "README.md"
RR_OLD = '  suite/              tool list, ports, URLs and the "All tools" link (@repo/suite)\n'
RR_NEW = RR_OLD + '  access/             shared settings, palette and screen-reader announcer (@repo/access)\n'
OPTIONAL = {"check-types"}


class Abort(Exception):
    pass


def find_root(start):
    d = os.path.abspath(start)
    while True:
        if os.path.isfile(os.path.join(d, APP, "package.json")):
            return d
        parent = os.path.dirname(d)
        if parent == d:
            return None
        d = parent


def read(root, rel):
    with open(os.path.join(root, rel), encoding="utf-8", newline="") as f:
        return f.read()


def exists(root, rel):
    return os.path.isfile(os.path.join(root, rel))


def line_of(text, idx):
    return text.count("\n", 0, idx) + 1


def plan(root, skip):
    """Returns (writes, report). writes: {rel: new text}; nothing is written here."""
    if not os.path.isfile(os.path.join(root, "packages/suite/package.json")):
        raise Abort("packages/suite is missing. Apply suite_nav.py first (it adds the shared \"All tools\" link).")
    writes, report = {}, []

    def new_files(eid, title, prefix_test):
        rels = [r for r in FILES if prefix_test(r)]
        todo = [r for r in rels if not (exists(root, r) and read(root, r) == FILES[r])]
        clash = [r for r in todo if exists(root, r)]
        if clash and eid == "access-package":
            raise Abort(f"[{eid}] {clash[0]} already exists with different content. Move it aside first.")
        if clash and eid == "app-files":
            raise Abort(f"[{eid}] {clash[0]} already exists with different content (not the starter). Move it aside first.")
        if eid in skip:
            report.append((eid, title, "skipped", None))
            return
        for r in todo:
            writes[r] = FILES[r]
        report.append((eid, f"{title} ({len(rels)} files)", "already" if not todo else "apply", None))

    new_files("access-package", "packages/access", lambda r: r.startswith("packages/access/"))
    new_files("app-files", "components and lib", lambda r: r.startswith(APP + "/components/") or r.startswith(APP + "/lib/"))

    for eid, rel in REPLACED.items():
        title = rel
        if eid in skip:
            report.append((eid, title, "skipped", None))
            continue
        cur = read(root, rel) if exists(root, rel) else None
        if cur == FILES[rel]:
            report.append((eid, title, "already", None))
            continue
        if cur is not None and STARTER[rel] not in cur:
            raise Abort(f"[{eid}] {rel} is not the create-next-app starter any more, so it was not replaced. Move it aside or --skip {eid}.")
        writes[rel] = FILES[rel]
        report.append((eid, title + (" (replaces starter)" if cur else " (new)"), "apply", 1))

    text = read(root, LAYOUT)
    for eid, title, old, new in LAYOUT_EDITS:
        if eid in skip:
            report.append((eid, f"{LAYOUT}: {title}", "skipped", None))
            continue
        if new in text:  # replacement first: it contains its own anchor
            report.append((eid, f"{LAYOUT}: {title}", "already", line_of(text, text.find(new))))
            continue
        n = text.count(old)
        if n != 1:
            raise Abort(f"[{eid}] anchor for '{title}' found {n} times in {LAYOUT} (expected 1).")
        i = text.find(old)
        text = text[:i] + new + text[i + len(old):]
        report.append((eid, f"{LAYOUT}: {title}", "apply", line_of(text, i)))
    if text != read(root, LAYOUT):
        writes[LAYOUT] = text

    raw = read(root, PKG)
    pkg = json.loads(raw)
    changed = False
    deps = pkg.setdefault("dependencies", {})
    if "deps" in skip:
        report.append(("deps", f"{PKG}: @repo/access", "skipped", None))
    elif deps.get("@repo/access") == "*":
        report.append(("deps", f"{PKG}: @repo/access", "already", None))
    else:
        deps["@repo/access"] = "*"
        changed = True
        report.append(("deps", f"{PKG}: @repo/access", "apply", None))
    scripts = pkg.setdefault("scripts", {})
    if "check-types" in skip:
        report.append(("check-types", f"{PKG}: check-types script (optional)", "skipped", None))
    elif "check-types" in scripts:
        report.append(("check-types", f"{PKG}: check-types script (optional)", "already", None))
    else:
        scripts["check-types"] = "tsc --noEmit"
        changed = True
        report.append(("check-types", f"{PKG}: check-types script (optional)", "apply", None))
    if changed:
        writes[PKG] = json.dumps(pkg, indent=2) + "\n"

    if "root-readme" in skip:
        report.append(("root-readme", "README.md: packages/access", "skipped", None))
    else:
        rr = read(root, ROOT_README)
        if RR_NEW in rr:
            report.append(("root-readme", "README.md: packages/access", "already", line_of(rr, rr.find(RR_NEW))))
        else:
            n = rr.count(RR_OLD)
            if n != 1:
                raise Abort(f"[root-readme] anchor (the packages/suite line) found {n} times in README.md (expected 1). Use --skip root-readme.")
            report.append(("root-readme", "README.md: packages/access", "apply", line_of(rr, rr.find(RR_OLD)) + 1))
            writes[ROOT_README] = rr.replace(RR_OLD, RR_NEW)
    return writes, report


def print_report(report, dry):
    print(("Dry run: nothing will be written.\n" if dry else "") + "Edits:")
    for eid, title, status, line in report:
        where = f" (line {line})" if line else ""
        print(f"  [{eid}] {title}{where}: {status}")


def apply(root, writes):
    stamp = time.strftime("%Y%m%d-%H%M%S")
    state = {"stamp": stamp, "created": [], "backups": {}}
    sp = os.path.join(root, STATE)
    if os.path.exists(sp):
        with open(sp, encoding="utf-8") as f:
            old = json.load(f)
        state["created"] = old.get("created", [])
        state["backups"] = old.get("backups", {})
    for rel, text in writes.items():
        p = os.path.join(root, rel)
        if os.path.exists(p):
            if rel not in state["backups"] and rel not in state["created"]:
                bak = f"{rel}.bak-{stamp}"
                with open(p, "rb") as src, open(os.path.join(root, bak), "wb") as dst:
                    dst.write(src.read())
                state["backups"][rel] = bak
        else:
            if rel not in state["created"]:
                state["created"].append(rel)
            os.makedirs(os.path.dirname(p), exist_ok=True)
        with open(p, "w", encoding="utf-8", newline="") as f:
            f.write(text)
    with open(sp, "w", encoding="utf-8") as f:
        json.dump(state, f, indent=2)
    return state


def revert(root):
    sp = os.path.join(root, STATE)
    if not os.path.exists(sp):
        print("Nothing to revert: this script has not been applied here.")
        return 0
    with open(sp, encoding="utf-8") as f:
        state = json.load(f)
    for rel, bak in state["backups"].items():
        b = os.path.join(root, bak)
        if not os.path.exists(b):
            print(f"Backup missing, left as is: {bak}", file=sys.stderr)
            continue
        os.replace(b, os.path.join(root, rel))
    for rel in sorted(state["created"], key=len, reverse=True):
        p = os.path.join(root, rel)
        if os.path.exists(p):
            os.remove(p)
        d = os.path.dirname(p)
        while d.startswith(root) and d != root and os.path.isdir(d) and not os.listdir(d):
            os.rmdir(d)
            d = os.path.dirname(d)
    os.remove(sp)
    print(f"Reverted: {len(state['backups'])} files restored, {len(state['created'])} new files removed.")
    print("Next: npm install")
    return 0


def main():
    ap = argparse.ArgumentParser(description="Install the real Condensate Lab and packages/access.")
    ap.add_argument("--path", help="repo root (default: found from the current folder)")
    ap.add_argument("--dry-run", action="store_true", help="list each edit; write nothing")
    ap.add_argument("--diff", action="store_true", help="show the changes to existing files; write nothing")
    ap.add_argument("--revert", action="store_true", help="undo everything this script did")
    ap.add_argument("--skip", action="append", default=[], metavar="ID", help="skip an edit (repeatable)")
    a = ap.parse_args()
    root = os.path.abspath(a.path) if a.path else find_root(os.getcwd())
    if not root or not os.path.isfile(os.path.join(root, APP, "package.json")):
        print(f"Could not find {APP}. Run inside the repo or pass --path.", file=sys.stderr)
        return 1
    if a.revert:
        return revert(root)
    try:
        writes, report = plan(root, set(a.skip))
    except Abort as e:
        print(f"Aborted, nothing written: {e}", file=sys.stderr)
        return 1
    if a.dry_run or a.diff:
        print_report(report, True)
        if a.diff:
            for rel, text in writes.items():
                if exists(root, rel):
                    old = read(root, rel).splitlines(keepends=True)
                    sys.stdout.writelines(difflib.unified_diff(old, text.splitlines(keepends=True), rel, rel + " (new)"))
                else:
                    print(f"+++ new file {rel} ({len(text.splitlines())} lines)")
        return 0
    if not writes:
        print_report(report, False)
        print("\nEverything is already applied.")
        return 0
    apply(root, writes)
    print_report(report, False)
    print(f"\nWrote {len(writes)} files. Backups end in .bak-<time>; undo with --revert.")
    print("Next: npm install, then npm run dev and open http://localhost:3005")
    return 0


if __name__ == "__main__":
    sys.exit(main())
